INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('9','A','47','A','原宿 外苑','Mrs.GREEN APPLEの曲が好き！','なぜミセスの曲はみんなに人気なんだろう？','使われている歌詞の言葉が心に響くのかもしれない','本探究では、ミセスの曲の魅力を明らかにする。','みんなが好きなミセスの歌詞を調査する。','音楽、国語、社会','人気曲の共通点がわかり、流行に敏感になるかも','調査方法についていろいろな方法を知りたい','流行の曲はどうして流行っているのか','人間が好む特定のリズムがあるのではないか？音楽で実験してみてはどうか（◎◎）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','1','A','','絵を描くことが好き！','絵を描いている時にどんな工夫をしている？','影の書き方とか、体の書き方も工夫かもしれない','絵を作る難しさ／絵を作っている途中の美しさを明らかにする','みんなの（美しさ的）好きなマンガ／アニメを聞いて見る','美術','絵を上手な人増えると、絵を見ている時にその絵てどういうこと説明している／表しているを簡単に見つける','他の人にとっていっぱいなことを表している絵をその人にとって何の気持ちを表していると思っていると聞いて見る','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','2','A','','長距離が速くなりたい！','長距離が速くなるにはどうすればいいだろう？タイムには体調や天候、気温も関係あるのであろうか','短距離のフォームとは違うフォームで走るといいかもしれない','本探求では長距離の歴史を知り、長距離はどうしたら速くなるのかを明らかにする','長距離の選手と自分を比較し、どう違うのかやどこを改善すればいいだろうかを知り、実験してみる','保険、体育、社会、数学','部活の大会でいい結果を残せる。 ・体育の授業や体力測定の時に有利 ・歴史をマメ知識で知れて友達に教えたら友達も速くなるかも！？','まず、選手の走り方の特徴などを知る','長距離はどうしたら速くなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','3','A','','','','','','','、','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','4','A','','成長期が終わるまでに身長を伸ばすには？','身長を伸ばすには何をすればいいのだろうか。身長はどんなものと関係するのだろうか。成長期が終わっても身長は伸びる？→成長期っていつ頃？','運動、「食べ物」、「生活」、DNA、遺伝子','','','体育、理科、数学','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','5','A','','ゲームが楽しい','なぜゲームは楽しいのだろうか。','ストーリーなどが良いから','なぜゲームは楽しいのか明らかにする。','ネットなどで調べる','技術、国語','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','6','A','','スポーツが好きです！','色々なスポーツの起源は何だろう？','人々の娯楽として作られたのかもしれない','本探求では色々はスポーツ起源やルールを明らかにし  自分が好きなスポーツ以外でのスポーツで楽しさを見つける。','皆が好きなスポーツを調査しそれを調べ始めてやる  スポーツもあるかもしれないが実践してみる','社会、体育','皆の好きなスポーツが何か分かり  自分の「好き」にも向き合えるようになるかも。','みんなにアンケートを取り  皆の好きなスポーツを調査する。  始めてやるスポーツもあるかもしれないが実践する。','色々なスポーツの起源やルールを調査して、  自分の新しい「好き」を見つける。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','7','A','','惑星を壊すゲームにはまってる','地球を変形させたらどうなるだろう','人が住めなくなるかも','本探究では地球の形を様々にし、どんなことが起きるのか明らかにしたい。','みんなが住んでいる地球がもし丸じゃなくて様々な形になったらどうなるのか、まず重力について調査したい','理科 数学','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','8','A','','自分の体力が少ない','簡単な方法で体力が強くなるのか','体力が多くなる方法は大変なのかもしれない。','本探求では自分でもできる簡単な方法で体力が強くなるのかを調べる','実際の運動神経がよい人や体力が多い人の運動法を参考にして自分なりに毎日できるようにアレンジする','保体、数学','','','自分でできる体力がUPする方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','9','A','','絵が上手に描けるようになりたい','絵のバランスが取れないのはなぜか？','絵のバランスを上手に取る方法はあるのか？','本探求では、絵のバランスを上手に取る練習方法を見つけたい。','絵のバランスを上手に取れる練習方法やそのためにすることを調べる。','美術、国語、社会、','字のバランスがとれるようになる','自分に合った練習方法を見つける','絵のバランスをとる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','10','A','','バスケットボールが好き','vcn','外国に旅行に行った人がバスケットボールを面白いと思いに','','','','','','','');
