INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','12','A','','英語が楽しい！','なぜ日本の学校には英語の授業があるのだろう','もしかして世界で最も使われている言語なのかも。','本探求で英語がなぜ最も使われている言語なのかを明らかにする。','みんなが英語を喋れるために、簡単な言葉や勉強の仕方を調査する。','英語','みんな英語がうまくなって英語が楽しいって言ってくれるかもしれない。','自習をして自分に合う勉強法を調べてから、友達にどんな勉強法をしているか聞く。','英語をネイティブのように喋れる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','13','A','','テニスをうまくなりたい','テニスがうまい人の特徴は','もしかして自分とは違う練習方法をしてるかも','自分の部活の練習方法と上手い人の練習方法を比較する','部活のコーチやネットで調べる','体育','テニスが上手くなるのと部活の練習方法が増えるかも','最初は練習方法を調べる','テニスの上達について','');
