INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','15','A','','亀が好き!!!!!!!!!!!!🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢','亀の種類などを詳しく知りたい🐢🐢🐢🐢🐢🐢🐢🐢','もしかしたらめっちゃでかい亀の種類があるのかも🐢🐢🐢🐢🐢🐢🐢🐢🐢','本探求ではいろいろな亀の種類やとくちょう、飼っている亀のことを詳しく調べ、明らかにする🐢🐢🐢🐢🐢🐢🐢🐢🐢','みんなは亀が好きなのか、嫌いなのか、又はどちらでもないのか','理科','みんなが亀の魅力を知り、亀が好きになってくれる','まずは家で飼っている亀について','亀について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','16','A','','おばさんは何故若いことにこだわるのか','そもそも若く見えるわけがないのに年齢を偽るから','若い頃の時代に戻りたいからかも','何故おばさんは若いころが一番記憶に残るのかを明らかにしたい','AIとかに聞く（おばさんとかに聞くのは失礼だから）','道徳','みんなが何故おばさんが若いことに執着するか知ってもらえるかも','僕のままに何故若いことに執着をするか聞く','おばさんたちは何故若いころに執着するのか','');
