INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','18','A','','今バスケにはまってる','バスケがうまい人の特徴','色々な練習方法があるかもしれない','シュートやドリブルをうまくなりたい','うまい人の練習方法を見る','体育','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','19','A','','音楽を聴くのが好き！集中力がない！(家での勉強が続かない！！)','どうしたら集中力を高めることができるのか','好きなこと(音楽)をしながらなら集中できるかもしれない！','本探究では、音楽を聴きながら勉強することで集中力が上がるのかについて明らかにする。','調べる。→実際にやってみる、試してみる！(家で)','音楽、保健','集中力が高まって、勉強ができるようになるかもしれない！家での勉強がはかどるかも！？','','音楽を聴くことで集中力が高まるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','20','A','','生物が好き','生物はなぜ生まれたのかその起源は何か？それはどこからやってきたのか？','もしかしたら宇宙からのウイルスが地球で進化して生命が生まれたのかも','この探求で、生物の原点が何かを知れている状態にしたい','生物学をある程度勉強し、て一番最初にいた生物について調べて考えていく','理科','人間や動物が何から生まれてきたのかが分かる。','いろいろな先生と話して、より良い調査方法を聞いて参考にして、調査をしていきたい。','～何もない時代からなぜ生命が生まれたのかについて～','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','21','A','','空を飛べるようになりたい','なぜ人は空を飛べないのだろう','飛行機の特徴に合わせれば、飛べるかも','本探求では、どのようにしたら空を飛べるかを明確にする','飛行機の特徴を調べ、飛行機に合わせていき実行してみる','理科','未来の空飛ぶ車を早く開発できるかもしれない','飛行機の特徴を調べる。','人は飛行機を真似したら、空を飛べるかもしれない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','22','A','','生物が好き','なぜ生物についてわかっていないことが多いのだろう？','それだけ生物の進化が不思議なのかもしれない','本研究では生物の生態をちょっと明らかにする','実際に動物や虫の４体を集めて解剖する','理科','もしかしてだけどもしかしてだけそれって生物の何かを知れるんじゃないの','４体収集や解剖学について研究していきたい','ガ～ガキのやる解剖について～','');
