INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','28','A','','バスケのシュート率、ドリブル、を上達させたい','','実は簡単だと思っていたスポーツが難しかったり難しいと思っていたスポーツがかんたんだったりするかも','本探求ではスポーツの楽しさ、難しさを明らかにする','調べるスポーツをするときにやっている人に、楽しさ、こんなところが難しいを教えてもらう','体育','いろんなスポーツの楽しさがわかりそのスポーツにはまるかもしれない','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','29','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','1','A','','心理テストめっちゃ当たる','話したこともない人がなんでこんなに私のことを言い当てるの？','もしかして誰でも当てはまるものなのかも！','本探究では、なぜ自分が当てはまってると思うのか、だれにでもあてはまるものなのかを明らかにする','自分が当てはまってると錯覚しているのか、あっていたとしたらなぜわかるのか、友達に心理テストをしてみて自分の性格とあっていたかをアンケートする','たぶん何でもない','相手の行動の理由がわかるかも！！','まずは自分で心理テストをやってみて当てはまっているか、心理テストは本当に当てはまっているのか','心理テストの真実！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','2','A','','テニスを上達したい！','サーブ、ラリー上達の仕方。テニスがうまい人の特徴。','たくさん練習したり、特別ないい練習法があるのかも','本研究では、テニスの歴史や、先輩や選手を見てサーブの強いやり方など、コーチとかを見ながら練習法とか正しいフォームやうまい人の特徴をあきらかにしたい。','うまい選手とかとかをよく観察して細かい動き方を見てみる','保険体育、歴史、','部活とかでテニスがうまくなれるし、うまくなったら先輩に迷惑をかけなくてよくなるかもしれないかも。','コーチとかうまい先輩をよく見て観察する。','テニスが上達する練習法について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','3','A','','私生活で左も使えるようになりたい 両利きになりたい','右手がけがをしても左手で生活したい','左を使えた方が生活が楽になるかも','本研究では左手を使えるようになったら私生活はどれほど楽になるかまたどれほど上達するかを調べる','左利きの人の人にインタビュー，動画を見る','保体、理科？','私生活，部活でも楽になる','左利きの人を見る','どうやったら早く、うまく左を使えるか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','4','A','','サッカーがもっとうまくなりたい','なぜプロの選手はあんな簡単に相手を抜くのだろう？','プロのうまい選手は全員ほとんど同じようなプレーをしている？','本探求では、うまい選手はどのようなプレーをしているのかを調べて実践してを繰り返してうまくなる方法を明らかにする','うまい選手のドリブルの仕方や顔のあげ方などを調べる','体育、数学','共通点を見つけ、うまくなる方法を知れる？','具体的に、どんなドリブルの仕方をしているのかについて調べる','サッカーで主にドリブルがうまくなる方法について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','5','A','','インターネット中毒になったことがある','なぜインターネット中毒になる？','面白いから','本研究ではどこでだれがいつこのような規制や制限をつくったのか。なぜこんなにインターネット社会になってしまったのか。人の心理と問題について明きらかにする。','政治、国民の声について調べる アンケートを取る','図書、道徳、歴史','時間の使い方がうまくなるかも','情報収集の仕方、アンケートの取り方','人の欲','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','6','A','','自分でプロバスケチームを作ってみたい','どうやってプロチームを作っているの？','もしかしたらその人たちも前の人から学んでいるかも','本探求では、プロバスケチームを作るための基本を調べる。','作るだけじゃなく、強くしたいし、自分のバスケにも落とし込みたい','社会、数学、体育','バスケチームの裏側が分かり、もっとバスケが好きになるかも！','調査方法を参考にしてみたい','バランスの良い夢のバスケチームを作る！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','7','A','','K-popのアイドルが好き','K-popはなんでいろんな国で人気なのか？','K-popには独自の戦略があって人気なのかもしれない','K-popが人気なのはどんな戦略があるからなのかを明らかにする','・K-popの歴史から人気になった理由をつきとめる・過去のグループをもとにK-popにはどんな傾向があって人気なのか','社会、音楽、体育','世の中ではどんなものが人気になるのかの傾向が分かる','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','8','A','','大森元貴のギターにあこがれた','気軽に練習するにはどうすればいいのだろう','かっこいいから','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','9','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','10','A','','ダンスが好き。もっと上手になりたい。上達したい。','ダンスが上手な人はどのようなことを練習しているのか','もしかしたら踊ることより基礎をやっているのかも','基礎と柔軟を中心として自分らしいダンスを見つける。','上手な人のダンスの動画をいっぱい見て研究する。','保体、音楽、','自分に向き合えて自分だけのダンスが出来るかも','ダンスの先生に聞く。ダンスのお友達にも聞いてみる。','ダンスが上達するためには何が必要で自分らしいダンスができるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','11','A','','海について','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','12','A','','左足を右足と同じぐらい強く打てるようになりた。','プロのサッカー選手は大体両足が使えるのか？','もしかしたら右足と同じようにけれないかもしれない。','この探求で練習すれば左足が使えるようになる。そして普段のサッカーでもそれを生かしたい','右足のホームを見てそれを意識してさらに手の位置や足の踏み込みなどを見て、見よう見まねでやる。','体育','左足を使えるようになることで、サッカーの試合でも左側にドリブルが出来てさらにシュートも打てるようになる。','左足のシュートがうまい人や左利きの人にコツを聞いてそれを参考にしながらやる。','左足を使えるようになる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','13','A','','勉強って必要なの？','なんで人生では勉強したことをほぼ使わないのに勉強しないといけないのか','考える力をつけるため？','勉強はなんで人生で必要ないといわれているのか、勉強をするメリットデメリットなど','インターネットで調べたり、勉強をやっていてよかったと思うことを友達とかに聞く','国語、数学、理科、社会、英語？','勉強をやる意味がわかって、勉強しよう！っていう気持ちになるかもしれない！！','データで調べる','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','14','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','15','A','','深海のなぞが気になる','なぜ地球の表面の七割は海なのに、月や火星などよりもわかっていないのか？？','‘‘七割‘‘って言ってるくらいだからそれだけ大きいってことだし、とても深い場所もあるから調べられないから？','深海のなぞをできるだけ誰よりも知る！！！！','まずはネットで調べる！！','理科：（地学、生物）  物理、技術：（最後らへんで深海だから、その深海の超高圧に耐えるためはどのようなモノ？が必要か）  地理：（海洋ゴミ問題など！！資源問題など！！）','知識が身につく！！生物や地学の知識だけでなく、それを解決するための「ロボット」や、環境、資源といった「社会」の知識までいろんな知識が得られる？','まずは深海を軽く調べたい！！','深海のなぞについて！！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','16','A','','スポーツが好き','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','17','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','18','A','','ゲームが好き','なぜ人はゲームに熱中するの？','ガチャやレベルアップが関係している？','なぜ人はゲームに熱中してしまうのか、その理由。人気なゲーム','人気なゲームを調べたり、みんなに聞く','理科','人気なゲームを楽しめて、ゲームより楽しくやる','みんなが好きなゲームを聞いて、なぜ好きなのかを聞く','なぜ人はゲームに熱中してしまうのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','19','A','','なぜプロ野球選手インコースが打つのが上手なのか','なぜプロ野球選手インコースが打つのが上手なのか','もしかしたらみんな何かの共通点があるかも','インコースを打てる高校生プロ野球選手の共通点を明らかにする','実際にプロ野球選手が打撃しているときのの動画を見る','体育','プロ野球選手の特徴がわかる','調査方法について色々な方法が知りたい','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','20','A','','足速くなりたい！！！','足速い人には共通点があるのか','みんなフォームが一緒なのか、、、','本探求足の速さの秘訣を明らかにする','毎月トレーニングを変えて一番効果のあったと思うやつも探す。','体育','足が速くなる','実践する','最短で足が速くなるには、、、！！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','21','A','','体力と足の速さの両方を向上させたい。','体力と足の速さの両方を一度に鍛えられるトレーニングはあるのか。','300ｍとか400ｍを全力で走ればいいのかも。','体力と足の速さの両方を鍛えられる方法を明らかにする。','実際にいくつかのトレーニングをしてみて、何もしていない状態の記録とトレーニングを行った後の記録を比べる。','体育','大会や体力テストなどでいい記録が出せる。','トレーニング法を調べる。','体力と足の速さの両方を一度に鍛えられるトレーニング法はあるのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','22','A','','流行の服がすき。','服の流行はどのようにできているの','','流行の服は、どのようにできているのかを明らかにしたい。','ケーポップや、他のアイドルの服も研究したい。','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','23','A','','ソフテニがうまくなって、試合でたくさん勝ちたい！','上手な人たちはどのように練習に取り組んできた？うまい人がたくさんやってる練習はなにか？','ラケットの振り方とか、足の動かし方のいい練習法とかがあって家とかでもたくさん練習してる？','本探究では、自分のやったことのない練習法をたくさん試してみて、自分の課題であるストロークとサーブにあう効率のいい練習法を明らかにする。','たくさんの練習方法とかを調べて実際にやってみて、いいと思ったのを記録したりして夏休み中などを使ってたくさんやる。また、それが何にいいのかを調べたりする。','体育','新人大会で少し練習の成果が出るかも。','自分の課題をすべて出して苦手なことも考える。','自分の苦手なサーブとストロークを完璧に！～ソフトテニス～','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','24','A','','本格的なプログラミングでゲームをつくりたい','どのようにすれば上達する？','上達にはプロに教えてもらったりとても長い時間が必要かもしれない','プログラミングを上達させるためにはどのように勉強や練習をすればよいのかを明らかにする。','プロに教えてもらうのは難しいかもしれないのでインターネットなどで検索して独学','技術','プログラミングのプロになって凄いゲームを作って将来金持ち','色々な調査方法を知りたい','プログラミングを上達させよう！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','25','A','','バスケうまくなりたい','どの様に練習したらいいのか？','上手い人に聞く','自分が足りないところを探してなくす','いろんな人の意見を聞く','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','26','A','','バレーが好き！もっと上達したい！','何故かサーブが入らない、','サーブが入らないのは、腕の力がないのかもしれない。','サーブが入らない原因を追究して、追求した結果をもとにサーブが入るようになるまで練習する。','バレーの選手や、バレーの本を使って調べて、自分はそこが足りないのかを検証しながら進めていく、実際に効果を感じられたら、練習用のルーティーンに加える','体育','部活の時に、色んなことを試せる、バレーを楽しむことや、自信につながる、部活の時に、サーブ以外のものをやることにもつながる','サーブを飛ばすためにはどうすればいいのか、','サーブを飛ばすための練習方法をつくり、実際にボールの飛ぶ距離が延びるのか検証する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','27','A','','陸上競技で必要な能力を高めたい','全て鍛えられる一番効果的な練習方法は?','一気に鍛えられる練習方法はない、またはまだ解明されていない？','全部じゃなくてもいいから、できるだけ多くの能力を身につけられる練習法を明らかにする。また、それが本当なのか明らかにする。','調べて、実際に実験をしてみて、何もしてない状況と、その練習方法を何日もやったあとにまた記録をはかる。','体育 数学','部活の大会や記録会の幅広い競技でいい成績をのこせるはず。','実際に幅広い能力をもっている人にどのようなことをしているか聞いてみる。','陸上競技に必要な能力を手に入れるためにはどのような練習やトレーニングをすればいいのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','28','A','','K-popが好き！！','k-popが世界で人気なのはなぜだろう','曲だけでなく、見た目でも楽しめるから','k-popが世界で人気な理由を調べる。デビューするには何が必要か、ダンスや歌がうまくなるにはどうしたらいいかを明らかにする。','実際に行動してみて、ダンスうまくなる！！','体育、音楽','自分の夢に近づける、好きなことを深められる','k-popが世界で人気な理由を調べる','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','29','A','','寝てると気づいたら時間がとても経っている。','なぜ寝ている時は，時間が早く進むのか？','意識があまり無くてその分時間が早く進むのかも。','本探求では寝ている時はなぜ時間が早く進むのかと夢について明らかにしたい。','どのような時にどのような夢を見たかを記録し，ネットでも調べてみる。','理科，社会，保健体育','寝ることについて調べると，寝ることの大切さに気付き，健康的に生活できるかも。','インターネットで調べたり，記録する。','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','1','A','','家での勉強に集中出来ない','時間だけ過ぎて勉強が進まない','勉強する環境や集中できる時間があるのかもしれない','本探求では集中できる環境や時間については明らかにする','色々な人にその人の集中できる方法を聞く、調べて試す','理科','短時間で沢山の内容を覚えられる','','集中して効率よく勉強するには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','2','A','','Mrs.GREEN APPLEを愛してる','なんでミセスのライブのチケットはめっちゃ人気なんだろう','ライブの道具がレベチだからかも、？ライブに参加する人もしない人でも楽しめるものがあるからかも','本探求ではライブの道具のレベルとライブ人気さを明らかにする','いままであったライブの中で一番行きたいと思うライブを調査する','音楽、社会、技術、理科','これから人気のライブがあったらそれに似たライブにいけるかも！','どのライブが一番人気なのか みんながすごいと思うライブの技術はどれか','一番技術がすごいライブはどれか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','3','A','','集中力を上げたい','なんで集中し続けれないのか','人間がそもそも集中力が続かない生き物なのかも？','人間が集中力が続かない生き物なのか、続かないなら続く生き物は何か。続くなら、なぜ自分は続かないのか明らかにする。','ネットで人間が集中できる生き物なのか調べる。できるなら自分を振り返る、友達に聞く…など','理科、保体','勉強も部活も集中して取り組めるかも','データを調べる。人に聞く','人間は集中できる？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','4','A','','二塁に送球を届かせたい！！！！！！！！！','なぜ届かないのか','トレーニングや練習が必要かも？','なんで届かないのか、どんなことをするべきか、を確かめる','動画や自分のチームメイト、部活動の上手な友達やプロ選手の動きを参考にしたり真似したりする！','保体','野球のクラブチームや部活動に影響力など与えることが期待できそう。それに加えて盗塁阻止率も上がるし、得点圏への進塁を防げるから。','どういった技術を身につければいいか、どの様なトレーニングや練習方法が必要か等。','二塁送球をノーバンで届かせるには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','5','A','','バレーで連続して安定したパスを飛ばしたい！＋バレーのポジションとかについて','どうやったら安定してるパスができる？','ボールの当たる位置が悪いから⁈＋いまいちまだポジションとかがわかんない、、','バレーの当たってる場所を観察してできるだけ全部をきれいに取れるように ポジションを理解してうごけるようになりたい','うまい人の動きを見たりして真似してみる。','保体、美術？','バレーがうまくなってやっていてもっと楽しくなる！','過去の大会の動画とかを見てどんなパスがいいのかを調べてみる','バレーについて！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','6','A','','アートブロック、なぜ存在するんだろぅ。。','なんで？アートブロックが発生するの？','もしかして、手がつかれる、？脳みそが飽きる、？','なぜかをあきらかにする','ちゃんと原因を調べて自由になる','美術','解決方法も調べてみんなと楽しく絵を描く','一日何回も絵をかいてみる','アートブロックって、なあに？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','7','A','','ソフトテニスが好き、もっと上手くなりたい','なぜフォアやバックを外してしまうのか','打点に当たってないから？','本探求ではラケットの打点をボールに当てるコツを調べる','上手い人のボールとの距離や打つタイミングを見る','保体','速いボールが打てるようになる','上手い人の大会動画などを見る','ソフトテニスが上手くなる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','8','A','','英語を読み書きできるようにする。','なんで英語が読み書きできないんだろう。','昔から英語を言ってないから？','英語を言えるようにする。','家でも学校でも少しずつ英語を言えるようにする。','英語','英語が今よりもしゃべれるようになる。','英語の発音をしてノートに書く','英語が読み書きできるようにする。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','9','A','','絵がうまく描けるようになりたい','なんで練習してるのにうまくならないの？','誰でも絵がうまくなる練習法があるのか？','誰でも絵がうまく描けるようになる練習法を調べる','イラストレーターや漫画家、絵がうまい人の  練習法や書き方などを調べる','美術','絵がうまくなるかもしれない','いろんなデータを調べる。','なぜ絵がうまくならないのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','10','A','','すげーねっむい‼何で寝なきゃいけないんだよぉぉッ!!!!!!!!!!','本当になんでなんだろう...動物も寝なければ敵に襲われずに済むのに...','もしかしたらどうしても寝なければいけない理由がある...!?(案外当たり前)','本探求ではなぜ生物は寝なければいけないのか調べる','そのためにいろいろな過去の実験などをもとに生物が寝なければいけない理由を調べる','保健・理科','睡眠がどれほど大事なものかを知り、睡眠をたくさんするようになる(はず)','いろいろ過去のデータなどを調べる','なぜ生物は寝なければいけないのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','11','A','','肩を強くしたい、球速を上げたい','野球部で球速を上げたかったから','投げ方が違うのかも。筋力がほかの人より劣っているのかも。','肩が強くなる方法を明らかにする','本探求ではどうしたら肩が強くなるのかをインターネットで調べたりコーチに聞いて検証します。','体育','肩が強くなればスタメンになる可能性が上がると思うから','インターネットで調べる。コーチに聞く。','肩を強くし球速を上げるにはどのような練習法があり、どんな工夫をすればよいのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','12','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','13','A','','絵の具で絵を描けるようになりたい','何故絵の具を思ったように扱えないのだろう','何故絵の具じゃなく鉛筆やペンで書くとうまくいくのに筆になった途端思うようにいかにのだろう','絵の具を使って絵を描くことへのイライラと苦手を克服する','動画を見たり先生に聞いたり、根本的に絵の具以外の鉛筆などで描いた絵がうまくならないと行けない','美術','絵が上手くなる可能性が出きて将来の選択肢が増える。','絵がうまい人に聞いて練習方法や過程を知りたい','絵の具を使った絵を極める','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','14','A','','どうやったらコントロールがよくて試合で使ってもらえるようなピッチャーになれるのか','怪我が治ったばかりで試合に出たいがファーストやライトなどの自分がアンケートで書いたピッチャーをやりたいということをやらせてもらえないから','コントロールのいい悪いの違いは意識から変わってくるのかも？','90％まで正確になるまでやりたい','プロの投手はどのようなところにどのようなボールを集めているのかを調べて実践できるまでにしたい','保健体育','試合での登板機会が増える。いい成績を残せる','ネットで調べる','コントロールを100％に近い成功確率にするのとスライダーを極める','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','15','A','','プレゼンテーションが得意','なんであの時にプレゼン発表の時に落ちてしまったのか？','他の人が見た時(生徒)のプレゼンテーションのみんなが見ていた観点が違ったのではないのか？','生徒向けのプレゼンテーションの仕方とは？','大人だけではなく、生徒に響くようなプレゼンの作り方について。','国語・保健(？)','今後誰かにプレゼンをしたり、社会に出たりするときにプレゼンはよく使うから、その観点で役に立つ。もしかしたらそのほかの学校の活動でも役に立つかもしれない','この課題について、まず調べてみる。そこから少しづつ発展させていく・','生徒に響くプレゼンの作り方。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','16','A','','点数や評価を上げたい','なんで勉強をしたのに点数がいまいちなんだろう','勉強の量や仕方、時間で変わるのかな？','本探究では、勉強方法を明らかにする','いろんな勉強方法を試し、効果的なのを見つける','国語、数学、理科、社会','自分に合っている勉強方法が分かるし、それをみんなに広めることができる。','そもそもどういう方法があるのか','さまざまな勉強方法を試してみる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','17','A','','野球でスイングスピードを速くしたい','なんでスイングスピードが遅いのか','もっと食べなければならないのかもしれない','本探究ではどうやったらスイングスピードが速くなるかを明らかにしたい。','食べること以外に早くする方法があるか調べる','保健・体育・数学・理科','スイングスピードが上がって長打が打てる','スイングスピードが上がる方法を調べる','スイングスピードがどうしたら上がるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','18','A','','アニメ進撃の巨人のすべてを知りたい!!','なぜあんなにも話が長いのだ！全部知るのに時間がかかりすぎるだろ！','奥が深いのかもしれない','進撃の巨人の奥底まで深く知り、進撃マスターになりますぇ','・','体育、理科、歴史、地理、','この作品に対しての現実との比較ができる','あらすじ、複線、道具について全て調べる','進撃の巨人のすべてについて','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','19','A','','映画「リリーのすべて」に感動した','なんで男性から女性になったのか','性別を変えることは幸せなのか','男性から女性になったリリーの気持ちを考えたい','実在するリリーさんの生い立ちを調べて映画を見ながら考えを深める','保健体育、道徳、社会、理科','トランスジェンダーやLGBTについての考えが深まる','周りの人に知ってるトランスジェンダーの有名人を教えてもらう','LGBTQについて','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','20','A','','レイアップのシュート率を上げたい！','なぜレイアップのテストの時に3・4本を外してしまったのだろう  相手がいるとなんでレイアップが止まってしまうのだろう','ボールを当てる場所と踏み込む場所が違うのかもしれない  みんなが見ているから緊張しているのかもしれない  ディフェンスにぶつかるのが苦手だからなのかもしれない','本探求ではレイアップのシュート率をアップしたい！  相手がいても、レイアップで突っ切ってシュートしたい！','どこで踏み込んで、どこに当ててシュートするのか、どのようにしたらレイアップで突っ切れるのか  バスケに詳しい人に教えてもらう、インターネットで  調べる','体育','','探求に手伝ってくれる人を探す、レイアップのコツを調べる','レイアップのコツについて','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','21','A','','ジャンプ力がない','なんでジャンプ力がないと思ったのだろう','自分が周りの人と良く比べているから？','本探求では自分のジャンプ力がどのくらいなのかを調べる','ジャンプ力が高い人や、ジャンプの仕方について考える','体育','スポーツで何かしら有利になれそう','自分と似ている探求の人を探す。苦手なことをうまくなる方法があるか調べる.','自分のどこが苦手でどうしたら苦手じゃなくなるか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','22','A','','ゴール下のシュートをほとんど入るようにしたい','いつもなら入る距離なのに試合で、入らないのはなぜなのか？','緊張？敵ができたから？','本探求では、いつもだったら入るゴール下のシュート、なんで試合になると入らなくなるのか？','ゴール下のシュートが上手い先輩に聞くなど、、、','体育','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','23','A','','SNSが好き！最近SNSを通した事件が多い！','なんでSNSを見ていると時間がすぐに過ぎるんだろう？  SNSを使う上で事件が多くなってきているのはなぜだろう？','見ている人を飽きさせない工夫があるのかも  知らない人と話す機会になっているのかも','本探求ではSNSの工夫や歴史、事件についてを明らかにする','・SNSの歴史や工夫、事件について調べる・SNSについての本を読む・SNSについてのアンケートをする','技術・音楽・英語・社会・（国語）','SNSをコントロールできるようになるかも、SNSで事件が起きてる理由がわかるかも','調査方法についていろいろな方法が知りたい・似てようなテーマの人を探してどのようにして進めているのかを調べる','SNSが世界で復旧されてから現在に至るまでどのようなことがあったのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','24','A','','バスケ上手くなりたい','ドリブルは普通だけどシュートは下手何で？','もしかしたらちゃんと集中していない','どうしてシュートが入らないか明らかにする','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','25','A','','東京に高い建物がなぜ多いのか気になる','なんで高いビルや建物をたくさん建てるんだろう？','色んな地域や、国から注目されたいから？','本探究では、東京にはなぜ高い建物が多く建てられているのかを、明らかにする。','高い建物建てようと思ったきっかけについて調べてみる。そのあとに、なぜ東京に高い建物が多く建てられるのかを調べる。','技術','高い建物が多く建てられることについて知ることによって、高い建物の重要性が分かる。','色んなサイトを使って調べてみる。','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','26','A','','この世の国が好き','国旗の秘密','偉い人が作ってる  国の特徴を国旗に入れてる','本探求ではいろんな国旗の特徴や秘密を知る','有名なとこを調べる  共通点がありそうなとこをまとめて調べる（州とか）  本を買う','社会、美術、家庭','その国の有名なものを知れる  国旗の由来を知れる','非現実的なことを現実的に考える','仮想の国旗(国も)を作って、その国旗の特徴から国を紹介する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','27','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','28','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','29','A','','邦楽が好き','聞くタイミングや聞き手によって曲の印象に違いがでるのはなぜか、年齢によって好きな曲は変わるのか','曲の速さ、進行の仕方、声、楽器が関係してる？','本研究ではどんな楽器を使ったどんな曲がどんな時、どんな層に刺さるのかを知る','同年代の人にどんな曲が好きか、どんな時にどんな曲を聞くか聞いてみる','音楽、社会、国語','自分の気分に合わせて曲を選べるかもしれない  おすすめの曲を聞かれたときに的確なのをいえるかもしれない','同年代の人にどんな曲が好きか、どんな時にどんな曲を聞くか聞いてみる','年齢・気分によって刺さる曲は変わるのか。どんな曲を聞くのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','30','A','','抹茶が好き 抹茶の歴史が知りたい','日本ではいつから作られ、なぜ抹茶が人気なのか','すこし苦いけど甘いから人気だった １９９０年','抹茶がいつから人気で何年に作られたのか','抹茶が好きな人に聞く。','社会','人にちゃんとした抹茶の歴史やなぜ人気なのかをつたえられる。自分が知らなかった事も知れる。','抹茶が好きか聞く。','どうして嫌いな人がいるのか。いつ作られたのか','');
