INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','2','A','','漫画好き','なぜ日本の漫画は素晴らしいといわれているのか','絵柄、表現力などから考えられる','本探求は日本の漫画のどこら辺が魅力的なのか徹底調査します','海外のアニメ、漫画の好きな人たちが好きな作品の特徴を調べる','国語','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','3','A','','go言語を扱ってみたい','go言語の非同列処理net/http','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','4','A','','絵がうまくなりたい','どのような練習方をしたら絵がうまくなるのか','自分にとって絵がうまい人のまねをしながら絵をかいていたら上達するのかも','絵が上手な人はどのような技法を使っているのか 自分の画力を上達させたい','絵がうまい人(ゴッホとか)の絵の特徴を調べる。分析する','美術','絵が上達したら新しい道ができるかも','絵が上手な人はどのような技法を使っているか、どのような練習をしていたのかを調べる。その絵の特徴をつかむ','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','5','A','','バスケでの3pミドルシュートががうまくなりたい','毎日シュートを百本決めたらどのくらいシュートが入るようになるか？','もしかしたらシュートのフォームやボールに回転がかかってなくてはいってないののかもしれない','バスケのシュートを10本中7本くらい決めれるようになりたい','自分の好きなNBA選手のシュートを研究したり自分でも毎日シュートを百本決めてシュートの確率を上げる努力をする','体育・数学・理科・保健・家庭科','試合でシュートをいっぱい決めれるようになって試合でいっぱい出れるようになる','シュートがうまい選手のフォームや体の使い方をまねしたい','どのようなことをしたらシュートの確率が上がるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','6','A','','バレー！のコツをしりたい(うまくなりたい)','オーバーとかスパイクとかアタックとかどうやったら上達するのか','もしかしたらフォームやカマエ、助走が違うかもしれない','本探求ではスパイクやアタックなどのコツを明らかにする','バレー部の先輩やバレー選手の試合などの動画を見てコーチにコツを教えてもらってノートにめもする。コツの動画やタブレットで調べたりする！','体育','バレーがうまくなったら大会とかにも生かせると思う。','どうやって調べるかかんがえる','バレーがどうやったら上達するのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','7','A','','食べることが好き！！！世の中の食べ物はたくさんの味があってすごく美味しい！好きなもの、甘いものなど食べるとすごく幸せな気持ちになる。','なぜ人間は食べることを求めるのだろう。  （おなかがすくのだろう）  なぜ食べ物はあんなに美味しくて、見た目も美味しそうなのだろう。  どんなときにおいしいと感じるのか？  どんなときに○○が食べたい！と感じるのか？  食べることでどんな効果があるのか？','体に必要な食。→不可欠なもの、毎日食べるものがおいしくないと、きれいでないとテンション上がらないし、食べる気失せると思うから？？？？  色が与える印象が食にも影響してるかも？（においも）  食べたいと思わせるためにいろいろな工夫がある？  食べると、幸せな気持ちになる？  たくさん運動して疲れたとき、甘いものを欲する？','本探究では、人間にとっての食事について明らかにする。  ・食事の役割  ・美味しい理由、美味しそうな理由  ・美味しいと感じるとき  ・食べたいと感じるとき  ・食べる→効果、どんな感情が生まれる？   ・どうすればもっと食事を楽しめるか？','・日々の生活での気づきを見つける。  →「私は○○なときにお腹がすく、食べたいと感じる！」、「食事をすると、○○な気持ちになる」、「料理は○○のおかげで美味しくなってる！」などたくさん感じたことをメモしておく！  ・実際に料理を食べる！  →どんな見た目（飾りつけ）なのか、どんな味、においなのか、食べた後に感じることなどメモしておく！  ・アンケートを取る？  →「美味しいものを食べて幸せになったことはありますか？」「人気な料理などにはどんな工夫がされていると思いますか？」「おなかがすくときはどんなときですか？」など','家庭科、保体、理科（？）','食事の大切さ、ありがたさを知り、日々の食事をもっと大切にして楽しめる。一人でご飯を上手に美味しくつくれるようになる。（栄養バランスなど考えながら、見た目、美も意識する）','課題のために、どのような方法で調べているか参考にしたい。  →分析の仕方、情報の収集など。  そしてどのようにこれまでの学びを生かしているのか、掘り下げているのか参考にしたいと思う。','人間にとって食事は感情、心、体、行動にどのように影響されているのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','8','A','','アイスが好き！でも「ラクトアイスは体に悪い」と噂で聞いた。でもスーパーやコンビニに行くとラクトアイスはたくさん売ってるし、私自身も普段からおいしくめちゃくちゃ食べている。','なんで体に悪いと言われているのに、こんなにたくさんの種類が売られていて、みんなに人気なのだろう？そもそもラクトアイスと普通のアイスクリームの違いとは？','ラクトアイスには「体に悪い」というマイナスなイメージがあるだけで、実際には値段が安かったりカロリーが低かったり、メリットがたくさんある？    実際にアイスを買って、カロリーなどの栄養や値段を比べる。また、アンケートも取る。','・本探究では、アイスの４つの分類（アイスクリーム・アイスミルク・ラクトアイス・氷菓）の値段やカロリーなどの違いを数値ではっきりさせる。  →ラクトアイスと他の3種類の違いを伝えるために、他の3種類も調べる。  ・また、何のアイスが好きかとその理由もアンケートを取って、「アイスが人気な理由」も明らかにする。','①コンビニやスーパーで売られている色々な種類のアイスの「種類別」「値段」「カロリー」などを調べ、グラフにまとめる。  ②クラスや学年に「一番好きなアイスの商品名は？その理由は？」「ラクトアイスにどんなイメージを持っている？」などのアンケートを取る。','理科、数学、家庭科','ラクトアイスを「体に悪いもの」と決めつけるのではなく、データとみんなのアンケート結果を通して、それぞれの種類のアイスが持つ「本当の良さ」が見えてくる？と思う。','さっきも書いたように、クラスや学年に「一番好きなアイスの商品名は？その理由は？」「ラクトアイスにどんなイメージを持っている？」などのアンケートを取る。','ラクトアイスが体に悪い理由は？  そもそもラクトアイスとは？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','9','A','','ドラムをやってみたい！','あんなに大きな楽器なのに音量を抑えつつ、かっこよく、リズムを支えられるのはなぜ？ドラムにはどんな役割がある？、どうしたら演奏できるようになる？','ドラムがいないとリズムがくずれる？ドラムがいなくてもバンドは成り立つ？たたく場所によっても、印象が変わる？','本探究ではドラムの役割、ドラムを演奏できるようになるためのコツを明らかにする','ドラムの演奏方法を知る、有名なバンドのドラムではどのような工夫をしているか調査する、ドラムの役割を知る','音楽','ドラムにどんな役割があって、聞く音楽にもリズムが感じられるようになるかも、自分の演奏で笑顔になってくれる人がいるかも','ドラムの役割、演奏できるようになるコツ、工夫のポイントを調べ、まとめたり、ドラムにどんな印象があるか聞く','ドラムを演奏できるようになるには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','10','A','','３ポイントやミドルがもっと入るようになりたい','なぜ全然入んだろうか','もしかしてシュートホームがちがう？','NBA選手とかはなぜそんなに3ポイントがはいったりなんでそんなに確率がよいのか','みんなの確率やNBA選手の確率を調べる。あとみんながどんな工夫をしているのかを調べる','体育、数学,理科','自分の3ポイントやミドルがたくさん入りやすくなる','足の重心を調べる。','3ポイントやミドルがどうやったら入りやすくなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','11','A','','ベースかっこいい!!弾きたい！','そこまで目立つ楽器じゃないのになんでかっこいいんだろう？ベースにはどんな役割があるんだろう、ベースをうまく弾くコツって何？','もしやバンドにおいてベースがいないと成り立たない？弾き方によって魅力が変わる？みんなにベースの魅力を理解してもらうには？','本探究では、ベースのうまく弾くコツとみんなが理解してくれるようにベースの魅力かっこいい理由を明らかにする','ベースの弾き方を学ぶ、世界のバンドなどでベースがどんな役割をしているかベースの必要性とは何か調査する。','','みんながこれから聞く曲にベースがどんな役割があるのか新しい視点で曲が聞けるのかも','ベースの役割ややり方を調べる、ノートにまとめる','ベースの魅力と、ベースをかっこよく引く方法は？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','12','A','','バリトンサックスやってみたい!!!','どうしてかっこいい音が出るんだろう？なんでうまい人とあんまりの人の差が激しいんだろう？そもそもサックスの音の出る仕組みってどうなってるんだろう？','かけた時間の長さや経験の差で差が出るのはわかるけど息の入れ方や口のつけ方で音質が変わる？','本探究では、バリトンサックスの音の出し方、リードのコツについて明らかにする','バリトンサックスの吹き方、コツを調べる。うまい人の癖とあんまりの人の癖を比べる。楽器屋さんに行って、プロのお話を聞いたりしそうさせてもらう。あわよくば買う。','音楽、理科','吹部でチューバを吹くときに音質をまねしてもっとうまくできるようにする','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','13','A','','サッカーが好き!!!','なぜ上手い人は無回転やカーブが打てるのか？','もしかしたら無回転やカーブは筋肉がすごいから？実体験があったから？','本研究では自分が無回転やカーブを蹴れるまで練習して蹴れるかを検証してまた足の筋肉を鍛えたら蹴れるかも検証しサッカーの変化球を明らかにします！','無回転やカーブの解説動画や無回転やカーブを蹴れる人のプレイを見る！','体育 理科 数学','将来の2年生や3年生または高校生？でレギュラーででれる。そして自分に足りないシュート力を磨く！','具体的な例や実体験など！','どうしたら無回転やカーブが蹴れるか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','14','A','','scratchのアニメをはやらせたい','なぜ、あまりscratch日の目を浴びないのか','プログラミングは一部の層にしか見られないからかもしれない','本研究では、なぜ人が集まらないか、どうすれば人が集まるか','出ているscratchアニメなどを調べる','心理学（道徳？）・技術','人がどんなものに興味を持つか、','いろんなサイトのランキングを見て絞り込む。（できれば、アンケートを取りたい）','人を集める方法とは。？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','15','A','','ペンケースがつくりたい！','自分にあうペンケースが無いからつくりたい','コンパクトなのが一番いいのかもしれない','自分にあうペンケースをあきらかにする','いろいろなペンケースを試す','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','16','A','','アニメや小説が好き！','どうしてあんなに感動する話を考えられるのか？また、外国の人に日本のアニメが人気なのもそれが理由なのだろうか','大勢の人たちが協力して作っているからかも？また、日本のアニメには何か引き込まれるのがあるのかもしれない','本探求では、アニメを作っている人たちの工夫を明らかにする','そのためにサイトなどで調べたり、制作過程などがわかる短編映像をたくさん見たりする。そしてそれをまとめどのような工夫があるのかを考える','技術 国語 数学 音楽 美術','作っている人たちの工夫を知り、アニメをもっと楽しく見ることができるはず！！','どんなことをしたら業界の人々がどんな工夫をしているかがわかるのかを知るためにいろんな人に意見を求めたいです！','感動するような作品を作っている人たちはどのような工夫をしているのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','17','A','','アニメやペットが好き','なんでにんげんはかわいいとおもうのだろう','もしかすとかんじょうがうごいているのかもしれない','いまかってる犬がかわいいとおもってぃる','','保健体育、理科、美術、社会','可愛いと思える気持ちがどこかにあると思うからそれを知りたい','','犬なぜ人間はかわいいと思えるのだろうか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','18','A','','原宿派手な人多!!','なんで原宿や渋谷は派手な人がほかの場所より多いんだろう','原宿には新しぃ物が多いから、若い人が集まってどんどん新しいファッションが増えていくのかも!!','どうして派手な人が集まるのか、どういうきっかけで派手なファッションになるのかを明らかにする!!','まずは、原宿の魅力を調べる!!','社会、美術、家庭','町の魅力を伝えられたり、今までに、派手なファッションをしてみたいと思っていた人の力になれるかも!!','調べ方、アンケートやインタビューの仕方を参考にしたり、なぜ派手な人が多いのかだけじゃなく、昔はどんな町だったかとか、人が集まる理由も調べてみたい','原宿や渋谷はなぜ若者の町として有名なのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','19','A','','アニメと漫画とゲームとサッカーが好き','どうしたらうまくなるだろうか','もしかしたら研究や、練習が足りないかも','本研究ではサッカーがうまくなる方法を明らかにする。キックの威力や、正確さ、回転のかけ方などを練習する','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','20','A','','頭の中で ’’こんにちは’’ って言える。','なぜ喋っていないのに、頭の中で声が聞こえるのだろうか。なぜ喋れるの？なぜ考えられるの？','細胞が言葉を記憶しているからかもしれない。','本探究では、どうして喋っていないのに頭の中で声が聞こえるのかと脳の仕組みを明らかにしたい。','体の構造に詳しい人に話を聞き、この探求のヒントになりそうな話を聞き出す。脳の仕組みについて乗っている本を探す。','理科','普段当たり前のように行っている行為が体の中でどうなっているのかが分かり、人間の体がいかによくできているのかが分かる。（）','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','21','A','','バレーボールがうまくなりたい！！！','どうしたらサーブ・アンダー・オーバー・スパイクがうまくなれるのか','もしかしたらバレーボールがうまくなるコツがあるのかも!！！','本研究では、バレーボールがうまくなるためのコツを明らかにする！','コーチや先輩のボールの触り方をじっくりと観察をする‼','保体・体育','ボールの触り方がうまくなり、その触り方を意識して、ボールを触れば今よりもさらにバレーボールがうまくなるはず‼あと試合に出れるようになるかも！？','どうやって調べるのか。','バレーボールがうまくなるためのコツは何だろう。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','22','A','','フィギュアスケートが好き！','どうしたらうまくなるのだろうか？','もしかしたら回転のかけ方にうまくなれる秘訣があるのかも','本研究では、フィギュアスケーターの回転のかけ方を明らかにする','フィギュアスケーターのジャンプを飛ぶ時の回転のかけ方を観察し分析する。','保険・体育・国語','大会で調べた分の成果がでるかもしれない！','フィギュアスケートの主にトリプルの回転をかけるときや足をどこにつくかなどを調べる','フィギュアスケートがうまくなってスケートを色んな人知ってほしい！！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','23','A','','日常組が好き!','なぜあんなに動画が面白いのだろう','日常組やスタッフさんが考える企画が面白いから？','本探求では日常組の過去や配信をやる動機を明かす','みんなに何の日常組の動画が好きか調査する','国語','将来の夢やもし仕事で挫折して別の道に行こうとしたら候補が増えるから','みんなもどういう文章構成にしているのか参考する','どういうチャンネルが流行るのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','24','A','','科学（理科）が大好き！！','なんで家の中で自然現象がおこらないのか？','もしかしたら、家の中でも雨を降らせたり、竜巻をおこしたりすることができて、家の中でも農業ができるようになるのかもしれない。砂漠にも雨を降らせることができるようになるかもしれない！！','本研究では、家の中で自然現象が起こるかどうか考え実験し、そのことがどのように良い影響が与えるのか明らかにする。','1.塾のテキストをもとに、雨がどの条件で振るのかなどを調べる  2.その結果をもとに、考察し、仮説を立て実験する  3.その結果がどのような良い影響を与えるか考える','理科','水不足がなくなって、アフリカの方々など水を必要としているがないまたは岡名がない人や、減少傾向にある農家さんの負担を減らすことができるかもしれない。','理科（科学）','水不足で困ってしまっている人や、お金がなくて、お風呂に入ったりできない人、蒸し暑くて熱中症になりかけていたりする時。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','25','A','','サッカーが好き！','どうしたら左足をうまくけれるのか','もしかしたら右足でボールをけりすぎたのかも','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','26','A','','バスケットボールが好き!!!!!','バスケットボールについてもっと知りたい','もしかしたら、試合を見ることが足りないのかも','本探究では、バスケットボールの知識を得るために試合を見て、知識を得る','試合を見る、シュートフォームなどを知る','体育','試合を見ることが楽しくなる、上手になる(かも)','バスケットボールが上手な人に聞いてみる','バスケットボールの知識を得てみんなに伝える!!!!!','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','27','A','','バレーボールがすき！','どうしたらバレーボールがうまくなるのか','もしかしたら、アンダーとオバーは壁打ちをしたらうまくなるかも、サーブは近くから打って、コートに入ったら遠くから投げたらはいるようになるかも、あとは打つときの形をつくる。スパイクはジャンプして一番高くでキャッチする練習をしたらうまくなれるかも。','マイ探求では、アンダー、オバー、サーブとスパイクをうまくなれるようになって上手にできるやり方をしる。','本やバレーボールがうまい人（コーチ、先輩）などに聞いたり調べたりする。','体育','今よりアンダー、オバー、スパイク、サーブなどがうまくなって試合に出れるようになるかも。','アンダーなどのやり方を調べる。','バレーボールをうまくなるためには。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','28','A','','バレーボールが上手くなりたい！','どうしたらパス・トス・サーブ・スパイクがうまくなるのか','もしかしたら、バレーボールの上手くなるコツがもっとあるかも!','本探究では、パス・トス・サーブ・スパイクの上手くなるコツを明らかにする!!','コーチや先輩のバレーボールをみたり、上手くなる方法を聞く‼','体育・保険','バレーボールのコツをつかみ、たくさん練習すれば１年生の試合にでれるかも⁉','パス・トス・サーブ・スパイクのコツを調べる！','バレーボールが上手くなる方法を知る!','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','29','A','','仮想通貨作る','みんながどう変化（喧嘩、貧富の差）するのかきになるから','もしかしたら、私が世界の頂点になれるかも！','貧富の差、人の欲望をあきらかにする','最初にお金をばらまく→みんなかほしいほしい言う','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','1','A','','ペーパーレスってなんで実施してるのか','ペーパレス化によってなしえること','ひとまずSDGsの達成との関連性について調べる','ひとまずSDGsの達成との関連性について調べる','ペーパレス化について調べSDGsと一個一個関連を調べる','社会','意味もなくそっれぽい言葉を使う大人にならなくなる','','','');
