INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','30','A','','なぜたまに現金しか使えない店や自動販売機があるのだろう','交通ICやQR決済できるものが増えているのにまだあるのか','自動販売機や店は使えるようにするのが面倒なのかも','決済方法が多いものとそうではないものの違い','なぜないのか調べたりどのくらい現金しか使えないものがあるのか','社会','','','決済方法が少ない自動販売機なぜあるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','31','A','','目が不自由な人のための、信号の横などにある視覚障害者専用のボタンに視覚障害の人は気づけるの？','どうやって目の不自由な人は見えないのにそれを使えるのか','もしかしたら、視覚障害者にしかわからない合図のようなものがあるのかも？','目の不自由な人の暮らしのための工夫について・私たちが今後できることは何か','実際にその機械を押してみる・調べる','美術・社会','行きやすい社会のための工夫や将来生きることに役立つ','調べる','目が不自由な人が視覚障害者用のボタンに気づける理由は','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','32','A','','最近文房具を前より使わなくなった','どうして文房具があまり使われなくなったのか','もしかしたら紙を使う量が減っているのかも','文房具の売れ行きか紙の使用量の変化','インターネットや本で調べる','社会','データがウイルスとかで消えるのを防げる','インターネットを使う','なぜ人間は新しいものにひかれるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','34','A','','サッカーってやっぱ楽しい','W杯とかみてやっぱり楽しいし面白いと感じた','もしかしたらサッカーって世界と感情を一緒にさせれるのかも','サッカーの魅力やルールを明らかにしたり実際にやってどういうところが楽しいのかを明らかにする','サッカーってやっぱどういうところが面白いのかを調査する。','体育、社会','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','35','A','','なぜスポーツは楽しいのか','ｗ杯とか野球が面白いと思ったから。','人を魅了、楽しませるものだから','この探求でいろいろなスポーツに触れてスポーツで感動、魅力、楽しい理由を明らかにする','スポーツ（多種目）をやっている人にやっている理由と楽しさと魅力を聞く','体育（保）','野球だけではなくほかのスポーツへの興味や楽しさがわいたりするかも','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','37','A','','最近部活動中のけがが多い','どうやったら事故を減らせるか','普段の生活習慣が関係あるのか','どうしたらスポーツをしているときのけがを減らせるのか','部活動中に起きうるケガの種類を調べる','保体','ケガが減りそう','','','');
