INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','2','A','','思考実験とかの考えること','思考実験はどんな種類があるか、あるとしたらどんなものなのか','現実では行うことが難しいから','物理学と哲学の思考実験で何が違うのか','思考実験一覧表を作る','道徳 国語 理科','考えることの大切さを知れる','アンケートを取る','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','3','A','','涙がしょっぱい気がした','涙しょっぱい','涙しょっぱいのなんで','涙がしょっぱい理由','みんなに聞く','理科','涙を流すときにしょっぱい理由がわかる','アンケートとる','涙がしょっぱい理由','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','4','A','','柴犬が好き','柴犬以外の日本犬は何種類いるのか？','日本犬は柴犬を含めて６種類いる','その６しゅるいの日本犬の特徴と歴史と絶滅した犬種の歴史明らかにする','日本犬保護協会のホームページで調べる','社会','その6種類の日本犬と関連している地域の歴史がわかる また、ハチ公についても知れる','秋田犬の特徴をしらべる','日本犬の特徴とれきし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','5','A','','190以上もの国がある？','なぜ190か国以上に分かれたのか？','もしかしたら文化の違いが原因なのではないのか？','190か国の文化の違い','いくつかのまとまりで調べる。','社会、外国語','190か国のなかでの仲間と違い','文化のまとまりを調べる。','なぜ190以上の国に別れそれぞれの文化があるのだろうか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','6','A','','注射が嫌い','なぜ注射には何歳までに打たないといけないなどと年齢制限があるのか','子供のうちに打っておかないと効果が出ないのではないか','年齢制限のある注射、なぜ年齢制限がついているのか、制限を守らなかった場合どうなるのか','病院のサイトや注射の専門のサイトを見て調べる','国語・社会','ワクチンなどに年齢制限がついている','理由を調べる','注射に年齢制限がついている理由','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','7','A','','漫画が好き','日本の漫画はなぜ海外にも人気があるのか？','日本の漫画はいつから海外に人気が出たのか','日本の漫画が世界で人気になった理由を知る','漫画の歴史や人気の理由をインターネットで調べ、海外との違いもまとめる','社会、国語、美術','日本の漫画文化について理解が深まり、世界で人気がある理由を説明できるようになる','日本の漫画の歴史について調べる','なぜ日本の漫画は世界で人気なのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','8','A','','イスラエルとパレスチナがもめてる','なぜもめているか？ユダヤ人の迫害の歴史があった','←ユダヤ人の受けた迫害の歴史が関係しているのでは','ユダヤ教やユダヤ民族の原点、聖地に関する歴史、ユダヤ人の受けた迫害の歴史、現在のパレスチナ問題とイスラエルという国','ユダヤ教の抱える信条や他教徒との違いや、ユダヤ民族の住む地域の移り変わりをインターネットや図書館で調べる。ホロコーストの実態などは過去にアウシュヴィッツに行ったときに撮ったものを参考に、ホロコースト記念館などの情報をもとに考える。','社会','','','ユダヤ人はなぜ迫害され、迫害するのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','9','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','10','A','','授業や勉強に集中できるようになりたい','どうしてすぐに集中が切れてしまうのか？','その時の気分や睡眠などが関係しているのかもしれない  好きなことは集中できるから好き嫌いも関係している？','どうして集中が切れるのかと集中力を高めるにはどうしたらいいか、集中できる人とできないひとの違い','集中できている人やできなくて困ってる人に聞いてみる  集中力に関係してること、集中力を高める方法を調べる','体育','前よりも授業や勉強に集中できるようになる  集中力が高まる','','集中力を高めるには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','11','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','12','A','','中・長距離（８００ｍ・１５００ｍ）で速くなりたい','同じ練習をしている友達のほうが１０秒近くも速い','速い人に聞いてみる。自分でメニューを作り実践','はじめとどれくらい早くなったのか','特異な友達に聞く。それを実践','体育','はじめよりも簡単に楽にはやく走れるようになる','今の疑問を深める','長距離が早くなるには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','13','A','','あの桜変わったピンク色だな～','なんで葉っぱは緑なのに花は色がついてるのかな？','その場所の土の成分かな？','植物でも葉っぱと花の色が違うのには、何が関係しているか','理科の先生に聞いたり、本やネットで調べてみたりできれば、その場詩に生えているそれぞれの花や緑の葉っぱが生えている木のそれぞれの土の成分を調べてみたいです。','理科','理科が得意になり。花の種類が前より知ることができてこんな植物にはこのような土が必要などということがわかる。','葉っぱと花の色が違うのがなぜかを調べる','なぜ植物でも「花」には色があるのだろう？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','14','A','','スマホ依存症の改善の仕方','なんで勉強は依存になる人が少ないのにスマホは依存になるのか知りたくなったから','中毒性があるから。ブルーライト？が関係している','スマホ依存症はなぜなるのか','とりあえず、三木先生。三木先生が分からなかったらネットで調べる','理科','少しでも勉強に集中できるようにしたい','原因と改善点を調べる。','スマホ依存になる原因と改善の仕方','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','15','A','','退屈な時間は長く感じるのに、楽しい時間は短く感じる','同じ時間のはずなのになんで短く感じたり長く感じたりするのか','苦手な教科を勉強していても集中していれば短く感じるから集中しているかどうかで感じ方は変わるのではないか','本探求では時間が長く感じるときや短く感じるとき、短く感じさせる方法や長く感じさせる方法を明らかにする','楽しい時、退屈な時、運動しているときに感覚で10分計って誤差を記録する。タブレットを使って調べ学習をする。','理科、体育、数学、家庭科','つまらないときに早く時間を感じれるようになるかも','楽しい時、退屈な時、運動しているときの脳には何もしていないときとどんな変化があるのか調べる','時間を早く感じたり長く感じるためには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','16','A','','サッカーのシュートはどうやったらもっと飛ぶか','','今全然ボールが飛ばないからどうやったら飛ぶのかいろいろなことをしたい','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','17','A','','音楽が好き','音楽はなぜこんなに聞きたくなるのか','昔はそんなことなく進化でこうなった？','my探求では「音楽の進化の軌跡」を調べたい','音楽ができたとき、そこからの楽器や音楽、聞き手がどのように変化して今に辿り着いたのか','社会＋音楽','音楽の魅力をより深めることができる','Google等で昔の「音楽の始め」について調べる','音楽の進化の軌跡','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','18','A','','第一空挺団は高所から五点着地してる。','五点着地ってできるの？むずいの？','もしかして衝撃分散？','五点着地をできるようになる方法を明らかにする','五点着地、第一空挺団の訓練を調べて実践する','体育、CT','高いところから落ちても生きて帰れそう。','訓練方法を調べる','五点着地をできるようになるには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','19','A','','小学校の先生になりたい！海外に行きたい！','学校が楽しいから？世界のことをもっと知りたい！','もしかして日本と外国って教育の仕方が違うのでは？','本探求では日本と外国の教育の違いやその課題を明らかにする','日本と外国の教育の仕方の違いや今起こっている問題について調べる','全教科','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','20','A','','友達コミュ力高いなー','なんですぐ仲良くなれるのかな？','初対面の人とすぐに仲良くなれる人って、話すのがうまいのかも？笑いを引き起こすのがうまいのかも？','コミュ力上げる、初対面の人ともすぐに仲良くなれるためには何が大事かを明らかにする','コミュ力が高い人の話し方や話すときの表情に着目したたり、気をつけていることを聞いてみる。','国語','転校生とかそういう初対面の人とも仲良くなれる','人と話すときに気を付けていることなどを友達に聞いたり、調べたりする','人見知りを直すためには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','21','A','','リフティングは楽しい','どうしたらリフティングがうまくなるだろう','コツとかはどうでもよくて、何回もやることが大事なのではないか','本探求では、何をしたらリフティングがうまくなるのかを明らかにする。','1つ目：まず素の状態でリフティングの回数を測って、その後にネットなどでコツ等を調べ、それをもとにもう一回やってみる。そしてコツを調べる前と後の回数を比較する。２つ目：まず素の状態でリフティングの回数を測る。そして３０分間リフティングをやり続けてそのあとにもう一回回数を測る。そして３０分前と後での回数を比較する。','体育','リフティングをやり続けることで、ボールタッチの質が上がり、チームでも良いプレーができるようになるのではないか','練習方法を今考えている二つだけじゃなくてほかにも何か方法があるのか知りたい','リフティングはどうやったらうまくなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','23','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','24','A','','野球が好きだがやりたくない','どうしたらモチベが上がるか','楽しい事をすればモチベが上がる？','モチベはどうすれば上がるのか','嫌なことをする前に楽しい事をする','','嫌なことでもモチベーションが上がる','どんな時にモチベが上がるか調べる','どうしたらモチベが上がるか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','25','A','','食べ物','何で嫌いな食べ物があるのか。苦手なのか。','食べ物のトラウマ？偏見？味が苦手。','どうやったら好き嫌いがなくなるか。食べれるようになるか。','1つ目は、嫌いな食べ物だと思わないで好きな食べ物だと思って食ってみる。  2つ目は、なぜ嫌いになるかを調べる。  3つ目は、味を変える。  4つ目は、隠す。  5つ目は、見た目をよくする。','保体、家庭科、CT','食べれる食べ物が増える説。  いろいろな食べ物好きになったら、給食とかご飯の時間が楽しくなる説。','調べる。','どうやったら好き嫌いがなくなるか、減るのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','26','A','','ユーチューブショーとのコメ覧終わってる','なんでコメ欄をあらす？','もしかして僕が知らないユーチューブの伝統？','本探求では、どうしてユーチューブショートのコメ欄が基本あれるのかを明らかにする','','ユーチューブのショート動画','なんで戦争が起きるのかがわかるかもしれない','最初のまま','ゲームのランキング動画でコメント欄を荒らさないためにはどうすればいいのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','29','A','','和服・制服がかわいい','今は昔の服を着ている人が少ない','もしかして動きにくいから？','本探求では昔の和服・制服の人気を調べて服がどんどん変わった理由について詳しく調べる','ネット調べたり、アンケートをする。','社会','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','30','A','','好き嫌いはなんであるんだろう','ダサいとダサくないって人それぞれ違うんじゃ','感性は人それぞれ違うからみんなの基準も違うかもしれない','人それぞれ感性が違かったら対立が起きてしまうのに','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','34','A','','やりたいこと、やらなければならないことが多すぎて時間がない','なんで時間が足りなくなるんだろう','もしや無駄な時間があるかもしれない','現代における無駄な時間を明らかにする','みんなが無駄だと思っている時間、無駄だったかもしれないと後悔した時間はないか、またそれは何の時間なのか調べる','社会','無駄な時間の傾向が分かれば、どの時間を削ればいいか明確に分かりやすくなるかも。','1回アンケートを取る','現代人は無駄な時間が多いのか、また無駄な時間を削減するには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','35','A','','ディズニー楽しい','ディズニーはなぜあんなにもワクワクするの','ディズニーに隠された工夫があるのかもしれない','ディズニーパーク内で隠されている工夫を歴史と関連付けて調べてディズニーに来た人が楽しめる理由を明らかにしたい','ネットで工夫されているところを調べて、友達にどんなときにワクワクするか調査する','道徳？社会','愛され続けているディズニーに隠されている理由を知れば、将来自分で何かを開いたときの知恵の材料になるかもしれない','ワクワクするときがどんなときか考える','ディズニーに隠された工夫','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','36','A','','エレキギターをうまく弾けるようになりたい','ギターがすぐ上達する人との違いではなにがあるんだろう','練習内容や時間の違いがあるのかもしれない','ギターのどんな練習が一番上達するのか調べる','練習内容を調べ、それを練習する','音楽','ギターがうまく扱えるようになる。正しい練習方法がわかる','ギターの技能について詳しく調べる','ギターが早く上達しやすい練習方法とは','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','37','A','','','','','','','','','','','');
