INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','1','A','','サッカーが好き','どりぶるを強くしたい','ドリブルをしたら強くなるかも','ドリブルを練習してサッカー経験者に勝つ','ドリブルが強くなる練習メニューをやる','保体、','ドリブルが強くなる','練習相手をしてもらう','ドリブルを強くする','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','2','A','','部活動で都大会が決まった。その時、現場では涙は出なかったが、家に帰ったら涙が出た。','なぜうれしい時にも涙が出たのだろうか。','もしかして、中にこもった感情が爆発して涙が出るのではないか。','本探求では人がなぜ喜んだ時に涙が出るのか・大笑いした時に涙が出るのは関係するのか などを調べる','本やインターネットなどで涙が出る理由を調べる・アンケートで一番涙が出るときはいつか集計する','理科(全教科？)','人の感情の理解ができるようになるかも・感情のコントロールができるかも','他者からの意見を取り入れるためにアンケートをとる','なぜ人にも涙が出るのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','3','A','','アイスが食べたいです','なんでアイスって美味しいんだろう','アイスが冷たいから美味しく感じるのかも','アイスの美味しさの秘密','ネットで調べる','家庭科','アイスのことをもっと好きになれる','調べる','アイスの美味しさの根源とは','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','4','A','','','なぜ同じ出来事でも、国籍によって感じ方や感情に違いが出るのか','感情の差は事実ではなく解釈の仕方で決まるのでは？','本探求でははじめに感情とは何なのか簡単に調べる。','本、インターネット、アンケートなど','国語？','','','人々の感じ方の違いの理由','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','5','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','6','A','','体力テストで高得点がとりたい','なんで俺より足が速い人がいるの','生まれた時の才能や、体つきだけではなく努力で高得点を取っている人がいるかも','種目別で実験し、１種目で高得点の出し方をたたき出す。','教室で調べてそのやり方で高得点を目指せるか実践してみる。確かめてみる。','体育科、理科,','生活に最低限必要な身体能力が身につく。','全員が生活に必要な身体能力を手に入れることができる。','体力テストで高得点を取るには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','7','A','','骨折','こっうせつかが多い','骨が弱いから','本探求では自分が骨折しやすい原因と。  どうすれば骨折とか怪我減るのかを明らかにする','タブレットや本で調べて、実践してみる','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','8','A','','地元の場所で最も美味しいカツオを探したい！','今まで分からなかったカツオの発見があるかも！','地元で最も美味しいカツオの美味しい店はどこにある？','東京にいるからわからないけど、環境の違いで、まだ発見できていない種類のカツオがあるかも！','地元に限らず、どのような場所でどのような種類のカツオがあるか探りたい！','社会','地理の授業に繋がる。日本各地の名産品をよく知れる。','インターネットで調べて、詳しくは街中アンケートをする。','日本各地でどのようなカツオの種類があるか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','9','A','','音楽がすき','人気な音楽は何が大切？','コード進行が関係している？','本研究では人気の音楽の共通点を明らかにする。','アンケート','音楽、数学','曲の構成が分かる','アンケート','人気の音楽の共通点とは','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','10','A','','本、漫画、メンタル','なぜ伏線がある本はおもしろいのか？','共通点がある？頭の中で何かが起きる？','どのようなことが関係していて、そのことがほかのことに使われていないか調べる。','アンケート','国語','国語力がつく','アンケート作る。','伏線は人間にどんな影響を与えるのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','11','A','','勉強ができるようになる効率的な脳の使い方','どのような使い方をしたらよくなるのか','脳の部位と役割について研究する。','数学の視点とる 人気の勉強法をとる→それは脳科学的にほんとにそれがいいのか調べる','アンケート','理科','またひとつ新しい知識を得られる','アンケートとる','勉強ができるようになる効率的な脳の使い方','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','12','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','13','A','','社会科が好き','なぜヨーロッパはあんなに発展しているのか','気候がいい感じだから？','ヨーロッパの歴史やその土地の特徴、周辺はどうなのかなどを調べる。そして将来のヨーロッパがどう発展するのか考える。','インターネットや本などでしらべて、最後に考える。','社会、','ヨーロッパのことについていろいろと知ることができる、社会科の授業に役立つ。','まずヨーロッパの地域の特徴を調べる。','ヨーロッパはなぜあんなに発展しているのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','14','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','15','A','','バレーボールのレシーブがうまくなりたい','ハイキューを見たから','もしかして、ハイキューの技ができるのかもしれない','西谷さんくらいレシーブがうまくなりたい','レシーブのやり方を調査する','体育','ハイキューの西谷さんのレシーブの方法がわかる','レシーブを1000回したらどうなるのか','レシーブを1000回したら腕はどうなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','16','A','','サッカーどんな練習をしたらシュートがうまくなるのか','試合でゴールを決めたいから','試合でゴールをきめれるかも','スーパーゴールを決めれるかも','充てる場所を調査する','体育','','','/','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','17','A','','スリーポイント決めたい','どうやったらスリーが入るようになるのか','フォームを固めると狙いやすいのでは？','スリーポイントを決めるための練習法は何がよいのか','タブレットやインターネットで調べてやってみる。','体育','とにかく実践してデータをたくさんとる','有名な練習法を調べてみる。','スリーポイントを決めるための練習法とは？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','18','A','','一般的な椅子が4本足な理由','美術館とかでは足が4本以上のを見たりするのにレストランとかでは見ないから','ガタついて普通に座れないから','4本が一番いい理由','タブレットで調べまくる','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','19','A','','走るの好き','足早い人はなぜ足が速いのか','走り方に工夫がされている？','早い人の共通する走り方の工夫を調べて体に定着させ、記録の向上につなげる','仲のいい足が速い人に聞いたりトップスプリンターの走り方などを分析してそれを意識しながら走る。','体育','','','','');
