INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','32','A','','代表委員としていいクラス、学年にしたい','なんでみんな話を聞いてその行動ができないのだろう','自分には関係ないと思っているのではないか','みんなに話を聞いてもらったり行動をしてもらうための話し方、伝え方を明らかにする','どんなとき人の話を聞きたくなるかを友達に聞いたり、どんな話し方をしたら話を聞いてもらいやすいのかを調べる。','国語、保体','人と話すときに伝えたいことが伝わりやすくなるかもしれない','これまでこの学年がどんな問題を解決してこれなかったのか、なぜそれが解決できなかったのか考える','学年の問題を解決するためにはどのような話し方をしたらいいか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','33','A','','太陽を見るとくしゃみが出る理由とくしゃみが出るといわれている物は本当にでるのか検証','学校から帰っていたときにくしゃみが出そうで出なくてむかついたときに上を見て太陽を見たらすぐくしゃみがでたので不思議に思うようになった。','太陽の光の刺激が強すぎてくしゃみがでるのではないだろうか？逆にくしゃみが出ないときに太陽を見たらくしゃみはでるのか','太陽をみたらくしゃみが出る理由とどうすればくしゃみがでるのか','ネットでくしゃみが出る方法をたくさん調べて検証してみる','理科・保健体育','くしゃみをでるアイテムは迷信かもしれない太陽をみるとくしゃみがでるのは個人差があるのかもしれない。','くしゃみがでるといわれている物を調べて自分と友達で試してみる','太陽を見るとくしゃみがでる理由とくしゃみがでる物は本当にでるのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','34','A','','かき氷のシロップってほんとに全部味が一緒なのか','細かな味の違いを見分けるにはどうしたらいいのか','味覚が鋭い人と普通の人では何が違うのか','味覚が鋭い人と普通の人では何が違うのかを明らかにし、味覚を鋭くする方法はあるのかをしらべる。','味覚が鋭い人が味の違いが判るのかをまず実験する（かき氷のシロップ、からしとわさび）','保体、家庭科、理科','料理をおいしく作ることができる','前提として、味を感じる仕組みを調べる','舌が鋭い人と普通の人の違い','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','35','A','','靴紐がすぐほどけてしまう','靴紐がすぐほどけないようにしたい。','靴紐の結び方が悪いのかもしれない','本探究では靴紐をほどけないように調べてどうやったらほどけないか実験をする。','','','','','','');
