INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','37','A','','着物が好き','なぜ着物を着ないのか。','着物は日常から着にくいのではないのか。','着物の欠点を調べる。','和服と洋服のつくりの違いについて調べる。','社会','和服の作りに着づらい原因があるのかもしれない','和服が着づらい原因を考える。','なぜ和服が着られなくなったのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','38','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','1','A','','ベースって意味あるのかな','ベースがあることによって何が変わるのか','曲に深みが出るのかもしれない','','','音楽','','','曲の雰囲気を決めるのは何か','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','2','A','','サッカーがうまい人の特徴','サッカーのうまい人の特徴を調べてじぶんもうまくなる','組織力や適応する能力があればいいのでは','特徴を明確にしてまとめたい','うまい友達や有名なサッカーチームのプレイを見たり自分でも試してみる','体育','サッカーがうまくなる','友達やプロの選手を参考に','サッカーがうまい人の特徴','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','3','A','','心理学について興味がある。','噓を見抜く方法はあるのか','嘘をついている時だけ表情やしぐさに変化があるのではないか','噓をついている人の表情やしぐさの変化をみつけ、心理学に当てはめてなぜその行動に移るのか考えてみる','友達に嘘と真実を言い続け、それを見抜いてもらう。  見抜けた場合はなぜ見抜けたのか、というのを繰り返して嘘をついている時の特徴を探す。','理科・保健体育','嘘発見器になれる  嘘がバレないようになるかも','予測・仮説をたててみる。実験内容を考える','嘘を見抜くには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','4','A','','テーマパークにに行く前日にドキドキするしたり、テーマパークから帰りたくなくなる。','テーマパークに中毒性がある？','人間の精神に関係がある？','すべての人にこの現象が起きるのかを調べ、他にどんなことでこのように感じるのかを調べる。','いろんな人の特別なことについてアンケートをとり、人間のドキドキするときの精神状態についてしらべたりする。','保健体育','この中毒性を制御することができるかも','本当にこの探求でいいのか考えなおす。最終決定。','テーマパークの中毒性','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','5','A','','キャラクターかわいい','愛されるキャラはどんな顔','決まった目の位置とかがあるのかも','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','6','A','','格闘技を見た','格闘技が強い人の特徴','気合がある人が強い','特徴を調べる','やってる友達に聞く','体育','普通に気になった','やってる やっていた人をさがす','格闘技強い人の特徴','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','7','A','','サッカーに関しては左利きの奴上手いし、バスケは有利らしい','しゅん(伊藤)とかあおばとかが左利きだから。←こいつら上手い。バスケだったら、はやと','もしかしたら、スポーツは左のが有利','結局どっちが有利かを明確にさせる(左か右か)','世界の人口の利き手足とスポーツ選手の利き手足を比べる(サッカーだったら足、バスケなら手)','体育','左手・足を使うのを頑張るかもしれないし、普通に気になった','手伝ってくれそうな人を探す(スポーツの探求の人)','スポーツは左と右どっちが利き手足が有利なのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','8','A','','魔法を使いたい','なんで使えないのか？','もしかして、科学で魔法を出すことができるのかも、、  ・あと少しで使えるようになるかも','科学で魔法の事象をすべて証明？検証してみる。科学＝魔法の方程式を完成させる！また、人類がまだ踏み入れていない領域にあるかどうかも調べる。','魔法に関する事象をおこす実験をする！科学での観点でも、第六感の観点でも','理科・保健体育','人類が魔法を使えるようになること','魔法関する事象を教えてもらう Ex.スプーンを簡単に曲げる、水を急に凍らす、物を念でもやすetc...','魔法を使えるようになるには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','9','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','10','A','','アマモ場が減っている','なぜアマモが減少？','今生息しているアマモが弱いからかも','アマモの遺伝子などを変えずに強い種類の特徴や何が違うのかを明らかにする','植物を調べるときのように核や細胞壁などの部位を調べる。また、アマモは下の土(泥」によって育つため土を変えて成長を見てみる 。','技術、理科','海の環境回復','特になし','アマモのそもそもの姿を知る。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','11','A','','なんで勉強は自発的にしたいと思わないのにゲームはするのか','ゲームはどこでもできるからかも','心理学が関係しているかも','ゲームの種類と勉強の種類を比べ、差を知る','いろんな人に協力してもらう','理科','勉強がはかどるかもしれない','心理学に関係しているか調べる','なぜ勉強よりゲームのほうが魅力的に感じるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','12','A','','なんで俺らはいいタレントがそろってるのにかてない？','組織と個人技はどっちだったらかてる？','わんちゃんコーチングがわるい','なにがだめなのか明確にする。','サッカーがうまくない人にコーチングをして検証、ほかの原因も探す','体育、','強いチームの何が強いかがわかる','どんなプロチームがどのような共通点がありでどんな戦績を残してるか調べる','なんでいいタレントがそろっててもかてないの？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','13','A','','外見','すこし変えるだけで雰囲気変わる','元のイメージが強いから','人はどんなところで印象が変わるのか','試す','','印象の与え方をマスターできる','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','14','A','','ギターかっこいいna-','ギターはどうやってひくんだろう','ギターは何で引くのが一番引きやすい？','ギターを弾くのにあたって最適なものとは？雰囲気によって引くものを変えるなどするべきかより出したい音に知被けるにはどうするｂｗきか','いろんなものでギターを弾いて、いろんな奏法を試してグラフにまとめるその結果でロック系は何で引くか落ち着いたケイは何で引くかを深めてギターの音について探求を深める。','音楽','ギターの音づくりへの理解度が深まる','方向性をめいかくに','ギターの音で雰囲気や感情を左右させるにはどのように音を奏でるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','15','A','','指鳴らすの楽しい','なんで日によって指の鳴らす音の大きさが変わるのか','環境、部位で変わるのかも','指の鳴らす音を大きくするにはどうすればいいのか','なぜ鳴るのか調べる','理科','親戚に話す豆知識が一個増える','原理を調べる','指で大きい音を鳴らすためには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','16','A','','漫画・アニメ','漫画やアニメはなぜ人を引き付けるのか','面白いのもあるけど言葉が分からなくても絵や音楽などで状況が分かったりするから（？）','漫画やアニメはなぜ人を引き付けるのか','最初にみんなにアンケートを取り最も人気なジャンル（最も人を引き付けるジャンル）を決める','','分からない','アンケートを取る','漫画やアニメはなぜ人を引き付けるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','17','A','','高跳びをどうやってきれいに飛ぶか','部活で高跳びをしてるから','練習をしてるとうまくなる説(あたりまえ)','自分の限界を超えられるか','練習と観察','保体','大会はもうないかもしれないけど役立つ','いろんな人の高跳びを見れたら見る','高跳びをきれいにどうやって飛ぶか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','18','A','','なぜ日焼けするのか','日焼けしている人の原因','どのように日焼けするのか','なんで焼ける','日焼けしてる人に聞く','保険 体育','日焼けする または 予防ができる','人に聞く','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','19','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','20','A','','音楽を聴くことが好き','なぜ音楽はたくさんの人に世界中で愛されているのだろうか？','フレーズやメロディ、ベースに特徴があるのかもしれない','なぜ音楽は世界中でたくさんの人に愛されているのか','人気の曲のメロディを調べてみたり、友人に好きな曲を聴いてみる、イヤホンとかで音楽聞けるといいかも','音楽','より自分に合う曲を見つけられるかも、もっと聞く音楽の幅が広がるかも','いろいろな方法で調査してみたい','なぜ音楽は世界中でたくさんの人に愛されているのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','21','A','','俺って陸上競技にむいてるの？','なんとなく今まで中途半端にやってきたから','なにかもっと工夫したら早くなるのではないのか？','どうしたらもっと早くなるのか','自分が今なぜ遅いのか考える。','体育','陸上が早くなりそう','何が遅い原因かを調べる','なぜ陸上競技でいい結果が出ないのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','22','A','','五感と四肢さえあれば何でもいいから不老不死になりたい','自分と脳の細胞一つ一つの配置から何から何まで全部おんなじのものをコンピューター上で作ったらそれには自分と同じ意識が宿るのか','生物を人の手で作り上げたら意識が発生するのかそもそも意識とゆうものが脳に宿るのか','1人の人間とその人間が生きるのに必要な環境を原子の構造一つ一つまでコンピューターで再現しようとしたらどの程度のスペックが必要なのか  また今そのレベルのスペックのコンピューターはこの世に存在するのか','まずはその必要なスペックとどのレベルで実現できる可能性があるかを調べる','一応理科か数学か技術','不老不死になれる可能性を知る','とくにない','コンピューターの中だけなら人が不老不死に近いものになれる可能性はあるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','23','A','','三年生になったから、みんなにロボットと呼ばれている','自分とロボットと共通点を探したい','AIに聞いたら、戦闘IQが高いと言われました','なぜAI何もわがるの','AIの原理を調べる','社会','みんなの戦闘IQを高まるかもしれない','AIが生まれた原因を調べる','AIは人間の生活を変わることができますか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','24','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','25','A','','ミュージカルってすごい','どうしてミュージカルはこんなにみりょくてきなのか。','ミュージカルの構成に秘密があるのかも','ミュージカルはさまざまな公演が行われている中で、幅広い世代にどうしてここまで広まっていったのか調べたい。','ミュージカルの歴史や構成などを調べる。','音楽 社会 美術','','','ミュージカルはどうして人気なのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','26','A','','スヌーピー（ピーナッツ）が好き','PEANUTSはなぜ世界中で愛され続けているのか。','シンプルなイラストと面白い話にひかれるから。','PEANUTSの漫画や、そのキャラクターがなぜ世界中で愛されるようになったのか。','PEANUTSが好きな人にどんなところが好きなのかを調べる。','社会、美術','自分の好きなものを極められ、さらに好きになれる','PEANUTSがどのように成り立っていったかを調べる。','なぜPEANUTSの漫画やそのキャラターは世界中で愛されるようになったのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','27','A','','モンシロチョウかわいい','四原色が見えるのはほんとうか？','仲間を見分けるため？','','','理科','','','なぜモンシロチョウは四原色がみえるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','28','A','','最近朝早く起きれないなぁ','なんで朝早くに起きるとねむいの？','寝る時間が遅いかも','','','','','','どうやったら早く、気持ちよく起きれる？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','29','A','','ゲーム楽しい','なぜ負けると悔しいのか','おそらく脳のドーパミンなどの幸せホルモンなどの分泌が止まるから','なら、どうすれば負けても幸せになりつづける中毒性の非常に高いゲームを作れるのか','まず、人間は新しいものや面白いものを見たときに次はどうなるのか、という風に考えるときにドーパミンなどが分泌されるため、常に新しいものを提供するティックトックなどの短い間隔で楽しめるものを調べる。','理科','負けた時にも楽しめて、全体の幸福度が上がる','','どうすればもっと楽しんでゲームができるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','30','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','31','A','','バスケでダンクしたい。','どうしたらもっとジャンプできるか。どうやったらボールを持ちながら跳べるか。','今の自分の身長と筋力でもダンクできるのか。','自分がダンクするために足りないことを調べて、実際に試してみる。最も跳べる体制や、助走の仕方などについても考えて最終的にダンクする。','ジャンプ力が高い人や、ダンクできる人の跳び方を見て真似してみる。何回も跳んでみて一番跳べる足の角度や、手の振り方、助走のつけ方、跳んでくる方向、意識することを調べる。','体育 数学','ジャンプ力が上がりダンクできるようになる。','まず体育館で現在の自分の状況を確かめる。','ジャンプ力をあげてダンクするためには何が必要か。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','32','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','33','A','','ミッキー（ディズニーキャラクター）が可愛くて好き','ディズニーキャラクターはなぜ世界中に愛され続けているのか','シンプルにかわいいから、アニメが面白いから','ディズニーキャラクターが世界中で愛され続けるようなったのはなぜか。','ディズニーキャラクターが好きか、なんのキャラクターが人気か、ミッキーが好きか、調べる','社会、美術','ディズニーについて詳しくなり、もっとディズニーが好きになる','','ディズニーはなぜ世界中に愛されるようになったのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','34','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','35','A','','歌を歌うのが好き！！','なぜ人は歌を歌うのだろう。','自分の考えや心情を簡単に表現できるから？','歌を"歌う"ということが私たちにどう影響しているのか。  "聴く"とは何が違うのか','みんながどういうときにどんな曲を歌うのか、またその時どのような気持ちになるか調べる。','国語、保健、音楽','歌うことが心の変化や成長に影響を与えていることを知り、歌がより好きになる','アンケートをつくり、歌についての調査を行う','歌うことはなぜ人々の心の支えになっているのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','36','A','','「万物は静寂へ、熱は虚無へ、すべてを凍てす白銀の帳よ、絶対零度(アブソリュート・ゼロ)」 ←かっこよ、','なぜ中二病になるの？なぜ中二病を発症するのか。','もしかして、この世界が嫌になって、異世界や魔法、かっこいい言葉にあこがれる？！','この探求では中二病の考えていることや、どうやったら中二病になるのか、あこがれるのはどんなものかを考える。','自分が思う中二病だと思う人に、実際聞いて考える、また、その人が納得するような、詠唱を考えてみる。','保健、理科','中二病の考えや、気持ちが分かって、心が豊かになる。','探求方法を考える。','中二病患者は、どんなことを考えて、何にあこがれているのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','37','A','','ワールドカップおもろいな','サッカー知らないのににわかが興奮するのはなぜ、で終わったら興味が薄れるのはなぜか','もしかして何年に一度とかだから興奮するのでは','なぜ興味が薄れるのかを調べる','友達に聞いたり、サッカーなど少し触れて、なぜ興奮するのか調べる。','保険体育','少しでも野球やサッカーを見てほしい','やってみたり、聞いてみたりする','サッカーや野球を知らないのににわかが興奮するのはなぜ、で終わったら興味が薄れるのはなぜか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','38','A','','友達が怒ったー','人が怒る心理','もしかして短期！？','人が怒る理由を確かめる','怒ったことがある人に聞く','保険','理解が深まり喧嘩することがなくなるかも','怒ってる人をさがす','なぜ人は怒るのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','1','A','','なんで負けてるのにキレたり煽ったりするんだろう🤔','ゲーム下手な人ほど負けてまで煽ってキレるのか🤔','多分、相手が強すぎて勝てないから  キレのかもしれない🤔','なぜゲームで負けただけで相手の人はそんなにキレて煽ってくるのか  その理由を聞く','ゲームで負けてクッソキレてる人に聞いてみる','その他','相手が死ぬほどキレたり煽ったりしてくるのか  理由もわかるし相手の気持ちもわかる.','まず、ゲームで死ぬほどキレたり煽ったりしてくる奴に聞く。','たかがゲームで負けただけで小中学生はキレたり煽ったりしてくるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','2','A','','なんかスポーツできる人頭いい人すくないな','なんでスポーツしてる人は頭がいい人が少ない気がするのかな','スポーツしている人は勉強が苦手な傾向にあるのかもしれない','運動ができる人に実際に聞いてみる','運動できる人の気持ちになりきったらわかるかも','保健体育','達成感','どのようにすすめるか明確にする','運動ができる人は勉強ができないイメージがあるのはなぜ','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','3','A','','曲っていろんな楽器を使ってできてるな','なんでこんなたくさんの楽器を使っているんだろう','全部の楽器をカバーしてみたら楽器ごとの役割がもっとわかるかもしれない','楽器ごとの役割について調べる','楽器(ギター、ベース、ドラム)をすべてやって一曲カバーしてみたらわかるかもしれない','音楽','楽器が持つ役割や、どういう風に音が重なって曲ができているのか知ることができるはず','具体的にどういう風に進めていくか考える','それぞれの楽器が持つ役割ってなんだろう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','4','A','','サッカーでゴールを決めたらめっちゃ気持ちい','なんでゴール決めたら気持ちよくなるのか','ゴールの仕方によって気持ちよさは変わるのか','なぜゴールすると気持ちよくなるのか、また決め方によって感じ方は変わるのか調べる','気持ちよくなる原因を調べる。いろいろな決め方をして違いがあるのか確かめる。選手の喜び具合を見てどうなのか考える','保健体育','爽快感があるゴールをして見る人を魅了できればサッカーの人気が少しでも上がる。','気持ちよくなる原因について調べる','なぜゴールを決めると気持ちよくなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','5','A','','','','','ウォンバットについて調べる。','タブレットや図鑑などを使ってウォンバットについてたくさん知ってからなぜウォンバットはあんな見た目をしているのか、なぜあんなに硬いお尻をもっているのか、を考えたいと思う。','理科、国語','ウォンバットについてたくさん知れる。','ウォンバットについて調べる。','ウォンバットとはどういう生き物なのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','6','A','','ハンターハンターを見て、超能力すごすぎる！うちも超能力使いたい！','超能力ってうちらだせるのかな！？','もしかして、修行を重ねたり練習を積み重ねることで超能力は使えるかもしれない！','自分も超能力を使えるようになる','直観と、マインドフルネスとメンタリズムなどについて知って自分たちも実践する。','国語・理科・保体','超能力を身に着ける','地道に練習や鍛錬をしてみる。','超能力をみにつける‼','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','7','A','','ジャンシューうまくなりたい','確率上がるのかな','場所によって変わるのか','ジャンシューについて','動く','数学、保体','試合で入る','インターネットを使って調べる','ジャンプシュートの確率上げる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','8','A','','どこでもドアがほしい','どこでもドアって作れんのかな','無理なのかも','なぜどこでもドアが欲しいと思うのかどうやって作られているのか','ドラえもんを見る。原理を調べる','理科、社会','どこでもドアについてわかるはず','どこでもドアについて調べる','どこでもドアはつくれるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','9','A','','フリーキックはいるのかっけー','どこか打ったら入りやすいのだろうかまたどのようにしてけったら入りやすいのだろうか（自分にとって）','ペナ外の真ん中から売ったら入りやすいかも、あと少しカーブをかけたら、キーパーがとりにくいかも。','どこからどのようにして打ったら、一番入りやすいかを明確にする（自分にとって）','蹴って確かめる','体育、数学','フリーキックがうまくなる','実際にけってみる','どこがフリーキックが入りやすい場所か（自分にとって','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','10','A','','一次関数が数学の単元の中ででよくできる','なんでできるのか(算数の中で得意な計算がよく使われているのか)','一次関数にはほかの単元にはない面白さがあるのか','','','数学','一次関数が得意になる人が増えるかも','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','11','A','','りんご飴おいしい','給食で出たことない','作るのが大変だからなのかも','学校の給食でフルーツ飴を出すにはどうしたらいいか','フルーツ飴の栄養素とかを調べて、給食に出すメリット・デメリットをみつける','家庭科','給食でフルーツ飴がでるかも','インターネットを使って調べる。友達に話を聞く。','どうしたらフルーツ飴を給食に出すことができるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','12','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','13','A','','無断転載は批判されがちだけどみんな普通にyoutubeとかで見てる','著作権法がそこまでネットの無断転載に対して抑止力になっていないのかもしれない','著作権法がネットに対応しきれていないのではないか','著作権法がネットに対応しきれていないのではないかを明らかにする','ネットの過去の事例から分析する。','社会','法律やITの知識が増えるかも','wikipediaなどから過去に起きた事象を元に考える。','著作権法はネットに対応しきれていないのではないか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','14','A','','自分に似合った髪型がわからなすぎる','その人に似合う髪型とはなんだろう。','顔の形やパーツが影響しているのかもしれない。','様々なタイプの人を例にしてそれぞれに似合う特徴とそれは何が基準になっているのかを明らかにする','友達にいくつかの顔の形やタイプと、髪型を見せてこれにはどれが似合って見えるかなどアンケートとる','美術','これからさらに自分磨きできると思ったから。','様々な顔の形や髪型を調べてアンケートを作る。','「その人に似合った髪型」とはなんなのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','15','A','','最近の週刊ジャンプはなぜ人気がないのか','過去最大レベルのジャンプ暗黒期はなぜいまなのか','中堅の作品はあるが(大体もう終わるけど)、看板作品はほとんどない、変わらない','ジャンプの人気作が近代急激に減った理由の解明','今のジャンプのメンツや、過去のメンツ、支持層等を調べて、考察する','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','16','A','','ジャンプ力伸ばしたい','なんでみんなそんなに飛べるのだろう','運動やったりしている人はジャンプ力がある','本探求では誰でもジャンプ力70センチ位飛べるようになる方法やジャンプ力をがあるメリットデメリットというところまで明らかにしていきたい','今に自分のジャンプ力を計測し、ジャンプ力をよくなる方法を調べ実行。また、フォームなども陸上部の方々に聞いて改善してみたりもしたい。','保体','ジャンプ力を鍛えることにより下半身の筋力の上昇や体幹などが鍛えられけがの予防にもつながる。','自分のジャンぷりょくを計測しこれからやることの計画を立てる','じゃぷんぷ力を上げるためには何をすればいいのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','17','A','','肌が黒い人がこの学校に多い','なんで日焼けして黒くなるのか','日焼けすることのメリットはあるのかどうか','今回の探究ではなぜ肌が黒くなるのかと黒くなった時のメリット、デメリットを明らかにする','肌が黒い友達の普段の生活を調査してみる。','理科、保体','黒くなる原因がわかり日焼け対策ができるかも','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','18','A','','昔から人気なものってすごい','なぜ今も昔も人気なものがあるのか','年上の人が年下の人にこれいいよって言ったからか','なぜ昔から人気なものがあるのか理由を知る','ドラえもんみたいに昔から人気なアニメについて調べて共通してるものを知る','不明','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','19','A','','作曲家さんたちが作っている曲はすごい。','作曲家さんや曲を作っている人たちは何を意識して曲を作っているのか','イメージかあるからそれに合わせて作っている？','本研究では音楽とのつながりを調べる','人気の曲の分析。どうして人気なのかを調べる','音楽','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','20','A','','記憶ない','なんで記憶ないのか','インパクトがでかすぎて覚えてないのかインパクトがなさ過ぎて覚えてないのか','なんで記憶が飛ぶのか一回考える','寝たらわすれちゃうのか','保体','記憶をなくさずいられるかも！？','友達に記憶なくしたことあるか聞く','記憶がなぜなくなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','21','A','','地図を見ていたら不思議・読めない地名があった。','何で読めないような地名をつけたのか','歴史が関係してるかもしれない','不思議・読めない地名を読めるようになる。','その土地にあるものや言語などを調査してみる。','社会、外国語','初めて見た地名も読めるようになるかも','','読めないような地名がどうしてあるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','22','A','','','','','','','保体','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','23','A','','みんなしあわせそうだな','ひとがおもうしあわせとは','どういうときにしあわせとかんじるのか','しらべる','しやわせについてを調べる','理科・国語・道徳・保体','','','人にとっての幸せとは？を調べたりやってみる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','24','A','','音楽は集中力を上げる？','音楽を聴きながら勉強したら成績が上がるのか','音楽の中でも種類別に分けて考える','ネットとかで詳しく調べる','音楽の中でも集中力を上げる曲と下げる曲があるかもしれない','音楽','今年受験生だからそれが生かされるかも','新たな問いを調べる','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','25','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','26','A','','友達関係って難しい','周りに悩んでる人とかもいるから','なんかをしてしまったのかもしれない','人間関係が悪くなるのか考えてみる','友達と関係が悪くなったことがあるか聞く','保体','これからの人間関係困らなくなるかも⁉','人間関係とは何かしらべる','人間関係','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','27','A','','ギター弾いてみたい','もってない→作ればいい','どうやったら弦と箱だけで音が鳴るのか','音が鳴る仕組みを明らかにしてなにか楽器を作りたい','糸とかティッシュの箱とかを使ってなにも調べずに作ってみる','音楽・理科','新しい独特な楽器ができそう','','音を奏でるためには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','28','A','','この身長でジャンプ力伸びたら絶対ダンクできるだろーなー','どうやったらダンクできるか、今の自分の身長、体重、筋肉質でいけるのか','ダンクができるかもしれない','あと何センチあればリングにまず届くか、何センチ飛ばなきゃダンクできるのか、どの部位をもっと使わなきゃいけないのか。','今の自分の垂直飛び、立ち幅跳び、リングまでどれぐらいかを調べる。','体育','ダンクできるかも','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','29','A','','海やスポーツなどで外で遊ぶのが好き。','周りの子よりなんで黒いのか。','日焼けするのとしないのでどう違うのか。','陽に当たるとどうして焼けるのか、逆に陽に当たらないとどうして黒さが引くのか。','焼けている人と焼けていない人での過ごし方の違いを見つける。','理科・保体','焼けたくない人と焼けたい人の方法を見つけられる。','どうしたら焼けるのか','陽に当たるとどうして黒くなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','','30','A','','図形って身近なのに難しい。','図形の共通点とは？ 図形の面白さとは？  人が美しいと思う形は？','線や点が集まってできている。  人間が手を加えずに自然とできた図形(かたち)を美しいと感じる？','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','31','A','','なぜ人は「楽しい時間」や「とても集中してる時間」を早く感じるのか','自分の好きなことをやる、集中してるとき、はあっという間に時間が過ぎるのに自分が嫌いなことをやってるとき時間が長く感じるのはなぜか','楽しい時や集中してるときはそれだけに夢中になっているから時間を意識していなくて短く感じるのではないか','本探求では、人が時間の流れを状況によってどのように感じているかを明らかにする。','集中してるとき時間を早く感じる条件や理由についてインターネットなどを使って調べる。','理科、数学','楽しいことをやってる(集中している)＝時間が早くすぎるだから嫌なことをしてるときも時間が早くなるかも','','集中してるときなんで時間が早く感じるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','32','A','','黒黄同盟の新しい君主国構想に興味がある','じゃあなぜハプスブルク帝国などの多民族国家は崩壊したのだろう','多民族が共存するための君主という存在は近代主義にどうして敗北したのか','本探究では、ハプスブルク帝国の歴史を中世あたりまで復讐する','「ハプスブルク家の歴史を知るための60章」を活用する','社会','世界史の楽しをより多くの人に分かってもらえるかも','ハプスブルク帝国の歴史を近代まで復習する','なぜ多民族国家は崩壊したのだろうか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','33','A','','自転車のペダルを効率よく回したい','どうやったら効率よくペダルを回せるのか','ペダルに力をかける具合によって変わるのではないか','本探求ではいかに楽に力を利用できるのかを明らかにする','力と効率について調べる','理科、','ペダルの踏み方を意識することで速いペースで長距離ライドができる','うまい人の力のかけ方について','ペダリング効率のいいひとは何を意識しているのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','34','A','','いい人生を送りたい','お金があれば人生は幸せになるのか？','楽しくいい人生って具体的にどんなの？','本探求では俺が人生を一番楽しく送れそうな方法を探す','俺がやっていて楽しいと感じるものとこの先楽しく送る方法','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','35','A','','勉強に集中したい','川のせせらぎとかの自然音は、集中力UPやストレス解消にいいらしいけど、それはなぜか','なぜ集中力は変化するのか','本探究では、集中力について明らかにする。','集中力が変化するのはなぜか。五感別に調べ、表にまとめる。','理科、音楽、数学','集中力の性質を知ることで、勉強を効率的に進めることができるかも','集中力が続かないときの周りの環境のアンケートをとる','集中力はなぜ変化するのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','36','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','37','A','','女性名詞は必要か','名詞は一種類でいいのではないか','名詞に性がある言語とない言語ではどんな違いがあるのか','本探究では、複数の言語を参考にしながら語学、歴史、文化的な面での違いを知る。','どの言葉には名詞に性があるのかを知り、具体的な例を集める。','英語','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','38','A','','日本と海外の違いについて気になる','日本と海外の違いは？','日本と海外の教育制度の違いは？','本研究では日本と海外の教育制度の違いについて細かく調べる','日本と海外の教育制度について調べてまとめる','社会','海外の人たちの教育を真似してみると何か得られるものがあるかもしれない','ネットや本などでの情報収集','海外と日本の教育制度について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','1','A','','ゴラッソはどうすれば決まるのだろうか','デルピエロのような理不尽カーブシュートはどのようにすればうてるのだろうか？','決まった角度や当て方があるのではないか','この研究ではデルピエロのようなカーブシュートをどのようにすればうてるかを検証します。','デルピエロのようなカーブシュートをどうすればうてるかという情報を集めて、それをもとに蹴り方を変たりしてみて自分専用の止められないカーブシュートを作り上げる。','保体、理科','サッカーの試合や高校に行ってからサッカーをするにあたってどんな局面でも打開できる絶対に止められないカーブシュートは武器になるので、得点をどんどん決めれるしチームのエースになれる。','まずは普通に今の自分のうち方でうってみてデータを取る。','止められないカーブシュートを蹴る方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','2','A','','スパイダーマンってかっこいいね','なぜ奴は壁を登れるのか','もしかしたら俺もできるかもしれない','普通の人間でも壁を登れるのかを明らかにする','蜘蛛がなぜ壁を登れるのかを調べる','理科','壁が登れるかも','','スパイダーマンみたいに壁は登れるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','3','A','','サッカーの細かいドリブルと力強くコントロールが良いキックについて(サッカーあんましたことないほぼ初心者)','ワールドカップを見ていてどうしたら相手にとられないドリブル突破と力強いシュートができるのか気になった。','その人の弱点や瞬時の判断ができるから❓(サッカー選手、友達でうまい人など)','本探求では、ドリブルの仕組みや、キックの角度や威力の性質を理解する。','ほかの人たちと何が違うのか、何が同じなのかを比較する、自分とその人のサッカーのドリブルとシュートの基準など。','保体 数学','サッカーをしている人や、やったことがない人でも自分が実際に検証し、みんながわかりやすい説明をしたい。(あまりしたことないけど自分が興味を持ち、他の人達に興味を持ってもらいたい。)','早速自分の実力を確かめて、どのぐらいうまくなるのか検証したいです。「サッカーやっている人においつけるか？」「キックの速度など現在90キロ」','繊細なドリブルと力強いキック(シュート)について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','4','A','','絶叫系の乗り物が好き、苦手だったけど急に好きになった','どうして好きになったのか？なぜハマるのか？得意な人と苦手な人の違いは何？楽しいとわかっていてもどうして乗る前はいつも緊張しちゃうのか？','何か理由があるのかもしれない','問いを明らかにしたい','調べたりアンケートや実体験をもとに理由を考えてみる','','もやもやが解消されそうあと考え方も変わりそう前よりもっと楽しめる','アンケートの内容を考えてみる。','問いを明らかにすること！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','5','A','','サッカーの守備でファウルだけどファウルにならない守備の仕方・スライディングですぐに立ち上がって追いかけて潰す方法','一流のサッカー選手が守備うまくてファウルみたいなプレーがファウルを取られないから。また一流のディフェンダーになればなるほどクロスやシュートフェィントにかかってスライディングもしくは途中までしかけてもすぐに潰すからどうやればそういう風になるか気になる','身体能力・重心の位置・ゲームの試合展開を読む力・空間把握能力・瞬発力・日ごろからのトレーニング・危険察知能力・ずる賢さなどと考察する','本探求では、スライディングでの人を削った際にどこまでならファウルを取られないかや競り合いの時のプッシングした際にどういう風なやり方で競り合いに勝って尚且つファウルにならないか。すぐに対応できる方法・重心の位置などについて理解する。','友達と１対１をしたときにもう一人の友達に審判役を担ってもらい、いろんなファウルになりやすいプレーをやってみるや複数人でのコーナーキック、フリーキックなどの競り合いが起きるプレーなどをやる。','保体','サッカーをするときに初心者でもここまでならファウルはとられないなどと基準がより明確になり、理解しやすく尚且つ説明がしやすい。','安全面に配慮した状態である程度のプレーをし、一個一個理解・分析しやすいところまでプレーをする。また分析するために動画を取り、一個一個じっくり確認して次につなげる。','ファウルがファウルじゃなくなる方法とゴールの危険になりうるプレーに対する対応の仕方','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','6','A','','不協和音って「悪い」音がする','なぜ不協和音って悪いんだろう','人間が嫌いな音だからかもしれない','何によって不協和音が「悪い」というイメージを持つのかを明らかにする、ただたんに人それぞれの意見や体のつくりによって違うのか、または全人類共通な不協和音についての意見があるのか、または「悪い」のではなく、本当は別の表現があるかを明らかにする。','不協和音について調べる、自分の音楽などの実力をうまく利用して理由を明らかにする','音楽、理科、保体、社会','不協和音が「悪い」というより別の表現の仕方を求める','自分ができる範囲で音や他の人と一緒に実験し、または楽器とか使って調べる、人の不協和音についての意見を集める。','不協和音がなぜ「悪い」のか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','7','A','','世界で活躍したい','世界のトップクラスで活躍出来る人の共通点','フィジカル、技術、メンタル、モチベーションなど','本探求では世界のトップクラスで活躍する選手の共通する体格や体の使い方（スポーツによる）を明らかにし、それを踏まえて今からでも出来る体作りや、練習、体の使い方などを今後実際に行ってみる','スポーツごとに世界で活躍する選手の共通するものを調べる','理科、保体','高校に入った時に一年がベンチ入りもしかしたらスタメンになれるかも。メンタルなどはスポーツをしていない人でもためになるかも','','世界のトップクラスで活躍する選手の共通する事を調べて、自分ごととして今後に繋げる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','8','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','9','A','','じゃんけんで勝ちたい','どうしたら勝てるのか','相手が何を出すのかが分かれば勝てる','本探究では1対1じゃんけん 片方宣言心理戦におけるじゃんけんで原外生徒に勝ちやすい方法を明らかにする。  （ここでは、1対1のじゃんけんで、他方の人のみがじゃんけんの前に出す手を宣言してじゃんけんを行うゲームを1対1じゃんけん 宣言心理戦と呼ぶことにする）','原外生徒と1対1じゃんけん 宣言心理戦を行い、統計的確率から、出しやすい手の傾向を考える。またそこから、どうすれば一つの手を出してくれやすくなるのかを考える。','数学  （本探究では主に数学で習った統計的確率を用いて勝利方法を考えるが、考察や仮説を考える上で心理学的なことや生物の構造の理科的なことを用いる）','原外の給食じゃんけん他、じゃんけんをする時に有利な状況にできる','まず初めに宣言する手と、出す手を意図的に考えずにじゃんけんを原外生徒として、確立を求め、その時に相手が出した手を基に勝ちやすい方法を考える。','1対1じゃんけん 片方宣言心理戦におけるじゃんけんで原外生徒に勝利する方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','10','A','','最近めっちゃ夢見る','なんで夢見るんだろう','現実と関係があるのかな、夢の中で完全に自由にうごけないかな','夢について調べる。自分がどんな時に見るのか調べる。夢の内容も何か関係しているのかも','悪い夢は深く調べず、まずは良い夢だけ調べる。夢をもしかしたら見れない日が続くかもしれないから過去の夢も思い出す。夢の記録は簡単に、キーワードや印象に残ったことだけメモを取る。時々友達の見た夢も聞きたい。','保体、社会？','夢操作できるかも','夢について調べる','夢って何？夢はどういう精神状態の時に見るのか、そもそも夢を操作できるのかな','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','11','A','','テンポが速い曲ってテンション上がる','そもそもテンションが上がるって何？','テンションが上がるときの条件がわかれば共通点がわかる？','気持ちが上がっているときの条件とテンポの速い曲の関係性を見つける','音楽を聴いてテンションを上げてみる。自分の体の変化について調べる','保体、音楽','落ち込んでるときとかにより効果がありそう！','まずはテンションの高い音楽を見つける。','テンポの速い曲と気持ち、身体の関係性','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','12','A','','運動すれば頭よくなるのか','運動できたら難しい問題も解ける','スポーツの頭の使い方なのかもしれない','頭がよくなるまで','実際に運動をする','保体','頭いい能力が身につくかもしれない','まず原点に戻る','スポーツをすれば頭がよくなるかもしれない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','13','A','','どういう絵やイラストだと人が引き付けられるか','この絵はあまり好みじゃないな、とかこの絵(イラスト)好みだなとか違いがあったからなんでだろうと思ったから。','キラキラして透明感のあるイラストや、パッと見のインパクトと見る人の感情を動かす工夫がされているのではないかな、と思う。','人気なイラストレーターさんや人気なイラストや、絵を明らかにしたい。(その人たちはどういう画材を使って書いているかなど。)','まずは興味のあるイラストレーターさんの絵やイラストを調べる。家に帰ってからどういうイラストが多いのか調べる。','美術','自分でイラスト書くときに役立ちそう。','イラストに触れる','どういう絵やイラストだと人が引き付けられるのか(魅力を感じる)','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','14','A','','ギターうまくなりたい','ストローク以外の技法にはどんな効果があるのだろう','ハンマリングやスライド、チョーキングはなぜ使われるのだろうか。','ギターで使われる技法を多く学ぶことで自分の表現力が増して個性を出せるようになるから','自分の知っている曲をスライドやチョーキングなしで引くとどうなるか調べる','音楽','ギターの技法に触れることで自分の色を出せるようになる','曲に触れてみる','ギターの技法による表現の幅の広がりを調べる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','15','A','','長距離を走ると脇腹が痛くなることがある','なぜ痛くなるのか','走るときの動きや呼吸の仕方でその痛みを抑えられたりするのではないだろうか','どうしたらその痛みを抑えられるか','痛みが抑えられる呼吸の仕方や動きを調べる','保体、理科','長距離を走っているときの脇腹の痛みが軽減されて走りやすくなる','長距離が得意な人に聞いてみたり、ネットで調べてみる','なぜ長距離を走ると脇腹が痛くなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','16','A','','記憶力を良くしたい','どうして覚えていることと忘れることがあるのか','大事なことだけを覚えているのかも','覚えていることと忘れることの違いは何か、どうしたら記憶力はよくなるのか、自分の意志で忘れることはできるのか','記憶と脳の関係、記憶に残ることの共通点、','理科、保体、音楽','自分にとって大事なことを覚えていられる、暗記科目が得意になる？','覚えることの仕組みを調べる','記憶力がよくなる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','17','A','','蚊にさされたくない','どうやったら蚊にさされないか','蚊が苦手なにおいや色を取り入れればいいのでは','蚊に刺されないようにする方法','蚊の苦手なものを調べる','理科','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','18','A','','カップ麺を食べたい','待ち時間ながい','集中しているからかも','なぜ時間の感じ方が違うのだろうか','調べる、','理科','面白い知識が付きそう','早く感じるとき、長く感じるときを調べる','なぜ時間の感じ方が違うときがあるのはなぜなのだろうか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','19','A','','性格っておもしろい','血液型も関係してる','血液型がわかったときにその人の性格はわかる','血液型と性格の関係性','血液型と性格を比較','理科','相性のいい人が見つかるかも','特性を調べる','性格ってどこから来てる？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','20','A','','','','','','調べる','保体','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','21','A','','声を出しながらスポーツをすれば自分のベストが出るんじゃないか？','声は体と連動しているのか？？','心理的な問題なのかも？？','声とスポーツの関係性','調べる','保体、音楽、国語','パフォーマンス向上','保体、音楽の観点から条件などを調べる','声とスポーツの関係性','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','22','A','','テニスで前衛をするときにストレートを抜かれることがある。ポーチ出れない。','なぜ人によって反射神経の良い悪いがあるのか','日頃から運動していて咄嗟に動くのに慣れているから？','反射神経をよくする方法','反射神経が良い人の特徴を考えてみたり、逆に反射神経が悪い人はどうなのかを考える','保体、理科','テニスで前衛がうまくなったり、瞬発力が上がってボールを触りやすくなる','反射神経が良い人の特徴を調べる','反射神経をよくするにはどうすればいいのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','23','A','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','24','A','','勉強が面白くない','なぜゲームは楽しのに勉強は楽しくないのか','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','25','A','','友達に両利きがいて、両利きになってみたいと思った。','生まれつきの人もいるけど両利きになる方法はあるのか','利き手じゃない方の手で生活をしたり、トレーニングをしたら日常で使えるのではないか。','生まれつき両利きの人と同じくらい自然に両手を使えるようにするためにはどうすればいいか。なぜ利き手じゃない方の手で作業を行うと神経が通ってない感じで動かしずらいのか。','利き手じゃない方の手に慣れるトレーニングを調べる。部活で左手も余裕で使えるくらいまで上達させる','保体','部活面では左手を使ったシュートやプレーが上達する。勉強面や書くことの動作は今まで全く使えなかった部分が使えるようになる。','両利きの人は考え方などが違うのか、またどのようにして動作を行っているのか詳しく調べる。','両利きになるにはどうしたらいいのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','26','A','','マイケルジャクソンのアルバムはなぜあんなに売れたのだろう','彼の独特なvoiceには人を引き付ける力があるのかも','その声には幼いころからの生活が関係している？','マイケルの歌声だけでなく、曲のリズムやメロディにも注目し、どうしてそんなに魅力的な曲を作ることができるのか','マイケルの歌を古い順から聞いていき、歌声、曲に注目して調べていく。','音楽','実際に歌う方法や歌声について知ることができれば取り入れる。','マイケルの歌を聴く。','どうしてマイケルジャクソンのアルバムは超売れたのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','27','A','','似合う服とは何だろう','なんでみんな似合う服が違うのだろう','服の形や色が影響しているのかもしれない。','似合う服とは何が影響しているのだろう','自分や友達の似合う服を調べそれぞれどのような特徴があるのか調べる','美術 理科','自分や友達の似合う服や色を見つけることができる','パーソナルカラーや骨格について詳しく調べる。','服','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','28','A','','デッサン上手くなりたい','デッサンの上達に必要なものって何？','（段階的に）意識するポイントがある、時間をかける、使う道具によっても違う','デッサンをより良く上達するために自分に一番必要なことを明らかにし、それを実践して結果として残す。','実際に美大や藝大の卒業生や現役である美術学院の先生にどのようなことを大切にしていたかなどを聞く。','美術','今後のデッサンの成長につながる','いろいろな方向性を知りたい','デッサンを上達するために','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','29','A','','なかなか身長が伸びない','どうやったら身長が伸びるのか','運動（スポーツ）をしたり野菜、お肉（タンパク質がある物）を食べたら身長が伸びるのではないか','身長が伸びる方法','身長が伸びる方法を調べる','保体','ジャンプと縄跳び','','身長を伸ばすためには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','30','A','','朝、起き上がるのが大変だと感じる。ダラダラしないようにしたい。','なぜ起き上がることが大変なのか。','起き上がり方に問題がある？二度寝の気持ちよさを知っているからから？目覚まし時計の音楽や夢が影響？大変だと思うからおきあがれないのかも','楽に起きれる方法を明らかにする。また、寝起きの脳みそについて明らかにする','楽に起き上がれる方法、寝起きにいい曲、寝起きの脳みそ、夢で朝の気分が変わるのか調べる。','音楽、体育、理科','一生役立つ','寝起きの脳みそについて調べる。','起き上がることが楽しくなる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','31','A','','日焼けしたくない','どうして焼けるのか','日焼けするとメリットがあるからかもしれない','どうやって日焼けするのか、なんで黒くなるのか、日焼けするとどんなメリットがあるのか、どうやったら白くなるのか','どの日焼け止めが一番効くのか、どんな対策が一番効くのか調べる','保健、体育・理科、家庭科','日焼けする 仕組みを理解することで日焼け対策が今よりもよくなる','日焼けの仕方を調べる。','なんで日焼けをするのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','32','A','','心理学好き','なぜ心理的行動を起こすのか','心理的行動を起こすことによって気持ちを整理しているのではないか','なぜ心理てき行動が起こるのか','なぜ当たるのかもしくはあったているように感じるのか調べる','理科 社会 保体','人の感情や行動のメカニズムを科学的に理解できるようになる','いろいろな心理的行動についで調べる','いろいろな心理的行動とそのりゆう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','33','A','','どうしても就寝時刻が遅くなってしまう','「早寝早起きは大切だ」とは言われているが、別に昼間に寝てもいいのではないか？','早く寝て、朝にすっきりとした状態で起きたほうが、１日の始まりが良いのではないか。','早寝早起きが大切とは言われているが、結局はいつの時間になるのが良いのかを、明確にする。','健康に注意して、やってみる。そして、昼間に寝ることは、調べてみる。','理科、保健','自分が何時に寝て、何時に起きるのがよいのかを調べ、自分のこれからの生活に生かす。','早く寝ることの大切さについて調べる。','なぜ、早寝早起きが大切なのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','34','A','','最近自分で「面倒くさい」と感じてしまう','どうして面倒くさいと感じるのか','自身の関心や興味によってその物事に対する感情は大きく変化するのではないか','本研究ではなぜ「面倒くさい」と感じるのかを明らかにする。','今までの生活を振り返る。','理科、保健','自分がなぜそう感じてしまうかを考え、それを対策してこれからの生活に生かせそう','他の人はどう感じているのかを調べる。','なぜ面倒くさいと感じるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','35','A','','空を飛びたい','なんで鳥は飛べるのに人間は飛べないのか','人間には羽がないから飛べないのではないか','鳥の羽と人間の腕の違い','一回飛んでみる。','理科、歴史、体育','人間の進化の過程や体の構造、ほかの生き物との違いが知れる。','調べる前に自分で実証してみる。','なぜ人間は飛べないのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','36','A','','人と比べてしまうことが多い','人はどうして比べてしまうことが多いのだろう','自分の実力を図るために他人と比べてしまうのではないか','人が他人と比べてしまう要因','沢山の人にアンケートをとって、その実態を調べる。','国語・理科・体育','自分に自信をもって生きることができる','調べる内容や目的をもう少し整理し、自分の実体験を思い出す。','人はどうして他人と比べてしまうのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','37','A','','都大会行きたかったな。でも最初のときからだいぶタイムが伸びたよな','3年間の中でタイムが自己ベストより遅かったことが三回あった→それはなぜか。','1回目：長時間、日に当たっていたから？  2回目：2週間連続のレースの疲労があった。  3回目：やる前に800mをやっていたから？','タイムが落ちる理由を明らかにし、まだ伸びしろがあるのか考える。体に関係あるのならそれも調べる。','その日を思い出す。インターネットで調べる。','保健体育・理科','部活・自主練習での練習方法を明確にすることができる','タイムが落ちる原因をまず調べる。','どうしてタイムが落ちるときがあったのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','38','A','','勉強が長く続かない','どうしたら集中できるのか、なぜ集中できないのか','音楽とか聴きながらなら曲一生流れてるから勉強も集中できるかも','一番集中できる勉強法、集中できるものとできないもののちがい','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('9','A','47','B','原宿 外苑','Mrs.GREEN APPLEの曲が好き！','なぜミセスの曲はみんなに人気なんだろう？','使われている歌詞の言葉が心に響くのかもしれない','本探究では、ミセスの曲の魅力を明らかにする。','みんなが好きなミセスの歌詞を調査する。','音楽、国語、社会','人気曲の共通点がわかり、流行に敏感になるかも','調査方法についていろいろな方法を知りたい','流行の曲はどうして流行っているのか','人間が好む特定のリズムがあるのではないか？音楽で実験してみてはどうか（◎◎）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','1','B','','絵を描くことが好き！','絵を描いている時にどんな工夫をしている？','影の書き方とか、体の書き方も工夫かもしれない','絵を作る難しさ／絵を作っている途中の美しさを明らかにする','みんなの（美しさ的）好きなマンガ／アニメを聞いて見る','美術','絵を上手な人増えると、絵を見ている時にその絵てどういうこと説明している／表しているを簡単に見つける','他の人にとっていっぱいなことを表している絵をその人にとって何の気持ちを表していると思っていると聞いて見る','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','2','B','','長距離が速くなりたい！','長距離が速くなるにはどうすればいいだろう？タイムには体調や天候、気温も関係あるのであろうか','短距離のフォームとは違うフォームで走るといいかもしれない','本探求では長距離の歴史を知り、長距離はどうしたら速くなるのかを明らかにする','長距離の選手と自分を比較し、どう違うのかやどこを改善すればいいだろうかを知り、実験してみる','保険、体育、社会、数学','部活の大会でいい結果を残せる。 ・体育の授業や体力測定の時に有利 ・歴史をマメ知識で知れて友達に教えたら友達も速くなるかも！？','まず、選手の走り方の特徴などを知る','長距離はどうしたら速くなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','3','B','','','','','','','、','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','4','B','','成長期が終わるまでに身長を伸ばすには？','身長を伸ばすには何をすればいいのだろうか。身長はどんなものと関係するのだろうか。成長期が終わっても身長は伸びる？→成長期っていつ頃？','運動、「食べ物」、「生活」、DNA、遺伝子','','','体育、理科、数学','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','5','B','','ゲームが楽しい','なぜゲームは楽しいのだろうか。','ストーリーなどが良いから','なぜゲームは楽しいのか明らかにする。','ネットなどで調べる','技術、国語','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','6','B','','スポーツが好きです！','色々なスポーツの起源は何だろう？','人々の娯楽として作られたのかもしれない','本探求では色々はスポーツ起源やルールを明らかにし  自分が好きなスポーツ以外でのスポーツで楽しさを見つける。','皆が好きなスポーツを調査しそれを調べ始めてやる  スポーツもあるかもしれないが実践してみる','社会、体育','皆の好きなスポーツが何か分かり  自分の「好き」にも向き合えるようになるかも。','みんなにアンケートを取り  皆の好きなスポーツを調査する。  始めてやるスポーツもあるかもしれないが実践する。','色々なスポーツの起源やルールを調査して、  自分の新しい「好き」を見つける。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','7','B','','惑星を壊すゲームにはまってる','地球を変形させたらどうなるだろう','人が住めなくなるかも','本探究では地球の形を様々にし、どんなことが起きるのか明らかにしたい。','みんなが住んでいる地球がもし丸じゃなくて様々な形になったらどうなるのか、まず重力について調査したい','理科 数学','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','8','B','','自分の体力が少ない','簡単な方法で体力が強くなるのか','体力が多くなる方法は大変なのかもしれない。','本探求では自分でもできる簡単な方法で体力が強くなるのかを調べる','実際の運動神経がよい人や体力が多い人の運動法を参考にして自分なりに毎日できるようにアレンジする','保体、数学','','','自分でできる体力がUPする方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','9','B','','絵が上手に描けるようになりたい','絵のバランスが取れないのはなぜか？','絵のバランスを上手に取る方法はあるのか？','本探求では、絵のバランスを上手に取る練習方法を見つけたい。','絵のバランスを上手に取れる練習方法やそのためにすることを調べる。','美術、国語、社会、','字のバランスがとれるようになる','自分に合った練習方法を見つける','絵のバランスをとる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','10','B','','バスケットボールが好き','vcn','外国に旅行に行った人がバスケットボールを面白いと思いに','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','11','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','12','B','','英語が楽しい！','なぜ日本の学校には英語の授業があるのだろう','もしかして世界で最も使われている言語なのかも。','本探求で英語がなぜ最も使われている言語なのかを明らかにする。','みんなが英語を喋れるために、簡単な言葉や勉強の仕方を調査する。','英語','みんな英語がうまくなって英語が楽しいって言ってくれるかもしれない。','自習をして自分に合う勉強法を調べてから、友達にどんな勉強法をしているか聞く。','英語をネイティブのように喋れる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','13','B','','テニスをうまくなりたい','テニスがうまい人の特徴は','もしかして自分とは違う練習方法をしてるかも','自分の部活の練習方法と上手い人の練習方法を比較する','部活のコーチやネットで調べる','体育','テニスが上手くなるのと部活の練習方法が増えるかも','最初は練習方法を調べる','テニスの上達について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','14','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','15','B','','亀が好き!!!!!!!!!!!!🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢🐢','亀の種類などを詳しく知りたい🐢🐢🐢🐢🐢🐢🐢🐢','もしかしたらめっちゃでかい亀の種類があるのかも🐢🐢🐢🐢🐢🐢🐢🐢🐢','本探求ではいろいろな亀の種類やとくちょう、飼っている亀のことを詳しく調べ、明らかにする🐢🐢🐢🐢🐢🐢🐢🐢🐢','みんなは亀が好きなのか、嫌いなのか、又はどちらでもないのか','理科','みんなが亀の魅力を知り、亀が好きになってくれる','まずは家で飼っている亀について','亀について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','16','B','','おばさんは何故若いことにこだわるのか','そもそも若く見えるわけがないのに年齢を偽るから','若い頃の時代に戻りたいからかも','何故おばさんは若いころが一番記憶に残るのかを明らかにしたい','AIとかに聞く（おばさんとかに聞くのは失礼だから）','道徳','みんなが何故おばさんが若いことに執着するか知ってもらえるかも','僕のままに何故若いことに執着をするか聞く','おばさんたちは何故若いころに執着するのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','17','B','','今自分は何に集中するべきなのか','自分はダンスを習っているが、それは何のためなのか','','本探究では、','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','18','B','','今バスケにはまってる','バスケがうまい人の特徴','色々な練習方法があるかもしれない','シュートやドリブルをうまくなりたい','うまい人の練習方法を見る','体育','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','19','B','','音楽を聴くのが好き！集中力がない！(家での勉強が続かない！！)','どうしたら集中力を高めることができるのか','好きなこと(音楽)をしながらなら集中できるかもしれない！','本探究では、音楽を聴きながら勉強することで集中力が上がるのかについて明らかにする。','調べる。→実際にやってみる、試してみる！(家で)','音楽、保健','集中力が高まって、勉強ができるようになるかもしれない！家での勉強がはかどるかも！？','','音楽を聴くことで集中力が高まるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','20','B','','生物が好き','生物はなぜ生まれたのかその起源は何か？それはどこからやってきたのか？','もしかしたら宇宙からのウイルスが地球で進化して生命が生まれたのかも','この探求で、生物の原点が何かを知れている状態にしたい','生物学をある程度勉強し、て一番最初にいた生物について調べて考えていく','理科','人間や動物が何から生まれてきたのかが分かる。','いろいろな先生と話して、より良い調査方法を聞いて参考にして、調査をしていきたい。','～何もない時代からなぜ生命が生まれたのかについて～','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','21','B','','空を飛べるようになりたい','なぜ人は空を飛べないのだろう','飛行機の特徴に合わせれば、飛べるかも','本探求では、どのようにしたら空を飛べるかを明確にする','飛行機の特徴を調べ、飛行機に合わせていき実行してみる','理科','未来の空飛ぶ車を早く開発できるかもしれない','飛行機の特徴を調べる。','人は飛行機を真似したら、空を飛べるかもしれない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','22','B','','生物が好き','なぜ生物についてわかっていないことが多いのだろう？','それだけ生物の進化が不思議なのかもしれない','本研究では生物の生態をちょっと明らかにする','実際に動物や虫の４体を集めて解剖する','理科','もしかしてだけどもしかしてだけそれって生物の何かを知れるんじゃないの','４体収集や解剖学について研究していきたい','ガ～ガキのやる解剖について～','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','23','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','24','B','','得意ではないけど地理とか歴史とかの国と国の関係が好き 宇宙とか地球の始まり気になる','小学生の頃はだいっっ嫌いだったのに何で急に好きになったのか？（社会）私がいるところはどれくらいの時間でできたのかな','私が好きになった理由は何だろう','どんな教科でも好きになれる方法を考える','中間検査があったのでそこで点数が高かった人にどんなやり方で勉強したかを聞く、楽しい教科のアンケートを取る。','社会','私が苦手な教科を克服し、学校に来る時の憂鬱が消え、考査の点数が上がる可能性がある。','','どんな教科でも好きになれる方法','');
