INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','27','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','28','B','','バスケのシュート率、ドリブル、を上達させたい','','実は簡単だと思っていたスポーツが難しかったり難しいと思っていたスポーツがかんたんだったりするかも','本探求ではスポーツの楽しさ、難しさを明らかにする','調べるスポーツをするときにやっている人に、楽しさ、こんなところが難しいを教えてもらう','体育','いろんなスポーツの楽しさがわかりそのスポーツにはまるかもしれない','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','A','29','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','1','B','','心理テストめっちゃ当たる','話したこともない人がなんでこんなに私のことを言い当てるの？','もしかして誰でも当てはまるものなのかも！','本探究では、なぜ自分が当てはまってると思うのか、だれにでもあてはまるものなのかを明らかにする','自分が当てはまってると錯覚しているのか、あっていたとしたらなぜわかるのか、友達に心理テストをしてみて自分の性格とあっていたかをアンケートする','たぶん何でもない','相手の行動の理由がわかるかも！！','まずは自分で心理テストをやってみて当てはまっているか、心理テストは本当に当てはまっているのか','心理テストの真実！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','2','B','','テニスを上達したい！','サーブ、ラリー上達の仕方。テニスがうまい人の特徴。','たくさん練習したり、特別ないい練習法があるのかも','本研究では、テニスの歴史や、先輩や選手を見てサーブの強いやり方など、コーチとかを見ながら練習法とか正しいフォームやうまい人の特徴をあきらかにしたい。','うまい選手とかとかをよく観察して細かい動き方を見てみる','保険体育、歴史、','部活とかでテニスがうまくなれるし、うまくなったら先輩に迷惑をかけなくてよくなるかもしれないかも。','コーチとかうまい先輩をよく見て観察する。','テニスが上達する練習法について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','3','B','','私生活で左も使えるようになりたい 両利きになりたい','右手がけがをしても左手で生活したい','左を使えた方が生活が楽になるかも','本研究では左手を使えるようになったら私生活はどれほど楽になるかまたどれほど上達するかを調べる','左利きの人の人にインタビュー，動画を見る','保体、理科？','私生活，部活でも楽になる','左利きの人を見る','どうやったら早く、うまく左を使えるか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','4','B','','サッカーがもっとうまくなりたい','なぜプロの選手はあんな簡単に相手を抜くのだろう？','プロのうまい選手は全員ほとんど同じようなプレーをしている？','本探求では、うまい選手はどのようなプレーをしているのかを調べて実践してを繰り返してうまくなる方法を明らかにする','うまい選手のドリブルの仕方や顔のあげ方などを調べる','体育、数学','共通点を見つけ、うまくなる方法を知れる？','具体的に、どんなドリブルの仕方をしているのかについて調べる','サッカーで主にドリブルがうまくなる方法について','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','5','B','','インターネット中毒になったことがある','なぜインターネット中毒になる？','面白いから','本研究ではどこでだれがいつこのような規制や制限をつくったのか。なぜこんなにインターネット社会になってしまったのか。人の心理と問題について明きらかにする。','政治、国民の声について調べる アンケートを取る','図書、道徳、歴史','時間の使い方がうまくなるかも','情報収集の仕方、アンケートの取り方','人の欲','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','6','B','','自分でプロバスケチームを作ってみたい','どうやってプロチームを作っているの？','もしかしたらその人たちも前の人から学んでいるかも','本探求では、プロバスケチームを作るための基本を調べる。','作るだけじゃなく、強くしたいし、自分のバスケにも落とし込みたい','社会、数学、体育','バスケチームの裏側が分かり、もっとバスケが好きになるかも！','調査方法を参考にしてみたい','バランスの良い夢のバスケチームを作る！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','7','B','','K-popのアイドルが好き','K-popはなんでいろんな国で人気なのか？','K-popには独自の戦略があって人気なのかもしれない','K-popが人気なのはどんな戦略があるからなのかを明らかにする','・K-popの歴史から人気になった理由をつきとめる・過去のグループをもとにK-popにはどんな傾向があって人気なのか','社会、音楽、体育','世の中ではどんなものが人気になるのかの傾向が分かる','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','8','B','','大森元貴のギターにあこがれた','気軽に練習するにはどうすればいいのだろう','かっこいいから','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','9','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','10','B','','ダンスが好き。もっと上手になりたい。上達したい。','ダンスが上手な人はどのようなことを練習しているのか','もしかしたら踊ることより基礎をやっているのかも','基礎と柔軟を中心として自分らしいダンスを見つける。','上手な人のダンスの動画をいっぱい見て研究する。','保体、音楽、','自分に向き合えて自分だけのダンスが出来るかも','ダンスの先生に聞く。ダンスのお友達にも聞いてみる。','ダンスが上達するためには何が必要で自分らしいダンスができるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','11','B','','海について','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','12','B','','左足を右足と同じぐらい強く打てるようになりた。','プロのサッカー選手は大体両足が使えるのか？','もしかしたら右足と同じようにけれないかもしれない。','この探求で練習すれば左足が使えるようになる。そして普段のサッカーでもそれを生かしたい','右足のホームを見てそれを意識してさらに手の位置や足の踏み込みなどを見て、見よう見まねでやる。','体育','左足を使えるようになることで、サッカーの試合でも左側にドリブルが出来てさらにシュートも打てるようになる。','左足のシュートがうまい人や左利きの人にコツを聞いてそれを参考にしながらやる。','左足を使えるようになる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','13','B','','勉強って必要なの？','なんで人生では勉強したことをほぼ使わないのに勉強しないといけないのか','考える力をつけるため？','勉強はなんで人生で必要ないといわれているのか、勉強をするメリットデメリットなど','インターネットで調べたり、勉強をやっていてよかったと思うことを友達とかに聞く','国語、数学、理科、社会、英語？','勉強をやる意味がわかって、勉強しよう！っていう気持ちになるかもしれない！！','データで調べる','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','14','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','15','B','','深海のなぞが気になる','なぜ地球の表面の七割は海なのに、月や火星などよりもわかっていないのか？？','‘‘七割‘‘って言ってるくらいだからそれだけ大きいってことだし、とても深い場所もあるから調べられないから？','深海のなぞをできるだけ誰よりも知る！！！！','まずはネットで調べる！！','理科：（地学、生物）  物理、技術：（最後らへんで深海だから、その深海の超高圧に耐えるためはどのようなモノ？が必要か）  地理：（海洋ゴミ問題など！！資源問題など！！）','知識が身につく！！生物や地学の知識だけでなく、それを解決するための「ロボット」や、環境、資源といった「社会」の知識までいろんな知識が得られる？','まずは深海を軽く調べたい！！','深海のなぞについて！！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','16','B','','スポーツが好き','','','','','','','','','');
