INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','18','B','','ゲームが好き','なぜ人はゲームに熱中するの？','ガチャやレベルアップが関係している？','なぜ人はゲームに熱中してしまうのか、その理由。人気なゲーム','人気なゲームを調べたり、みんなに聞く','理科','人気なゲームを楽しめて、ゲームより楽しくやる','みんなが好きなゲームを聞いて、なぜ好きなのかを聞く','なぜ人はゲームに熱中してしまうのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','19','B','','なぜプロ野球選手インコースが打つのが上手なのか','なぜプロ野球選手インコースが打つのが上手なのか','もしかしたらみんな何かの共通点があるかも','インコースを打てる高校生プロ野球選手の共通点を明らかにする','実際にプロ野球選手が打撃しているときのの動画を見る','体育','プロ野球選手の特徴がわかる','調査方法について色々な方法が知りたい','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','20','B','','足速くなりたい！！！','足速い人には共通点があるのか','みんなフォームが一緒なのか、、、','本探求足の速さの秘訣を明らかにする','毎月トレーニングを変えて一番効果のあったと思うやつも探す。','体育','足が速くなる','実践する','最短で足が速くなるには、、、！！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','21','B','','体力と足の速さの両方を向上させたい。','体力と足の速さの両方を一度に鍛えられるトレーニングはあるのか。','300ｍとか400ｍを全力で走ればいいのかも。','体力と足の速さの両方を鍛えられる方法を明らかにする。','実際にいくつかのトレーニングをしてみて、何もしていない状態の記録とトレーニングを行った後の記録を比べる。','体育','大会や体力テストなどでいい記録が出せる。','トレーニング法を調べる。','体力と足の速さの両方を一度に鍛えられるトレーニング法はあるのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','22','B','','流行の服がすき。','服の流行はどのようにできているの','','流行の服は、どのようにできているのかを明らかにしたい。','ケーポップや、他のアイドルの服も研究したい。','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','23','B','','ソフテニがうまくなって、試合でたくさん勝ちたい！','上手な人たちはどのように練習に取り組んできた？うまい人がたくさんやってる練習はなにか？','ラケットの振り方とか、足の動かし方のいい練習法とかがあって家とかでもたくさん練習してる？','本探究では、自分のやったことのない練習法をたくさん試してみて、自分の課題であるストロークとサーブにあう効率のいい練習法を明らかにする。','たくさんの練習方法とかを調べて実際にやってみて、いいと思ったのを記録したりして夏休み中などを使ってたくさんやる。また、それが何にいいのかを調べたりする。','体育','新人大会で少し練習の成果が出るかも。','自分の課題をすべて出して苦手なことも考える。','自分の苦手なサーブとストロークを完璧に！～ソフトテニス～','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','24','B','','本格的なプログラミングでゲームをつくりたい','どのようにすれば上達する？','上達にはプロに教えてもらったりとても長い時間が必要かもしれない','プログラミングを上達させるためにはどのように勉強や練習をすればよいのかを明らかにする。','プロに教えてもらうのは難しいかもしれないのでインターネットなどで検索して独学','技術','プログラミングのプロになって凄いゲームを作って将来金持ち','色々な調査方法を知りたい','プログラミングを上達させよう！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','25','B','','バスケうまくなりたい','どの様に練習したらいいのか？','上手い人に聞く','自分が足りないところを探してなくす','いろんな人の意見を聞く','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','26','B','','バレーが好き！もっと上達したい！','何故かサーブが入らない、','サーブが入らないのは、腕の力がないのかもしれない。','サーブが入らない原因を追究して、追求した結果をもとにサーブが入るようになるまで練習する。','バレーの選手や、バレーの本を使って調べて、自分はそこが足りないのかを検証しながら進めていく、実際に効果を感じられたら、練習用のルーティーンに加える','体育','部活の時に、色んなことを試せる、バレーを楽しむことや、自信につながる、部活の時に、サーブ以外のものをやることにもつながる','サーブを飛ばすためにはどうすればいいのか、','サーブを飛ばすための練習方法をつくり、実際にボールの飛ぶ距離が延びるのか検証する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','27','B','','陸上競技で必要な能力を高めたい','全て鍛えられる一番効果的な練習方法は?','一気に鍛えられる練習方法はない、またはまだ解明されていない？','全部じゃなくてもいいから、できるだけ多くの能力を身につけられる練習法を明らかにする。また、それが本当なのか明らかにする。','調べて、実際に実験をしてみて、何もしてない状況と、その練習方法を何日もやったあとにまた記録をはかる。','体育 数学','部活の大会や記録会の幅広い競技でいい成績をのこせるはず。','実際に幅広い能力をもっている人にどのようなことをしているか聞いてみる。','陸上競技に必要な能力を手に入れるためにはどのような練習やトレーニングをすればいいのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','28','B','','K-popが好き！！','k-popが世界で人気なのはなぜだろう','曲だけでなく、見た目でも楽しめるから','k-popが世界で人気な理由を調べる。デビューするには何が必要か、ダンスや歌がうまくなるにはどうしたらいいかを明らかにする。','実際に行動してみて、ダンスうまくなる！！','体育、音楽','自分の夢に近づける、好きなことを深められる','k-popが世界で人気な理由を調べる','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','29','B','','寝てると気づいたら時間がとても経っている。','なぜ寝ている時は，時間が早く進むのか？','意識があまり無くてその分時間が早く進むのかも。','本探求では寝ている時はなぜ時間が早く進むのかと夢について明らかにしたい。','どのような時にどのような夢を見たかを記録し，ネットでも調べてみる。','理科，社会，保健体育','寝ることについて調べると，寝ることの大切さに気付き，健康的に生活できるかも。','インターネットで調べたり，記録する。','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','1','B','','家での勉強に集中出来ない','時間だけ過ぎて勉強が進まない','勉強する環境や集中できる時間があるのかもしれない','本探求では集中できる環境や時間については明らかにする','色々な人にその人の集中できる方法を聞く、調べて試す','理科','短時間で沢山の内容を覚えられる','','集中して効率よく勉強するには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','2','B','','Mrs.GREEN APPLEを愛してる','なんでミセスのライブのチケットはめっちゃ人気なんだろう','ライブの道具がレベチだからかも、？ライブに参加する人もしない人でも楽しめるものがあるからかも','本探求ではライブの道具のレベルとライブ人気さを明らかにする','いままであったライブの中で一番行きたいと思うライブを調査する','音楽、社会、技術、理科','これから人気のライブがあったらそれに似たライブにいけるかも！','どのライブが一番人気なのか みんながすごいと思うライブの技術はどれか','一番技術がすごいライブはどれか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','3','B','','集中力を上げたい','なんで集中し続けれないのか','人間がそもそも集中力が続かない生き物なのかも？','人間が集中力が続かない生き物なのか、続かないなら続く生き物は何か。続くなら、なぜ自分は続かないのか明らかにする。','ネットで人間が集中できる生き物なのか調べる。できるなら自分を振り返る、友達に聞く…など','理科、保体','勉強も部活も集中して取り組めるかも','データを調べる。人に聞く','人間は集中できる？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','4','B','','二塁に送球を届かせたい！！！！！！！！！','なぜ届かないのか','トレーニングや練習が必要かも？','なんで届かないのか、どんなことをするべきか、を確かめる','動画や自分のチームメイト、部活動の上手な友達やプロ選手の動きを参考にしたり真似したりする！','保体','野球のクラブチームや部活動に影響力など与えることが期待できそう。それに加えて盗塁阻止率も上がるし、得点圏への進塁を防げるから。','どういった技術を身につければいいか、どの様なトレーニングや練習方法が必要か等。','二塁送球をノーバンで届かせるには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','5','B','','バレーで連続して安定したパスを飛ばしたい！＋バレーのポジションとかについて','どうやったら安定してるパスができる？','ボールの当たる位置が悪いから⁈＋いまいちまだポジションとかがわかんない、、','バレーの当たってる場所を観察してできるだけ全部をきれいに取れるように ポジションを理解してうごけるようになりたい','うまい人の動きを見たりして真似してみる。','保体、美術？','バレーがうまくなってやっていてもっと楽しくなる！','過去の大会の動画とかを見てどんなパスがいいのかを調べてみる','バレーについて！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','6','B','','アートブロック、なぜ存在するんだろぅ。。','なんで？アートブロックが発生するの？','もしかして、手がつかれる、？脳みそが飽きる、？','なぜかをあきらかにする','ちゃんと原因を調べて自由になる','美術','解決方法も調べてみんなと楽しく絵を描く','一日何回も絵をかいてみる','アートブロックって、なあに？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','7','B','','ソフトテニスが好き、もっと上手くなりたい','なぜフォアやバックを外してしまうのか','打点に当たってないから？','本探求ではラケットの打点をボールに当てるコツを調べる','上手い人のボールとの距離や打つタイミングを見る','保体','速いボールが打てるようになる','上手い人の大会動画などを見る','ソフトテニスが上手くなる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','8','B','','英語を読み書きできるようにする。','なんで英語が読み書きできないんだろう。','昔から英語を言ってないから？','英語を言えるようにする。','家でも学校でも少しずつ英語を言えるようにする。','英語','英語が今よりもしゃべれるようになる。','英語の発音をしてノートに書く','英語が読み書きできるようにする。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','9','B','','絵がうまく描けるようになりたい','なんで練習してるのにうまくならないの？','誰でも絵がうまくなる練習法があるのか？','誰でも絵がうまく描けるようになる練習法を調べる','イラストレーターや漫画家、絵がうまい人の  練習法や書き方などを調べる','美術','絵がうまくなるかもしれない','いろんなデータを調べる。','なぜ絵がうまくならないのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','10','B','','すげーねっむい‼何で寝なきゃいけないんだよぉぉッ!!!!!!!!!!','本当になんでなんだろう...動物も寝なければ敵に襲われずに済むのに...','もしかしたらどうしても寝なければいけない理由がある...!?(案外当たり前)','本探求ではなぜ生物は寝なければいけないのか調べる','そのためにいろいろな過去の実験などをもとに生物が寝なければいけない理由を調べる','保健・理科','睡眠がどれほど大事なものかを知り、睡眠をたくさんするようになる(はず)','いろいろ過去のデータなどを調べる','なぜ生物は寝なければいけないのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','11','B','','肩を強くしたい、球速を上げたい','野球部で球速を上げたかったから','投げ方が違うのかも。筋力がほかの人より劣っているのかも。','肩が強くなる方法を明らかにする','本探求ではどうしたら肩が強くなるのかをインターネットで調べたりコーチに聞いて検証します。','体育','肩が強くなればスタメンになる可能性が上がると思うから','インターネットで調べる。コーチに聞く。','肩を強くし球速を上げるにはどのような練習法があり、どんな工夫をすればよいのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','12','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','13','B','','絵の具で絵を描けるようになりたい','何故絵の具を思ったように扱えないのだろう','何故絵の具じゃなく鉛筆やペンで書くとうまくいくのに筆になった途端思うようにいかにのだろう','絵の具を使って絵を描くことへのイライラと苦手を克服する','動画を見たり先生に聞いたり、根本的に絵の具以外の鉛筆などで描いた絵がうまくならないと行けない','美術','絵が上手くなる可能性が出きて将来の選択肢が増える。','絵がうまい人に聞いて練習方法や過程を知りたい','絵の具を使った絵を極める','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','14','B','','どうやったらコントロールがよくて試合で使ってもらえるようなピッチャーになれるのか','怪我が治ったばかりで試合に出たいがファーストやライトなどの自分がアンケートで書いたピッチャーをやりたいということをやらせてもらえないから','コントロールのいい悪いの違いは意識から変わってくるのかも？','90％まで正確になるまでやりたい','プロの投手はどのようなところにどのようなボールを集めているのかを調べて実践できるまでにしたい','保健体育','試合での登板機会が増える。いい成績を残せる','ネットで調べる','コントロールを100％に近い成功確率にするのとスライダーを極める','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','15','B','','プレゼンテーションが得意','なんであの時にプレゼン発表の時に落ちてしまったのか？','他の人が見た時(生徒)のプレゼンテーションのみんなが見ていた観点が違ったのではないのか？','生徒向けのプレゼンテーションの仕方とは？','大人だけではなく、生徒に響くようなプレゼンの作り方について。','国語・保健(？)','今後誰かにプレゼンをしたり、社会に出たりするときにプレゼンはよく使うから、その観点で役に立つ。もしかしたらそのほかの学校の活動でも役に立つかもしれない','この課題について、まず調べてみる。そこから少しづつ発展させていく・','生徒に響くプレゼンの作り方。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','16','B','','点数や評価を上げたい','なんで勉強をしたのに点数がいまいちなんだろう','勉強の量や仕方、時間で変わるのかな？','本探究では、勉強方法を明らかにする','いろんな勉強方法を試し、効果的なのを見つける','国語、数学、理科、社会','自分に合っている勉強方法が分かるし、それをみんなに広めることができる。','そもそもどういう方法があるのか','さまざまな勉強方法を試してみる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','17','B','','野球でスイングスピードを速くしたい','なんでスイングスピードが遅いのか','もっと食べなければならないのかもしれない','本探究ではどうやったらスイングスピードが速くなるかを明らかにしたい。','食べること以外に早くする方法があるか調べる','保健・体育・数学・理科','スイングスピードが上がって長打が打てる','スイングスピードが上がる方法を調べる','スイングスピードがどうしたら上がるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','18','B','','アニメ進撃の巨人のすべてを知りたい!!','なぜあんなにも話が長いのだ！全部知るのに時間がかかりすぎるだろ！','奥が深いのかもしれない','進撃の巨人の奥底まで深く知り、進撃マスターになりますぇ','・','体育、理科、歴史、地理、','この作品に対しての現実との比較ができる','あらすじ、複線、道具について全て調べる','進撃の巨人のすべてについて','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','19','B','','映画「リリーのすべて」に感動した','なんで男性から女性になったのか','性別を変えることは幸せなのか','男性から女性になったリリーの気持ちを考えたい','実在するリリーさんの生い立ちを調べて映画を見ながら考えを深める','保健体育、道徳、社会、理科','トランスジェンダーやLGBTについての考えが深まる','周りの人に知ってるトランスジェンダーの有名人を教えてもらう','LGBTQについて','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','20','B','','レイアップのシュート率を上げたい！','なぜレイアップのテストの時に3・4本を外してしまったのだろう  相手がいるとなんでレイアップが止まってしまうのだろう','ボールを当てる場所と踏み込む場所が違うのかもしれない  みんなが見ているから緊張しているのかもしれない  ディフェンスにぶつかるのが苦手だからなのかもしれない','本探求ではレイアップのシュート率をアップしたい！  相手がいても、レイアップで突っ切ってシュートしたい！','どこで踏み込んで、どこに当ててシュートするのか、どのようにしたらレイアップで突っ切れるのか  バスケに詳しい人に教えてもらう、インターネットで  調べる','体育','','探求に手伝ってくれる人を探す、レイアップのコツを調べる','レイアップのコツについて','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','21','B','','ジャンプ力がない','なんでジャンプ力がないと思ったのだろう','自分が周りの人と良く比べているから？','本探求では自分のジャンプ力がどのくらいなのかを調べる','ジャンプ力が高い人や、ジャンプの仕方について考える','体育','スポーツで何かしら有利になれそう','自分と似ている探求の人を探す。苦手なことをうまくなる方法があるか調べる.','自分のどこが苦手でどうしたら苦手じゃなくなるか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','22','B','','ゴール下のシュートをほとんど入るようにしたい','いつもなら入る距離なのに試合で、入らないのはなぜなのか？','緊張？敵ができたから？','本探求では、いつもだったら入るゴール下のシュート、なんで試合になると入らなくなるのか？','ゴール下のシュートが上手い先輩に聞くなど、、、','体育','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','23','B','','SNSが好き！最近SNSを通した事件が多い！','なんでSNSを見ていると時間がすぐに過ぎるんだろう？  SNSを使う上で事件が多くなってきているのはなぜだろう？','見ている人を飽きさせない工夫があるのかも  知らない人と話す機会になっているのかも','本探求ではSNSの工夫や歴史、事件についてを明らかにする','・SNSの歴史や工夫、事件について調べる・SNSについての本を読む・SNSについてのアンケートをする','技術・音楽・英語・社会・（国語）','SNSをコントロールできるようになるかも、SNSで事件が起きてる理由がわかるかも','調査方法についていろいろな方法が知りたい・似てようなテーマの人を探してどのようにして進めているのかを調べる','SNSが世界で復旧されてから現在に至るまでどのようなことがあったのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','24','B','','バスケ上手くなりたい','ドリブルは普通だけどシュートは下手何で？','もしかしたらちゃんと集中していない','どうしてシュートが入らないか明らかにする','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','25','B','','東京に高い建物がなぜ多いのか気になる','なんで高いビルや建物をたくさん建てるんだろう？','色んな地域や、国から注目されたいから？','本探究では、東京にはなぜ高い建物が多く建てられているのかを、明らかにする。','高い建物建てようと思ったきっかけについて調べてみる。そのあとに、なぜ東京に高い建物が多く建てられるのかを調べる。','技術','高い建物が多く建てられることについて知ることによって、高い建物の重要性が分かる。','色んなサイトを使って調べてみる。','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','26','B','','この世の国が好き','国旗の秘密','偉い人が作ってる  国の特徴を国旗に入れてる','本探求ではいろんな国旗の特徴や秘密を知る','有名なとこを調べる  共通点がありそうなとこをまとめて調べる（州とか）  本を買う','社会、美術、家庭','その国の有名なものを知れる  国旗の由来を知れる','非現実的なことを現実的に考える','仮想の国旗(国も)を作って、その国旗の特徴から国を紹介する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','27','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','28','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','29','B','','邦楽が好き','聞くタイミングや聞き手によって曲の印象に違いがでるのはなぜか、年齢によって好きな曲は変わるのか','曲の速さ、進行の仕方、声、楽器が関係してる？','本研究ではどんな楽器を使ったどんな曲がどんな時、どんな層に刺さるのかを知る','同年代の人にどんな曲が好きか、どんな時にどんな曲を聞くか聞いてみる','音楽、社会、国語','自分の気分に合わせて曲を選べるかもしれない  おすすめの曲を聞かれたときに的確なのをいえるかもしれない','同年代の人にどんな曲が好きか、どんな時にどんな曲を聞くか聞いてみる','年齢・気分によって刺さる曲は変わるのか。どんな曲を聞くのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','30','B','','抹茶が好き 抹茶の歴史が知りたい','日本ではいつから作られ、なぜ抹茶が人気なのか','すこし苦いけど甘いから人気だった １９９０年','抹茶がいつから人気で何年に作られたのか','抹茶が好きな人に聞く。','社会','人にちゃんとした抹茶の歴史やなぜ人気なのかをつたえられる。自分が知らなかった事も知れる。','抹茶が好きか聞く。','どうして嫌いな人がいるのか。いつ作られたのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','1','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','2','B','','漫画好き','なぜ日本の漫画は素晴らしいといわれているのか','絵柄、表現力などから考えられる','本探求は日本の漫画のどこら辺が魅力的なのか徹底調査します','海外のアニメ、漫画の好きな人たちが好きな作品の特徴を調べる','国語','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','3','B','','go言語を扱ってみたい','go言語の非同列処理net/http','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','4','B','','絵がうまくなりたい','どのような練習方をしたら絵がうまくなるのか','自分にとって絵がうまい人のまねをしながら絵をかいていたら上達するのかも','絵が上手な人はどのような技法を使っているのか 自分の画力を上達させたい','絵がうまい人(ゴッホとか)の絵の特徴を調べる。分析する','美術','絵が上達したら新しい道ができるかも','絵が上手な人はどのような技法を使っているか、どのような練習をしていたのかを調べる。その絵の特徴をつかむ','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','5','B','','バスケでの3pミドルシュートががうまくなりたい','毎日シュートを百本決めたらどのくらいシュートが入るようになるか？','もしかしたらシュートのフォームやボールに回転がかかってなくてはいってないののかもしれない','バスケのシュートを10本中7本くらい決めれるようになりたい','自分の好きなNBA選手のシュートを研究したり自分でも毎日シュートを百本決めてシュートの確率を上げる努力をする','体育・数学・理科・保健・家庭科','試合でシュートをいっぱい決めれるようになって試合でいっぱい出れるようになる','シュートがうまい選手のフォームや体の使い方をまねしたい','どのようなことをしたらシュートの確率が上がるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','6','B','','バレー！のコツをしりたい(うまくなりたい)','オーバーとかスパイクとかアタックとかどうやったら上達するのか','もしかしたらフォームやカマエ、助走が違うかもしれない','本探求ではスパイクやアタックなどのコツを明らかにする','バレー部の先輩やバレー選手の試合などの動画を見てコーチにコツを教えてもらってノートにめもする。コツの動画やタブレットで調べたりする！','体育','バレーがうまくなったら大会とかにも生かせると思う。','どうやって調べるかかんがえる','バレーがどうやったら上達するのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','7','B','','食べることが好き！！！世の中の食べ物はたくさんの味があってすごく美味しい！好きなもの、甘いものなど食べるとすごく幸せな気持ちになる。','なぜ人間は食べることを求めるのだろう。  （おなかがすくのだろう）  なぜ食べ物はあんなに美味しくて、見た目も美味しそうなのだろう。  どんなときにおいしいと感じるのか？  どんなときに○○が食べたい！と感じるのか？  食べることでどんな効果があるのか？','体に必要な食。→不可欠なもの、毎日食べるものがおいしくないと、きれいでないとテンション上がらないし、食べる気失せると思うから？？？？  色が与える印象が食にも影響してるかも？（においも）  食べたいと思わせるためにいろいろな工夫がある？  食べると、幸せな気持ちになる？  たくさん運動して疲れたとき、甘いものを欲する？','本探究では、人間にとっての食事について明らかにする。  ・食事の役割  ・美味しい理由、美味しそうな理由  ・美味しいと感じるとき  ・食べたいと感じるとき  ・食べる→効果、どんな感情が生まれる？   ・どうすればもっと食事を楽しめるか？','・日々の生活での気づきを見つける。  →「私は○○なときにお腹がすく、食べたいと感じる！」、「食事をすると、○○な気持ちになる」、「料理は○○のおかげで美味しくなってる！」などたくさん感じたことをメモしておく！  ・実際に料理を食べる！  →どんな見た目（飾りつけ）なのか、どんな味、においなのか、食べた後に感じることなどメモしておく！  ・アンケートを取る？  →「美味しいものを食べて幸せになったことはありますか？」「人気な料理などにはどんな工夫がされていると思いますか？」「おなかがすくときはどんなときですか？」など','家庭科、保体、理科（？）','食事の大切さ、ありがたさを知り、日々の食事をもっと大切にして楽しめる。一人でご飯を上手に美味しくつくれるようになる。（栄養バランスなど考えながら、見た目、美も意識する）','課題のために、どのような方法で調べているか参考にしたい。  →分析の仕方、情報の収集など。  そしてどのようにこれまでの学びを生かしているのか、掘り下げているのか参考にしたいと思う。','人間にとって食事は感情、心、体、行動にどのように影響されているのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','8','B','','アイスが好き！でも「ラクトアイスは体に悪い」と噂で聞いた。でもスーパーやコンビニに行くとラクトアイスはたくさん売ってるし、私自身も普段からおいしくめちゃくちゃ食べている。','なんで体に悪いと言われているのに、こんなにたくさんの種類が売られていて、みんなに人気なのだろう？そもそもラクトアイスと普通のアイスクリームの違いとは？','ラクトアイスには「体に悪い」というマイナスなイメージがあるだけで、実際には値段が安かったりカロリーが低かったり、メリットがたくさんある？    実際にアイスを買って、カロリーなどの栄養や値段を比べる。また、アンケートも取る。','・本探究では、アイスの４つの分類（アイスクリーム・アイスミルク・ラクトアイス・氷菓）の値段やカロリーなどの違いを数値ではっきりさせる。  →ラクトアイスと他の3種類の違いを伝えるために、他の3種類も調べる。  ・また、何のアイスが好きかとその理由もアンケートを取って、「アイスが人気な理由」も明らかにする。','①コンビニやスーパーで売られている色々な種類のアイスの「種類別」「値段」「カロリー」などを調べ、グラフにまとめる。  ②クラスや学年に「一番好きなアイスの商品名は？その理由は？」「ラクトアイスにどんなイメージを持っている？」などのアンケートを取る。','理科、数学、家庭科','ラクトアイスを「体に悪いもの」と決めつけるのではなく、データとみんなのアンケート結果を通して、それぞれの種類のアイスが持つ「本当の良さ」が見えてくる？と思う。','さっきも書いたように、クラスや学年に「一番好きなアイスの商品名は？その理由は？」「ラクトアイスにどんなイメージを持っている？」などのアンケートを取る。','ラクトアイスが体に悪い理由は？  そもそもラクトアイスとは？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','9','B','','ドラムをやってみたい！','あんなに大きな楽器なのに音量を抑えつつ、かっこよく、リズムを支えられるのはなぜ？ドラムにはどんな役割がある？、どうしたら演奏できるようになる？','ドラムがいないとリズムがくずれる？ドラムがいなくてもバンドは成り立つ？たたく場所によっても、印象が変わる？','本探究ではドラムの役割、ドラムを演奏できるようになるためのコツを明らかにする','ドラムの演奏方法を知る、有名なバンドのドラムではどのような工夫をしているか調査する、ドラムの役割を知る','音楽','ドラムにどんな役割があって、聞く音楽にもリズムが感じられるようになるかも、自分の演奏で笑顔になってくれる人がいるかも','ドラムの役割、演奏できるようになるコツ、工夫のポイントを調べ、まとめたり、ドラムにどんな印象があるか聞く','ドラムを演奏できるようになるには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','10','B','','３ポイントやミドルがもっと入るようになりたい','なぜ全然入んだろうか','もしかしてシュートホームがちがう？','NBA選手とかはなぜそんなに3ポイントがはいったりなんでそんなに確率がよいのか','みんなの確率やNBA選手の確率を調べる。あとみんながどんな工夫をしているのかを調べる','体育、数学,理科','自分の3ポイントやミドルがたくさん入りやすくなる','足の重心を調べる。','3ポイントやミドルがどうやったら入りやすくなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','11','B','','ベースかっこいい!!弾きたい！','そこまで目立つ楽器じゃないのになんでかっこいいんだろう？ベースにはどんな役割があるんだろう、ベースをうまく弾くコツって何？','もしやバンドにおいてベースがいないと成り立たない？弾き方によって魅力が変わる？みんなにベースの魅力を理解してもらうには？','本探究では、ベースのうまく弾くコツとみんなが理解してくれるようにベースの魅力かっこいい理由を明らかにする','ベースの弾き方を学ぶ、世界のバンドなどでベースがどんな役割をしているかベースの必要性とは何か調査する。','','みんながこれから聞く曲にベースがどんな役割があるのか新しい視点で曲が聞けるのかも','ベースの役割ややり方を調べる、ノートにまとめる','ベースの魅力と、ベースをかっこよく引く方法は？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','12','B','','バリトンサックスやってみたい!!!','どうしてかっこいい音が出るんだろう？なんでうまい人とあんまりの人の差が激しいんだろう？そもそもサックスの音の出る仕組みってどうなってるんだろう？','かけた時間の長さや経験の差で差が出るのはわかるけど息の入れ方や口のつけ方で音質が変わる？','本探究では、バリトンサックスの音の出し方、リードのコツについて明らかにする','バリトンサックスの吹き方、コツを調べる。うまい人の癖とあんまりの人の癖を比べる。楽器屋さんに行って、プロのお話を聞いたりしそうさせてもらう。あわよくば買う。','音楽、理科','吹部でチューバを吹くときに音質をまねしてもっとうまくできるようにする','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','13','B','','サッカーが好き!!!','なぜ上手い人は無回転やカーブが打てるのか？','もしかしたら無回転やカーブは筋肉がすごいから？実体験があったから？','本研究では自分が無回転やカーブを蹴れるまで練習して蹴れるかを検証してまた足の筋肉を鍛えたら蹴れるかも検証しサッカーの変化球を明らかにします！','無回転やカーブの解説動画や無回転やカーブを蹴れる人のプレイを見る！','体育 理科 数学','将来の2年生や3年生または高校生？でレギュラーででれる。そして自分に足りないシュート力を磨く！','具体的な例や実体験など！','どうしたら無回転やカーブが蹴れるか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','14','B','','scratchのアニメをはやらせたい','なぜ、あまりscratch日の目を浴びないのか','プログラミングは一部の層にしか見られないからかもしれない','本研究では、なぜ人が集まらないか、どうすれば人が集まるか','出ているscratchアニメなどを調べる','心理学（道徳？）・技術','人がどんなものに興味を持つか、','いろんなサイトのランキングを見て絞り込む。（できれば、アンケートを取りたい）','人を集める方法とは。？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','15','B','','ペンケースがつくりたい！','自分にあうペンケースが無いからつくりたい','コンパクトなのが一番いいのかもしれない','自分にあうペンケースをあきらかにする','いろいろなペンケースを試す','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','16','B','','アニメや小説が好き！','どうしてあんなに感動する話を考えられるのか？また、外国の人に日本のアニメが人気なのもそれが理由なのだろうか','大勢の人たちが協力して作っているからかも？また、日本のアニメには何か引き込まれるのがあるのかもしれない','本探求では、アニメを作っている人たちの工夫を明らかにする','そのためにサイトなどで調べたり、制作過程などがわかる短編映像をたくさん見たりする。そしてそれをまとめどのような工夫があるのかを考える','技術 国語 数学 音楽 美術','作っている人たちの工夫を知り、アニメをもっと楽しく見ることができるはず！！','どんなことをしたら業界の人々がどんな工夫をしているかがわかるのかを知るためにいろんな人に意見を求めたいです！','感動するような作品を作っている人たちはどのような工夫をしているのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','17','B','','アニメやペットが好き','なんでにんげんはかわいいとおもうのだろう','もしかすとかんじょうがうごいているのかもしれない','いまかってる犬がかわいいとおもってぃる','','保健体育、理科、美術、社会','可愛いと思える気持ちがどこかにあると思うからそれを知りたい','','犬なぜ人間はかわいいと思えるのだろうか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','18','B','','原宿派手な人多!!','なんで原宿や渋谷は派手な人がほかの場所より多いんだろう','原宿には新しぃ物が多いから、若い人が集まってどんどん新しいファッションが増えていくのかも!!','どうして派手な人が集まるのか、どういうきっかけで派手なファッションになるのかを明らかにする!!','まずは、原宿の魅力を調べる!!','社会、美術、家庭','町の魅力を伝えられたり、今までに、派手なファッションをしてみたいと思っていた人の力になれるかも!!','調べ方、アンケートやインタビューの仕方を参考にしたり、なぜ派手な人が多いのかだけじゃなく、昔はどんな町だったかとか、人が集まる理由も調べてみたい','原宿や渋谷はなぜ若者の町として有名なのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','19','B','','アニメと漫画とゲームとサッカーが好き','どうしたらうまくなるだろうか','もしかしたら研究や、練習が足りないかも','本研究ではサッカーがうまくなる方法を明らかにする。キックの威力や、正確さ、回転のかけ方などを練習する','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','20','B','','頭の中で ’’こんにちは’’ って言える。','なぜ喋っていないのに、頭の中で声が聞こえるのだろうか。なぜ喋れるの？なぜ考えられるの？','細胞が言葉を記憶しているからかもしれない。','本探究では、どうして喋っていないのに頭の中で声が聞こえるのかと脳の仕組みを明らかにしたい。','体の構造に詳しい人に話を聞き、この探求のヒントになりそうな話を聞き出す。脳の仕組みについて乗っている本を探す。','理科','普段当たり前のように行っている行為が体の中でどうなっているのかが分かり、人間の体がいかによくできているのかが分かる。（）','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','21','B','','バレーボールがうまくなりたい！！！','どうしたらサーブ・アンダー・オーバー・スパイクがうまくなれるのか','もしかしたらバレーボールがうまくなるコツがあるのかも!！！','本研究では、バレーボールがうまくなるためのコツを明らかにする！','コーチや先輩のボールの触り方をじっくりと観察をする‼','保体・体育','ボールの触り方がうまくなり、その触り方を意識して、ボールを触れば今よりもさらにバレーボールがうまくなるはず‼あと試合に出れるようになるかも！？','どうやって調べるのか。','バレーボールがうまくなるためのコツは何だろう。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','22','B','','フィギュアスケートが好き！','どうしたらうまくなるのだろうか？','もしかしたら回転のかけ方にうまくなれる秘訣があるのかも','本研究では、フィギュアスケーターの回転のかけ方を明らかにする','フィギュアスケーターのジャンプを飛ぶ時の回転のかけ方を観察し分析する。','保険・体育・国語','大会で調べた分の成果がでるかもしれない！','フィギュアスケートの主にトリプルの回転をかけるときや足をどこにつくかなどを調べる','フィギュアスケートがうまくなってスケートを色んな人知ってほしい！！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','23','B','','日常組が好き!','なぜあんなに動画が面白いのだろう','日常組やスタッフさんが考える企画が面白いから？','本探求では日常組の過去や配信をやる動機を明かす','みんなに何の日常組の動画が好きか調査する','国語','将来の夢やもし仕事で挫折して別の道に行こうとしたら候補が増えるから','みんなもどういう文章構成にしているのか参考する','どういうチャンネルが流行るのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','24','B','','科学（理科）が大好き！！','なんで家の中で自然現象がおこらないのか？','もしかしたら、家の中でも雨を降らせたり、竜巻をおこしたりすることができて、家の中でも農業ができるようになるのかもしれない。砂漠にも雨を降らせることができるようになるかもしれない！！','本研究では、家の中で自然現象が起こるかどうか考え実験し、そのことがどのように良い影響が与えるのか明らかにする。','1.塾のテキストをもとに、雨がどの条件で振るのかなどを調べる  2.その結果をもとに、考察し、仮説を立て実験する  3.その結果がどのような良い影響を与えるか考える','理科','水不足がなくなって、アフリカの方々など水を必要としているがないまたは岡名がない人や、減少傾向にある農家さんの負担を減らすことができるかもしれない。','理科（科学）','水不足で困ってしまっている人や、お金がなくて、お風呂に入ったりできない人、蒸し暑くて熱中症になりかけていたりする時。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','25','B','','サッカーが好き！','どうしたら左足をうまくけれるのか','もしかしたら右足でボールをけりすぎたのかも','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','26','B','','バスケットボールが好き!!!!!','バスケットボールについてもっと知りたい','もしかしたら、試合を見ることが足りないのかも','本探究では、バスケットボールの知識を得るために試合を見て、知識を得る','試合を見る、シュートフォームなどを知る','体育','試合を見ることが楽しくなる、上手になる(かも)','バスケットボールが上手な人に聞いてみる','バスケットボールの知識を得てみんなに伝える!!!!!','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','27','B','','バレーボールがすき！','どうしたらバレーボールがうまくなるのか','もしかしたら、アンダーとオバーは壁打ちをしたらうまくなるかも、サーブは近くから打って、コートに入ったら遠くから投げたらはいるようになるかも、あとは打つときの形をつくる。スパイクはジャンプして一番高くでキャッチする練習をしたらうまくなれるかも。','マイ探求では、アンダー、オバー、サーブとスパイクをうまくなれるようになって上手にできるやり方をしる。','本やバレーボールがうまい人（コーチ、先輩）などに聞いたり調べたりする。','体育','今よりアンダー、オバー、スパイク、サーブなどがうまくなって試合に出れるようになるかも。','アンダーなどのやり方を調べる。','バレーボールをうまくなるためには。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','28','B','','バレーボールが上手くなりたい！','どうしたらパス・トス・サーブ・スパイクがうまくなるのか','もしかしたら、バレーボールの上手くなるコツがもっとあるかも!','本探究では、パス・トス・サーブ・スパイクの上手くなるコツを明らかにする!!','コーチや先輩のバレーボールをみたり、上手くなる方法を聞く‼','体育・保険','バレーボールのコツをつかみ、たくさん練習すれば１年生の試合にでれるかも⁉','パス・トス・サーブ・スパイクのコツを調べる！','バレーボールが上手くなる方法を知る!','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','D','29','B','','仮想通貨作る','みんながどう変化（喧嘩、貧富の差）するのかきになるから','もしかしたら、私が世界の頂点になれるかも！','貧富の差、人の欲望をあきらかにする','最初にお金をばらまく→みんなかほしいほしい言う','','','','','');
