INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','21','B','','シリコンバレーのような場所はどのような歴史を経て出来上がったのか。','どのような条件がそろえば原宿がシリコンバレーのような場所になるか。','シリコンバレーにある「失敗を恐れない文化」という失敗を「貴重な経験」とする考え方が少し原宿にもつながるかも。','どのような条件がそろえばシリコンバレーのような場所が完成するのか。','シリコンバレーがどのような場所なのか調べ、原宿と共通点や異なる点を探す。','社会','シリコンバレーについての理解を深めることができる。','調べる','どのような条件がそろえば、原宿がシリコンバレーのような場所になるか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','22','B','','海外の赤ちゃん見てると癒される','海外の赤ちゃんがかわいいと思う理由','海外だけでなく、赤ちゃん自身に癒してくれる力があるのかも','海外の赤ちゃんに人を癒す力があるのか','赤ちゃんを可愛いと思う人間の心理について調べる','理科、家庭科','他の人にも海外の赤ちゃんの魅力をおしえてあげる事が出来る','海外の赤ちゃんと日本の赤ちゃんの違いを比較する','なぜ海外の赤ちゃんを見ると癒されるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','23','B','','一年生の頃に部活の目標が２つあって家族や部活仲間に言ったら目標が叶った','なんでみんなに言ってたら叶ったのか？','もしかして皆に言うことで自分で気づかないうちに達成しないとと思っているのかもしれない','本探究では','','','','','','');
