INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','39','B','','サブカルチャーがすき','どうしてサブカルの良さに気づけない人が多いのか','わかる人にしか刺さらないし普通じゃない文化だから','本探求ではサブカルの良さや魅力を明らかにする','色んな魅力的なサブカルのアーティスト、作家、漫画家を調べる','社会、美術、音楽','サブカルを好きになる人が増えそう','インターネットで調べる。','サブカルチャーの魅力','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','1','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','2','B','','思考実験とかの考えること','思考実験はどんな種類があるか、あるとしたらどんなものなのか','現実では行うことが難しいから','物理学と哲学の思考実験で何が違うのか','思考実験一覧表を作る','道徳 国語 理科','考えることの大切さを知れる','アンケートを取る','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','3','B','','涙がしょっぱい気がした','涙しょっぱい','涙しょっぱいのなんで','涙がしょっぱい理由','みんなに聞く','理科','涙を流すときにしょっぱい理由がわかる','アンケートとる','涙がしょっぱい理由','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','4','B','','柴犬が好き','柴犬以外の日本犬は何種類いるのか？','日本犬は柴犬を含めて６種類いる','その６しゅるいの日本犬の特徴と歴史と絶滅した犬種の歴史明らかにする','日本犬保護協会のホームページで調べる','社会','その6種類の日本犬と関連している地域の歴史がわかる また、ハチ公についても知れる','秋田犬の特徴をしらべる','日本犬の特徴とれきし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','5','B','','190以上もの国がある？','なぜ190か国以上に分かれたのか？','もしかしたら文化の違いが原因なのではないのか？','190か国の文化の違い','いくつかのまとまりで調べる。','社会、外国語','190か国のなかでの仲間と違い','文化のまとまりを調べる。','なぜ190以上の国に別れそれぞれの文化があるのだろうか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','6','B','','注射が嫌い','なぜ注射には何歳までに打たないといけないなどと年齢制限があるのか','子供のうちに打っておかないと効果が出ないのではないか','年齢制限のある注射、なぜ年齢制限がついているのか、制限を守らなかった場合どうなるのか','病院のサイトや注射の専門のサイトを見て調べる','国語・社会','ワクチンなどに年齢制限がついている','理由を調べる','注射に年齢制限がついている理由','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','7','B','','漫画が好き','日本の漫画はなぜ海外にも人気があるのか？','日本の漫画はいつから海外に人気が出たのか','日本の漫画が世界で人気になった理由を知る','漫画の歴史や人気の理由をインターネットで調べ、海外との違いもまとめる','社会、国語、美術','日本の漫画文化について理解が深まり、世界で人気がある理由を説明できるようになる','日本の漫画の歴史について調べる','なぜ日本の漫画は世界で人気なのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','8','B','','イスラエルとパレスチナがもめてる','なぜもめているか？ユダヤ人の迫害の歴史があった','←ユダヤ人の受けた迫害の歴史が関係しているのでは','ユダヤ教やユダヤ民族の原点、聖地に関する歴史、ユダヤ人の受けた迫害の歴史、現在のパレスチナ問題とイスラエルという国','ユダヤ教の抱える信条や他教徒との違いや、ユダヤ民族の住む地域の移り変わりをインターネットや図書館で調べる。ホロコーストの実態などは過去にアウシュヴィッツに行ったときに撮ったものを参考に、ホロコースト記念館などの情報をもとに考える。','社会','','','ユダヤ人はなぜ迫害され、迫害するのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','9','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','10','B','','授業や勉強に集中できるようになりたい','どうしてすぐに集中が切れてしまうのか？','その時の気分や睡眠などが関係しているのかもしれない  好きなことは集中できるから好き嫌いも関係している？','どうして集中が切れるのかと集中力を高めるにはどうしたらいいか、集中できる人とできないひとの違い','集中できている人やできなくて困ってる人に聞いてみる  集中力に関係してること、集中力を高める方法を調べる','体育','前よりも授業や勉強に集中できるようになる  集中力が高まる','','集中力を高めるには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','11','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','12','B','','中・長距離（８００ｍ・１５００ｍ）で速くなりたい','同じ練習をしている友達のほうが１０秒近くも速い','速い人に聞いてみる。自分でメニューを作り実践','はじめとどれくらい早くなったのか','特異な友達に聞く。それを実践','体育','はじめよりも簡単に楽にはやく走れるようになる','今の疑問を深める','長距離が早くなるには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','13','B','','あの桜変わったピンク色だな～','なんで葉っぱは緑なのに花は色がついてるのかな？','その場所の土の成分かな？','植物でも葉っぱと花の色が違うのには、何が関係しているか','理科の先生に聞いたり、本やネットで調べてみたりできれば、その場詩に生えているそれぞれの花や緑の葉っぱが生えている木のそれぞれの土の成分を調べてみたいです。','理科','理科が得意になり。花の種類が前より知ることができてこんな植物にはこのような土が必要などということがわかる。','葉っぱと花の色が違うのがなぜかを調べる','なぜ植物でも「花」には色があるのだろう？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','14','B','','スマホ依存症の改善の仕方','なんで勉強は依存になる人が少ないのにスマホは依存になるのか知りたくなったから','中毒性があるから。ブルーライト？が関係している','スマホ依存症はなぜなるのか','とりあえず、三木先生。三木先生が分からなかったらネットで調べる','理科','少しでも勉強に集中できるようにしたい','原因と改善点を調べる。','スマホ依存になる原因と改善の仕方','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','15','B','','退屈な時間は長く感じるのに、楽しい時間は短く感じる','同じ時間のはずなのになんで短く感じたり長く感じたりするのか','苦手な教科を勉強していても集中していれば短く感じるから集中しているかどうかで感じ方は変わるのではないか','本探求では時間が長く感じるときや短く感じるとき、短く感じさせる方法や長く感じさせる方法を明らかにする','楽しい時、退屈な時、運動しているときに感覚で10分計って誤差を記録する。タブレットを使って調べ学習をする。','理科、体育、数学、家庭科','つまらないときに早く時間を感じれるようになるかも','楽しい時、退屈な時、運動しているときの脳には何もしていないときとどんな変化があるのか調べる','時間を早く感じたり長く感じるためには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','16','B','','サッカーのシュートはどうやったらもっと飛ぶか','','今全然ボールが飛ばないからどうやったら飛ぶのかいろいろなことをしたい','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','17','B','','音楽が好き','音楽はなぜこんなに聞きたくなるのか','昔はそんなことなく進化でこうなった？','my探求では「音楽の進化の軌跡」を調べたい','音楽ができたとき、そこからの楽器や音楽、聞き手がどのように変化して今に辿り着いたのか','社会＋音楽','音楽の魅力をより深めることができる','Google等で昔の「音楽の始め」について調べる','音楽の進化の軌跡','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','18','B','','第一空挺団は高所から五点着地してる。','五点着地ってできるの？むずいの？','もしかして衝撃分散？','五点着地をできるようになる方法を明らかにする','五点着地、第一空挺団の訓練を調べて実践する','体育、CT','高いところから落ちても生きて帰れそう。','訓練方法を調べる','五点着地をできるようになるには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','19','B','','小学校の先生になりたい！海外に行きたい！','学校が楽しいから？世界のことをもっと知りたい！','もしかして日本と外国って教育の仕方が違うのでは？','本探求では日本と外国の教育の違いやその課題を明らかにする','日本と外国の教育の仕方の違いや今起こっている問題について調べる','全教科','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','20','B','','友達コミュ力高いなー','なんですぐ仲良くなれるのかな？','初対面の人とすぐに仲良くなれる人って、話すのがうまいのかも？笑いを引き起こすのがうまいのかも？','コミュ力上げる、初対面の人ともすぐに仲良くなれるためには何が大事かを明らかにする','コミュ力が高い人の話し方や話すときの表情に着目したたり、気をつけていることを聞いてみる。','国語','転校生とかそういう初対面の人とも仲良くなれる','人と話すときに気を付けていることなどを友達に聞いたり、調べたりする','人見知りを直すためには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','21','B','','リフティングは楽しい','どうしたらリフティングがうまくなるだろう','コツとかはどうでもよくて、何回もやることが大事なのではないか','本探求では、何をしたらリフティングがうまくなるのかを明らかにする。','1つ目：まず素の状態でリフティングの回数を測って、その後にネットなどでコツ等を調べ、それをもとにもう一回やってみる。そしてコツを調べる前と後の回数を比較する。２つ目：まず素の状態でリフティングの回数を測る。そして３０分間リフティングをやり続けてそのあとにもう一回回数を測る。そして３０分前と後での回数を比較する。','体育','リフティングをやり続けることで、ボールタッチの質が上がり、チームでも良いプレーができるようになるのではないか','練習方法を今考えている二つだけじゃなくてほかにも何か方法があるのか知りたい','リフティングはどうやったらうまくなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','23','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','24','B','','野球が好きだがやりたくない','どうしたらモチベが上がるか','楽しい事をすればモチベが上がる？','モチベはどうすれば上がるのか','嫌なことをする前に楽しい事をする','','嫌なことでもモチベーションが上がる','どんな時にモチベが上がるか調べる','どうしたらモチベが上がるか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','25','B','','食べ物','何で嫌いな食べ物があるのか。苦手なのか。','食べ物のトラウマ？偏見？味が苦手。','どうやったら好き嫌いがなくなるか。食べれるようになるか。','1つ目は、嫌いな食べ物だと思わないで好きな食べ物だと思って食ってみる。  2つ目は、なぜ嫌いになるかを調べる。  3つ目は、味を変える。  4つ目は、隠す。  5つ目は、見た目をよくする。','保体、家庭科、CT','食べれる食べ物が増える説。  いろいろな食べ物好きになったら、給食とかご飯の時間が楽しくなる説。','調べる。','どうやったら好き嫌いがなくなるか、減るのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','26','B','','ユーチューブショーとのコメ覧終わってる','なんでコメ欄をあらす？','もしかして僕が知らないユーチューブの伝統？','本探求では、どうしてユーチューブショートのコメ欄が基本あれるのかを明らかにする','','ユーチューブのショート動画','なんで戦争が起きるのかがわかるかもしれない','最初のまま','ゲームのランキング動画でコメント欄を荒らさないためにはどうすればいいのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','29','B','','和服・制服がかわいい','今は昔の服を着ている人が少ない','もしかして動きにくいから？','本探求では昔の和服・制服の人気を調べて服がどんどん変わった理由について詳しく調べる','ネット調べたり、アンケートをする。','社会','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','30','B','','好き嫌いはなんであるんだろう','ダサいとダサくないって人それぞれ違うんじゃ','感性は人それぞれ違うからみんなの基準も違うかもしれない','人それぞれ感性が違かったら対立が起きてしまうのに','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','34','B','','やりたいこと、やらなければならないことが多すぎて時間がない','なんで時間が足りなくなるんだろう','もしや無駄な時間があるかもしれない','現代における無駄な時間を明らかにする','みんなが無駄だと思っている時間、無駄だったかもしれないと後悔した時間はないか、またそれは何の時間なのか調べる','社会','無駄な時間の傾向が分かれば、どの時間を削ればいいか明確に分かりやすくなるかも。','1回アンケートを取る','現代人は無駄な時間が多いのか、また無駄な時間を削減するには','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','35','B','','ディズニー楽しい','ディズニーはなぜあんなにもワクワクするの','ディズニーに隠された工夫があるのかもしれない','ディズニーパーク内で隠されている工夫を歴史と関連付けて調べてディズニーに来た人が楽しめる理由を明らかにしたい','ネットで工夫されているところを調べて、友達にどんなときにワクワクするか調査する','道徳？社会','愛され続けているディズニーに隠されている理由を知れば、将来自分で何かを開いたときの知恵の材料になるかもしれない','ワクワクするときがどんなときか考える','ディズニーに隠された工夫','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','36','B','','エレキギターをうまく弾けるようになりたい','ギターがすぐ上達する人との違いではなにがあるんだろう','練習内容や時間の違いがあるのかもしれない','ギターのどんな練習が一番上達するのか調べる','練習内容を調べ、それを練習する','音楽','ギターがうまく扱えるようになる。正しい練習方法がわかる','ギターの技能について詳しく調べる','ギターが早く上達しやすい練習方法とは','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','37','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','38','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','1','B','','サッカーが好き','どりぶるを強くしたい','ドリブルをしたら強くなるかも','ドリブルを練習してサッカー経験者に勝つ','ドリブルが強くなる練習メニューをやる','保体、','ドリブルが強くなる','練習相手をしてもらう','ドリブルを強くする','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','2','B','','部活動で都大会が決まった。その時、現場では涙は出なかったが、家に帰ったら涙が出た。','なぜうれしい時にも涙が出たのだろうか。','もしかして、中にこもった感情が爆発して涙が出るのではないか。','本探求では人がなぜ喜んだ時に涙が出るのか・大笑いした時に涙が出るのは関係するのか などを調べる','本やインターネットなどで涙が出る理由を調べる・アンケートで一番涙が出るときはいつか集計する','理科(全教科？)','人の感情の理解ができるようになるかも・感情のコントロールができるかも','他者からの意見を取り入れるためにアンケートをとる','なぜ人にも涙が出るのか。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','3','B','','アイスが食べたいです','なんでアイスって美味しいんだろう','アイスが冷たいから美味しく感じるのかも','アイスの美味しさの秘密','ネットで調べる','家庭科','アイスのことをもっと好きになれる','調べる','アイスの美味しさの根源とは','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','4','B','','','なぜ同じ出来事でも、国籍によって感じ方や感情に違いが出るのか','感情の差は事実ではなく解釈の仕方で決まるのでは？','本探求でははじめに感情とは何なのか簡単に調べる。','本、インターネット、アンケートなど','国語？','','','人々の感じ方の違いの理由','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','5','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','6','B','','体力テストで高得点がとりたい','なんで俺より足が速い人がいるの','生まれた時の才能や、体つきだけではなく努力で高得点を取っている人がいるかも','種目別で実験し、１種目で高得点の出し方をたたき出す。','教室で調べてそのやり方で高得点を目指せるか実践してみる。確かめてみる。','体育科、理科,','生活に最低限必要な身体能力が身につく。','全員が生活に必要な身体能力を手に入れることができる。','体力テストで高得点を取るには？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','7','B','','骨折','こっうせつかが多い','骨が弱いから','本探求では自分が骨折しやすい原因と。  どうすれば骨折とか怪我減るのかを明らかにする','タブレットや本で調べて、実践してみる','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','8','B','','地元の場所で最も美味しいカツオを探したい！','今まで分からなかったカツオの発見があるかも！','地元で最も美味しいカツオの美味しい店はどこにある？','東京にいるからわからないけど、環境の違いで、まだ発見できていない種類のカツオがあるかも！','地元に限らず、どのような場所でどのような種類のカツオがあるか探りたい！','社会','地理の授業に繋がる。日本各地の名産品をよく知れる。','インターネットで調べて、詳しくは街中アンケートをする。','日本各地でどのようなカツオの種類があるか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','9','B','','音楽がすき','人気な音楽は何が大切？','コード進行が関係している？','本研究では人気の音楽の共通点を明らかにする。','アンケート','音楽、数学','曲の構成が分かる','アンケート','人気の音楽の共通点とは','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','10','B','','本、漫画、メンタル','なぜ伏線がある本はおもしろいのか？','共通点がある？頭の中で何かが起きる？','どのようなことが関係していて、そのことがほかのことに使われていないか調べる。','アンケート','国語','国語力がつく','アンケート作る。','伏線は人間にどんな影響を与えるのか？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','11','B','','勉強ができるようになる効率的な脳の使い方','どのような使い方をしたらよくなるのか','脳の部位と役割について研究する。','数学の視点とる 人気の勉強法をとる→それは脳科学的にほんとにそれがいいのか調べる','アンケート','理科','またひとつ新しい知識を得られる','アンケートとる','勉強ができるようになる効率的な脳の使い方','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','12','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','13','B','','社会科が好き','なぜヨーロッパはあんなに発展しているのか','気候がいい感じだから？','ヨーロッパの歴史やその土地の特徴、周辺はどうなのかなどを調べる。そして将来のヨーロッパがどう発展するのか考える。','インターネットや本などでしらべて、最後に考える。','社会、','ヨーロッパのことについていろいろと知ることができる、社会科の授業に役立つ。','まずヨーロッパの地域の特徴を調べる。','ヨーロッパはなぜあんなに発展しているのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','14','B','','','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','15','B','','バレーボールのレシーブがうまくなりたい','ハイキューを見たから','もしかして、ハイキューの技ができるのかもしれない','西谷さんくらいレシーブがうまくなりたい','レシーブのやり方を調査する','体育','ハイキューの西谷さんのレシーブの方法がわかる','レシーブを1000回したらどうなるのか','レシーブを1000回したら腕はどうなるのか','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','16','B','','サッカーどんな練習をしたらシュートがうまくなるのか','試合でゴールを決めたいから','試合でゴールをきめれるかも','スーパーゴールを決めれるかも','充てる場所を調査する','体育','','','/','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','17','B','','スリーポイント決めたい','どうやったらスリーが入るようになるのか','フォームを固めると狙いやすいのでは？','スリーポイントを決めるための練習法は何がよいのか','タブレットやインターネットで調べてやってみる。','体育','とにかく実践してデータをたくさんとる','有名な練習法を調べてみる。','スリーポイントを決めるための練習法とは？','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','18','B','','一般的な椅子が4本足な理由','美術館とかでは足が4本以上のを見たりするのにレストランとかでは見ないから','ガタついて普通に座れないから','4本が一番いい理由','タブレットで調べまくる','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','19','B','','走るの好き','足早い人はなぜ足が速いのか','走り方に工夫がされている？','早い人の共通する走り方の工夫を調べて体に定着させ、記録の向上につなげる','仲のいい足が速い人に聞いたりトップスプリンターの走り方などを分析してそれを意識しながら走る。','体育','','','','');
