INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','6','C','','流行語の使い方','流行語の使い方','流行語の正しい使い方を調べる','','ネットか有識者に聞く','特にない','CT 国語 社会 道徳','社会：２A教室','パワポかキャンバにまとめる','そもそも、流行語が生まれる理由について深堀してみるとよいのではないでしょうか。なぜその語が用いられ、定着していくのか。人間の営みから解釈してみても良いと思いました（新田）');
