INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','9','C','','スポーツをするときに体を痛めにくい使い方を調べる','体のつくりを調べる','体のつくりを調べる','運動する前に何をしたほうが良いのかどのように動かせばよいのか','ネットや本で調べる','特になし','理科','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','10','C','','日本の漫画が外国にも人気な理由は？','本探求では海外で人気な日本の漫画のジャンルを調べて、その漫画はどうやって運ばれているのかを明らかにする。日本と外国の人気な漫画のジャンルを調べる','Google先生。本屋さんに行く','外国で人気な日本の漫画のジャンル、流行り方、運ばれ方','Google先生、本屋さんに行く、アンケートを取る','アンケート、スマホ','社会','社会：２A教室','なし','日本の漫画と、海外での漫画・アニメーションの構造の違いについて検討してみてはいかがでしょうか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','11','C','','学校のチャイムの音の理由と統一されてる理由','本探求では、チャイムの音の理由と、統一されている理由を明らかにする。','Googleなどのインターネットで調べる','地方のチャイムなど県ごとに調べて比較、世界のチャイムも','Googleで調べる。','特になし','社会、国語、英語','社会：２A教室','タブレットで調べてPowerPointにまとめる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','12','C','','謎解きの点数をあげる','謎解きができる人の特徴を探る','実際にできる人に聞く。インターネットで調べる。','謎解き力とはについて自分で溶きながら考える。','ネットで情報収集をする。','','全教科 特に社会','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','13','C','','どうやったら１on１で勝てるようになるのか','どうやったら１on１で勝てるようになるのか','インターネットで調べて、実践してみる','','','','保体','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','14','C','','ペーパーレス化が進む世の中のメリットデメリット。','本研究ではペーパーレス化のメリットについて考える。','ペーパーレス化のメリットデメリットを表にまとめる','メリットデメリットを考える。','キャッシュレス決済するところを想像したり、紙の製造過程を検索して、そこでのメリットデメリットを考える。','パソコンを使う','社会','社会：２A教室','','ペーパーレスのメリットデメリットは検索すればすぐ出てくると思います。もう一歩探究するのであれば、あえて紙媒体を好む人が、なぜ好んでいるのか、どのような効果を感じているのか考えてみるとよいのではないでしょうか。例えば、数学教師が好んでチョークを使う、つまりICT化しないのは、チョークのカッカッという音が演算能力を向上させるという先行研究があったりします（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','15','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','16','C','','動物に好かれるには','本探求ではどうすれば動物に好かれるのかを明らかにする。','どのような人が動物に好かれるのかを調べる。','動物目線で考える。動物についてのアンケートをとる。動物の行動を監察する。','ネットで調べる。会ってみる。アンケート？','','','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','17','C','','','','','ダンスをうまく見せられようになるにはどんなことをしたらいいのかを知りたい','ダンスをダンサーやアイドルと比べてみてどううまく見せているかを見る','スマホを使いたいダンスを見るためには必要','体育','保体①：体上','','踊りのうまさというのは、どのような人間の見え方・認識・認知によって生まれているのか考えてみても良いかもしれません。美術的な見方だと、いくつかの彫刻や絵画を見ると、人間が好む人間の画角などが見えてくるかもしれません（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','18','C','','レシピどうりに料理を作らないニンゲンの思考を読み取る','本探究ではレシピどうりに料理を作らないニンゲンの思考を明らかにする','料理のレシピどうりに作らない人にアンケートを取る','まずはレシピを見てみる','レシピ道理に料理を作らない人の生態を調べる','レシピの本','視聴覚','その他：視聴覚室','とくにない','一流シェフでも、レシピ通りではなく即興的に食材を加えたり、温度・食材の質・お客様などに合わせてレシピを柔軟に崩します。こういう行為がどのような意味を持つのか、検討するのも面白いかもしれません。そのために、服部栄養専門の方に調査をしてみるとかどうですか？（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','19','C','','森の空気はなぜ癒されるのか、また体にどのような影響があるのか','本研究では森の空気はなぜ癒されるのか、そしてその空気は体にどのように影響を与えるのかを明らかにする。','癒される空気の特徴をインターネットで調べる。  実際に森へ行って、自分の体にどんな変化があるかを調べる。','癒される空気についてもっとよく知る。  いろんな癒される空気を知りたい。  そもそも癒されるとは','「癒される」「五感」についてちゃんと理解する。  森へいって、五感が刺激されるのとされないのとで比べてみる。  →目隠しする、耳栓する、家の中から眺める、鼻をつまむ、全部やる','','理科','理科：第１理科室','理科的に使うマイナスイオン→水溶液の中でしか存在できない  今使っているマイナスイオン（健康にいい）とは少しニュアンスが違う','癒しを感じる音・匂い・空気の濃度などを調べても良いかもしれません。実地調査が難しければ、ヒーリングミュージックなども良いかもしれません（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','20','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','21','C','','原宿で挑戦しやすい環境を作るにはどうすればよいか。','本探求では、シリコンバレーが発展した要因を分析して、原宿で新しい挑戦が生まれやすい環境を作るために必要な条件を調べる。','シリコンバレーと原宿を比較・分析し、挑戦しやすい環境に必要な条件を見つける。','シリコンバレーが発展した要因を調べて、原宿に取り入れられる要素を見つける。','シリコンバレーが発展した要因を調べて、その内容を原宿の現状と比較することで、原宿の強みを生かした挑戦しやすい環境づくりの具体的な方法を考える。','なし','社会','社会：２A教室','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','22','C','','なぜ海外の赤ちゃんをみるといやされるのか','赤ちゃんを見ると癒される理由を明らかにする','赤ちゃんの見た目や声が関係しているかを調べる','海外の赤ちゃん特有の魅力について','ネットで調べたり、実際に知り合いの海外の人の赤ちゃんと遊んで感じたことを元に調べる','','理科、家庭科','その他：視聴覚室','ない','');
