INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','25','C','','ミュージカルを通して考える、人間の音楽・芸能に対する思考','本探究では、ミュージカルの魅力についての秘密を明らかにする。','ミュージカルなどの古くからある音楽と最新の音楽とのかかわりを調べる','かかわりを調べるにあたって、どんな方向から調べるのか明確にする。','','','音楽 社会','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','26','C','','PEANUTSが世界中で愛された理由','本探求では、PEANUTSが好きな人にどんなところが好きなのか、世界ではどんな人が翻訳しているのかを明らかにする。','PEANUTSを書いた人や、世界中の翻訳した人についてまとめる。','PEANUTSを書いた人について調べる。','伝記を読む。インターネットで情報収集する。','','社会、美術','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','27','C','','なぜモンシロチョウは四原色が見えるのか','本探究ではモンシロチョウがなぜ四現象が見えているのか、理由とどう見えているのかも明らかにする。','まずは調べ作業をする。','','','','理科','理科：第１理科室','','');
