INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','33','C','','ディズニーが有名なのはなぜか','ディズニーが好きな人で有名な人はいるのか','ディズニーが好きな人で有名な人はいるのか調べてみる','','','','社会、美術','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','34','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','35','C','','歌は私たちの成長にどのようにかかわっているのか','歌がどのように人の社会に関わっているのか、また、私たちの成長にどうつながっているのかを明らかにする','・歌う曲についてアンケートを取る  ・自身の体験から歌について考える  ・歌が与える精神への影響を調べる  ・歌詞についての分析を行う','何を調べたいかを明確にする。  ・幼少期と現在好きな曲の調査を行う  ・どの歌詞が好きか・なぜ好きか  ・歌の歴史から、なぜ「歌」ができたのかを調査する','←上2つについてアンケート調査を行う。  歌の歴史を調べる','アンケートをFormで集めたい。ラボの先生に許可をもらっておく。','国語、社会、保健、音楽、道徳','音楽：音楽室','Form作成、許可をもらう  まだ目標が曖昧過ぎる。  My探究用ノートを持ってくる！！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','36','C','','0','この探求では中二病患者の理想や考えていること、興味を持っていることを考える','中二病の友達に聞く、中二病のアニメキャラを調べてそれぞれの特徴を調べてみる、','','','','理科、保体','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','37','C','','サッカーや野球を知らないのににわかが興奮するのはなぜ、で終わったら興味が薄れるのはなぜか、日本が出ているから興奮すると思う','本探求では日本が出ているから興奮するのかを明らかにする。','聞いたり、タブレットで調べる','','','アンケートをしたり実際にやる','体育','保体②：校庭','サッカーや野球を触れてみる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','38','C','','0','人が怒る心理','人が怒るときに使う脳について調べてみる','','','','0','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','1','C','','小中高生がゲームするメリットとデメリット','','人がゲームするときに使うところとかどんな悪影響があるのか','目的は、ゲームするとどんな影響を受けるのかまた周りの人にはどんな迷惑がかかるのか。','実際にゲームで負けて怒ってる人と怒ってない人に聞く、またGoogleで調べたりする。','特になし。','その他','その他：視聴覚室','特になし','例えば、ゲームにも種類があると思うので、どういう特徴を持っているか分類するところから始めてもよいのではないでしょうか。そのうえで、メリットがあるゲームがあるとすればどのようなものかプレゼンしてみるとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','2','C','','運動ができる人は勉強が苦手なイメージがあるが実際どうなのか','本探求では運動ができる人と苦手な人とのちがいを調べる。','聞いて回って自分でもなりきってみる','目指すは、そのイメージは実際どうなのか、またその規則性など','聴きまわったり、実際に自分でもやってみる。','特になし。 使うならばバスケットボールや、サッカーボール、','保健体育','保体①：体上','まずは体育館でできるやつをやる','それでいうと、部活が強い頭の良い大学とかはどのような位置づけになるんでしょうか。前提から疑ってみた方がよさそうです（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','3','C','','曲に使われている楽器の役割と必要性について','本探求では、曲に使われている楽器ごとの役割について、またその楽器が本当に必要なのか明らかにする','全部の楽器をカバーしてみたり、楽器の音を一つ消してみる(例えばギターの音だけ消してみる)とどんな変化があるか調べたりしてみる','本探求では、曲に使われている楽器ごとの役割について、またその楽器が本当に必要なのか探求する','まずカバーする曲を決め、楽器をカバーする中でどんな役割があるのか考えたり、全部の楽器の音を重ねてみたときの気づきや逆にその楽器の音をなくしてみたらどうなるのか調べてみたりする','ギター、ベースの持ち込み(毎回ではない)、楽譜を見る用・音源を聞く用のスマホ 実際にギター、ベース、ドラムの音は家で取るのでその機材は持っていきません','音楽','音楽：音楽室','申請しないといけないものの確認','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','4','C','','ゴール決めたら快感を得るのか、またその仕方によって快感具合は変わるのか','まずゴールをするとなぜ快感が生まれるのか。またゴールの仕方によって誰が一番爽快感を得るのか理由も含めて明らかにする','原因は調べる。シュートを打つ人と、見る人を用意して採点する。アンケートで見る側の意見を多く得て、統計する。','快感の原因を知るこ、どんなゴールが一番快感なのかプレーしてる側とみてる側の両方で明らかにする。','ネットで調べる。シュートを打つ人と、見る人でどれくらいの快感か採点してもらう。また見る人の人数を増やせばデータがまとめやすいので、できれば動画をとってアンケートをとる。その結果をグラフなどでまとめる。','快感の原因を知ったら、サッカーボール、トレシュー','保健体育 数学','その他：視聴覚室','快感の原因を知る','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','5','C','','超能力を身に着ける','まずは超能力について調べる。','','','','','理科、国語','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','6','C','','超能力を身に着ける','生き物の主食・腸の形・行動などの特性を知り、（面白い形の糞）三角形などの糞を作ることは可能なのかを探求！！','もしかして、修行を重ねたり練習を積み重ねることで超能力は使えるかもしれない！','直感を研ぎ澄ます・心理学を学ぶ','鍛錬する','タブレットで調べ練習する','国語・理科','国語：図書閲覧室','糞の形が特殊な生き物について調べる・学ぶ・知る','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','7','C','','人間が嘘をつく理由','探究を通して人間が嘘をつく心理を調べる','インターネットや本などで調べる','嘘をついているかついていないかの判断','インターネットで調べて友達と協力してやる','ノートや紙、タブレット、本などを準備する','理科・保体・国語','国語：図書閲覧室','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','8','C','','腹筋について','筋肉が何で中にあるのか','割ってみたり人間図鑑見る','','','','理科、保体','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','9','C','','フリーキックを入れるために','フリーキックの位置を確かめつつも、足のどこに充てるかも意識する。そして、キーパーアリの場合となしの場合で試してみる。','どこが一番入りやすい場所を、キーパーありバージョンなしバージョンで確かめる。','どの部分に充てれば、鋭い球が飛ぶのかを明らかにする。','1回1回どこに充てるかを意識して打つまた、動画などを見て、情報収集する。','GKグローブ、ボール（学校から借りる）スパイク','体育、数学','保体②：校庭','','例えば、このFKがうまくなるまでの過程を詳細に記録し分析できれば、将来的なFKトレーニングのメソッドとして役立ちそうですね（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','10','C','','一次関数に必要な力','一次関数の必要な力を見つける','一次関数の問題を解いて必要な要素をみつける','一次関数の問題を解くうえでひつような力を見つける。','一次関数の問題を解く、またはつくり、共通点を調べる。','ノートや紙を準備する','数学','数学：３B教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','11','C','','どうしたら効率よくフルーツ飴をつくれるのか。','どうしたら効率よく作れて、栄養バランスの取れた給食を作れるのかを調べる。','インターネットを使って調べる','フルーツ飴を給食で出してもらうための案を明確にする','栄養士さんなどにこの学校のフルーツアレルギーの人はどれくらいいるのかを聞く。またインターネットを使って調べる。','メモするもの。','家庭科','その他：視聴覚室','タブで調べる、栄養士さんに聞く質問を考える、できれば聞きにいく。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','12','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','13','C','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','14','C','','「その人に似合った髪型」とは何なのか','顔の形的にNGな髪型なども一緒に調べたい。','欠点やあった髪型などを誰かに説明できるように知識を身につける！','いろんな髪型を知る。','','','美術','','','髪型と顔の形について探究することで、社会還元はどのようにできますか？例えば、自動的に顔写真を分析して似合うものを提案してくれるAIを開発するとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','15','C','','なぜ最近の週刊ジャンプは人気がないのか','','','','','','その他','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','16','C','','ジャンプ力を上げる方法','','正しいフォームをしり実行する','ジャンプ力が伸びるフォームとは何かを研究する','まず自分のジャンプ力計測するその後プロの選手のジャンプのフォームを調べ自分のふぉむも動画を撮り二つを比較、その後その二つの違いをなくし計測する。また時間があったら陸上部の方々にフォームを見てもらいアドバイスをお願いしたい。','特になし','保体','保体①：体上','垂直跳びの計測と助走ありの計測どっちもする。おすぐっとなどのけがに気を付ける','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','17','C','','サッカー選手としてトップレベルにいる人達はどのようなことが僕たちと違うのか','','今回はキックのことについて詳しく探究する。','プロの選手のキックのフォームについて詳しくみて調べる。','キックがうまいと思うプロのサッカー選手をサッカー経験者にアンケートを取って一番アンケートの票が高かった選手の映像を細かく分析する','サッカーボール・スパイク','保体','保体②：校庭','自分のキックのフォームとプロの選手のキックのフォームを助走のところから１つ１つ画像を出して切り取っていく。軸足の位置などが比べ安いように意識してやる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','18','C','','昔から人気なアニメはなぜ今も人気なのか','','理由を知る','人気な理由を知る','','','社会','社会：２A教室','１つ','普遍的な面白さがあるアニメ、ありますよね。ドラえもんやクレヨンしんちゃん、ちびまるこなどでしょうか。これらが約10分程度のエピソードの中で、どのような展開をしているのか分析すると面白いと思います。ドラマだと、水戸黄門なんかが分析しやすいですね（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','19','C','','0','','','','','','音楽','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','20','C','','なぜ記憶がなくなるのか','日常生活での記憶はあるからでかい出来事を作る','','何でもかんでも覚える意識を持つ','','','保体','その他：視聴覚室','','初頭効果と系列位置効果というものがあります。記憶が忘却されるまでの期間を数学的に分析するのもありではないですか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','21','C','','読めないような地名がなぜあるのか','読み方に歴史などがかかわっているかなぜこんな地名がつけられたのか明らかにする','読み方や不思議な地名を探す。','その土地の歴史を調べる。','その土地の本などやタブレットなどで調べる。','','社会、外国語','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','22','C','','ファンダイクのディフェンス','','プレーをみる','１対１をする。真似をしてみる','ひとつひとつの動作に注目する。','','保体','保体②：校庭','','例えばファンダイクがハーランドを抑えるときの動作などを、いくつかの要素から分析してみるとよいかもしれません。目線・歩幅・狩るタイミングなど（新田）');
