INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','35','C','','集中力はなぜ変化するのか','本探究では、集中力が持続する環境とその条件を五感別に明らかにする。','まず、集中力が続かなくなる原因は聴覚だと仮説を立てて、それを中心に調べていく。','','集中できない時は、まわりではどんな音がしているときか、逆に集中できる音や音楽などを調べ実際に聞いてみる。','','理科、数学、音楽','音楽：音楽室','','');
