INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','37','C','','名詞の性は必要か','本探究では特にヨーロッパの言語についてルーツをたどって、ポーランド語を中心に違いを見つける。','欧米の言語でそれぞれ名詞の有無を調べる。','ポーランド語の文法を知り尽くして、ほかの言語を何系かで分けて比べてみたい','名詞に性がある言語とない言語を調べる。','資料集め','英語、社会','英語：１D教室','ポーランド語の7個の格と名詞の性について知ってみる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','38','C','','日本と海外の教育制度の違い','本研究では日本と海外の学習スタイルについて明らかにする','それぞれの学習スタイルについて細かく調べてみる','日本と海外の学習スタイルについて細かく調べる','インターネットや本などを活用して調べる','','社会','社会：２A教室','アジアあたりの教育と比べる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','1','C','','止められないカーブシュートをうつ方法','本探求ではどうすれば大きく曲がるシュートが打てるのかを探る','検索や本を読むなどをしてみる','分析してそれをもとに自分で試してデータを取り修正を加えて完成させる','調べたり動画を見て分析をする','スパイク','保体 理科','保体②：校庭','','物理の要素などを入れるとよいですね。ロベルト・カルロスのFKなどを分析すると面白いかもしれません（新田）');
