INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','9','C','','1対1じゃんけん 片方宣言心理戦におけるじゃんけんで原外生徒に勝利する方法とそこから考察する原外生徒の特徴','本探究では1対1じゃんけん 片方宣言心理戦におけるじゃんけんで原外生徒に勝ちやすい方法を明らかにすると共に、原外生徒の性格的な分類と傾向を考える。  （ここでは、1対1のじゃんけんで、他方の人のみがじゃんけんの前に出す手を宣言してじゃんけんを行うゲームを1対1じゃんけん 宣言心理戦と呼ぶことにする）','じゃんけんをして調査を行い、その結果を同じ手を出した人で分類し、その人の特徴を調査し、性格による出しやすい手の傾向を考える。同時に調査対象の原外生徒の手の大きさなどをできたら調査する。','とにかくデータを集めて分析をする。そこからじゃんけんの方法を考えてまたデータを集める。','生徒に協力してもらい、じゃんけんのルールを教えてじゃんけんをする。最初のデータ集めでは、僕が出す手を宣言して、相手には宣言してもらわずにじゃんけんをする。具体的な手をここでは書けないが、すでにあるじゃんけんデータから、宣言する手と出す手を決めてデータを集める。時間がありそうなら宣言する手は全ての手で行う。また、少しでもデータを集めるため、あいこの場合は仕切り直さずそのまま続ける。また、可能なら手の大きさと指の太さなどを測定させてもらう。  その集めたデータをもとに分析をして考察を考える。','すでにあるデータを集めておいてそこから自分の考察を考えてじゃんけんを行う。','数学','数学：３B教室','','');
