INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','11','C','','テンポの違う曲の気持ちの変化','変化した部分をまとめる。','心拍数とか自分で感じる体温などを細かく記録する。','テンションの上がる曲のテンポと心拍数の関係','心拍数がわかるものをつけて、曲を聞く。','ラボの先生に許可をもらう。（スマホ、イヤホン）','保体、音楽','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','12','C','','スポーツをすれば頭よくなるかもしれない','実際頭がよくなるのかを明確にする','いろんな種目のスポーツをした後に、いろんな科目の問題を解いてみて前回の自分となにが変わったのか調べる','勉強とスポーツは関係するのか','勉強とスポーツ両方できる人たちに聞きまわる。','勉強道具かもしれない','保体','保体①：体上','自分はどこまで運動ができるのか','学力と競技力には相関関係があると、先行研究で示されているので探してみてください。仮説を持って本調査に臨めるとよいです。例えば、保体で筋肉・骨格の勉強をしたら足が速くなるのかとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','13','C','','自分と絵師さんの違いを調べたい。アタリの種類とか調べたい。','どういう構図が人を引き付けるのかを明らかにする(明らかにするために、近付ける)','自分が好きな構図を試しに書いてみる。','自分が好きな構図を見つけたり多い構図を探す。','色々な構図を探す。','筆記用具、紙。','美術','美術：美術室','自分が描いている構図の傾向について。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','14','C','','ギターのハンマリングとスライドには何のちがいがあるのだろうか','ギター表現技法について','比較する','ギターの技法を自在に操れるようになる','たくさんの種類の曲をやる','ギター、スマホ、イヤホン、アンプ','音楽','音楽：音楽室','ギターなどの持ち込みの許可をもらう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','15','C','','呼吸の仕方や体の動かし方で長距離での脇腹の痛みが軽減されるのか','正しい呼吸や体の動かし方を明らかにする','インターネットで調べる、長距離が得意な友達に聞く、本などで調べてみる','なぜ脇腹が痛くなるのかを明確にする','インターネットで調べる。長距離が得意な人にいろいろ聞いてみる','特になし','理科、保体','理科：第１理科室','そこそこ調べ終わったら図書室に行って本でも何かわかることがないか調べたい','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','16','C','','記憶力が良くなる方法','記憶に残ることの共通点を調べる','印象に残っていることを内容ごとに分類しどのように脳や精神状態に影響しているか調べる。','人が覚えやすいこと、覚えにくいことの違いを調べる。','インターネットで調べる、アンケートをとる','アンケートをつくる','理科、保体、音楽','理科：第１理科室','Form作成','');
