INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','18','D','','なぜ人がゲームに熱中するのか。人の心理','なぜ人がゲームに熱中してしまうのか。ガチャやレベルアップの影響','人の心理を調べる','','','','理科','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','19','D','','インコースを打つためどうしたら打てるかがわかる','本探究ではインコースを打つためにプロ野球選手の練習方法や共通点を見つけて何でそうすると打てるのかを明らかにする。','プロ野球選手の練習を見てどんな練習しているかを見るのとインコースを打っている所見る','インコースを打てる高校生プロ野球選手の共通点と自分の違いを明らかにする','実際にプロ野球選手が打撃しているときのの動画を見る','動画を見るときに周りの邪魔にならないようにする','保体','保体②：校庭','バットの持ち込みを許可してもらう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','20','D','','足の速くなるには時間ではなく質なのか、、、','本探究では足の速い人の共通点、足が速くなる方法を明らかにする','足の速い選手の共通点を探す、たくさん足が速くなるトレーニング法を調べ試す','足が速くなる方法、秘訣を明確にする','ネットなどに乗っていることを実践してみる','・スパイク','体育','保体②：校庭','スパイク持ち込みの許可をもらう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','21','D','','足の速さと体力を鍛えるにはどうすればいいのか','本探求では、体力と足の速さを鍛えられる方法を明らかにする','何個かの練習方法を調べて、それを実際に試して、何もしていない状態と、練習方法を試した後のタイムを比べる','足を速くする練習方法を明確にする','インターネット、本で調べる','スパイク(申請)、タブレット','体育','保体②：校庭','スパイク持ち込みの許可をもらう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','22','D','','日焼け対策やテニスの練習をして、思う存分テニスができるようにしたい。','本探究では、日焼けをせず、うまくなるように工夫したり分析したりする','肌が白いうえにとっても上手い選手はどのような工夫をしているのだろう。','肌が白くうまくなりたい！','肌が白くなる方法とテニスのフォームを見直して美しくうまくできるようにしたーい','ラケットの準備','体育','保体②：校庭','ネットがないなああああああなしでどーやってやるか考える、','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','23','D','','たくさんの練習法を調べ、自分の課題に合ったものを見つけいい回数、時間を探って実行し、まとめる。','本探究では、自分のやったことのない練習法をたくさん試して自分の課題のサーブとストロークにあう効率かつ時短でできる方法の回数、時間などを明らかにする。','Googleとかでいろんな練習法を調べた後に効果に一番影響しやすい回数、時間をしらべ実行する。そしてよかったものをまとめていく。','自分の課題の練習法を調べる。','Googleなどで調べて見つける。','調べたのをまとめるために、パワポを用意する。','体育、','その他：視聴覚室','メモするパワポを作成する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','24','D','','プログラミングを上達させよう！','簡単にプログラミングが上達できそうな方法を明らかにする','何個か簡単にできそうな練習方法を調べて一番やりやすくプログラミングが上達しやすいものを選び，実際に試してみる。','上達しやすい良い練習方法を明らかにする','インターネットで調べる','家のノートパソコン','技術','その他：視聴覚室','ノートパソコンの許可をもらうのと調べたらメモしよう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','25','D','','バスケの大会でベスト８までいく','自分が苦手な感情のコントロールや、３Pの確率を上げる','自分より上手い人や、コーチに聞く、本やインターネットで調べる','感情のコントロールのところで、ただ思ったことを伝えるのでわなく、改善点やその理由も伝えるようにする ３Pのところでわ、力の伝え方や、力みすぎない','コーチやインターネットで調べたことを実践してみる','','保険','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','26','D','','仮説を立て、計画し、考え検証して、一番自分に合っているサーブ方法を鍛えれる練習方法を考えよう。','自分がどうしたら、サーブの距離が伸びて、どの形が自分に合っていて、成功率が高いのかを見つけ、自分のサーブの強さを上げるためにどのような練習メニューがいいのかを考え、実践しながらどんどんより良いものにしていく。','タブレットで調べたり、それを実践して、どのような結果になるのかを予想し、最終的な練習メニューを考える時に役立つかを考える。目標を立て、それを達成できるやり方なのかを、記録する。仮説を立て、それが本当なのかを検証する。','自分がサーブの距離を伸ばせないのをどうしたら改善できるのかを探求する。主にインターネットや本を使って調べた改善方法を実践し、改善していくのかをまとめて探求する。','主にインターネットや本を使って調べた改善方法を実践し、改善していくのかをまとめて探求する。考察や仮説を立て、いざ実践した時の結果をまとめやすいようにしておく。','ノート、タブレット、筆記用具、サポーター、シューズ、(本)、調べていく中で新しく必要になるもの','体育、保険','保体①：体上','ちゃんとレポートを描くことは忘れずに','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','27','D','','0','本探求では、トップ選手の練習方法と陸上競技で必要な能力を調べて明らかにする。','いくつかの方法を実際に試して、最初のときの記録と最後のときの記録を平均値・最高値などで比較する。','陸上競技に必要な能力を身につけられる、練習方法を明確にする。','本とかインターネットなどで調べる。あとはAiとかも活用してみる。','アンケートをとる。 気を付けることは、校庭にもたくさんの人がいると思うから、練習する場所。','体育、数学','保体②：校庭','スパイク、タブレットを許可してもらう。できたら、いろんな種目をやる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','28','D','','k-popが世界で人気な理由や、デビューするには何が必要かを調べる。みんなに魅力を知ってもらえるように頑張る！！','k-popが世界で人気な理由を明らかにする。デビューするには何が必要で何をしたらよいかを調べ、それに向けて、ダンスや歌がうまくなくなる方法を知る。','みんなに好きなk-popアーティストの推しポイントをインタビューする。ダンスのコツや基本を調べてみる。みんなに魅力を知ってもらえるように、j-popとの違いなども調べる。','k-popが世界で人気な理由を明らかにする。デビューするには何が必要か調べ、それに向けてダンスや歌をうまくなりたい！','k-popが好きな人に、推しポイントをインタビューする。他の国では何が人気なのか、ネットやSNSを使って調べる。時間が余ったら、デビューに必要なものを調べ、ダンスの基礎をやってみる','タブレット','音楽、体育、英語','その他：視聴覚室','インタビューできたら活動までにしておく！','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','B','29','D','','寝ることの大切さを伝える。','本探求では，寝ることの大切さについて明らかにする。','寝ることの大切さについてインターネットや疑問に思ったことを自分で記録してまとめる。','睡眠による体への影響を明確にする','自分の経験とインターネットで情報収集をする。','タブレット','社会，理科，保険体育','理科：第１理科室','タブレットの充電と調べることを覚える。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','1','D','','一番集中出来る環境は？','本探求では、音楽で集中力が上がるかを明らかにする','集中に音楽が関係したらどんな音楽がいいのかを調べる','どんな曲が集中力につながるかを明確にする','音楽が集中力につながるかを調べ、その音楽が何かを調べる','なし','音楽、理科 ？','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','2','D','','１番観客へ届ける技術がすごいライブはどれか','本探求ではミセスのこれまでのライブの技術や小道具などの秘密、そして来る人全員がみんな楽しめるための技術をどう工夫しているのかを明らかにする','「これがすごい！」というライブをランキングにし、そのランキングの3位～1位までの観客に届けるための技術の共通点を見つける','行って楽しそうなライブはどれか調べその1位～３位のライブの共通点はなにかを明確にする','インターネットでミセスの行きたいライブランキングを調べ、そのサイト内での1位～３位を調べるそして自分でそのライブの共通点はなにかを調べる','Formsでアンケートを取りたい。申請するものは１位～３位のライブによる','音楽、技術、理科、社会','音楽：音楽室','できればフォームスを作成して、インターネットで人気のライブを調べその理由を明らかにするそしてそのライブの共通点を調べ、それを覚えておくこと','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','3','D','','人間が集中力ができるのか、どうすれば集中力できるようになるのか','本探求では人間が集中力できる生き物なのか、どうやったら集中力が上がるのかを明らかにする','ネットで人間が集中力がない生き物なのかと集中力が上がる方法を調べ、実践する。','人間が集中力があるのかないのかを明確にする（時間があれば集中力が上がる方法を調べ出す）','ネットで複数のサイトを調べる。次回に向けてアンケートを取っておく','Formsでアンケートを取っておきたいから、先生に許可をもらう。','理科・保体','理科：第１理科室','1.ネットで調べる 2.Forms作成の許可、実行','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','4','D','','野球で二塁送球をノーバンで届かせるには','本探求ではなぜ二塁送球がノーバンで届かないのか、なぜポップタイムが上がらないのかを追求して明らかにする','ネットやYouTubeなどでプロ選手の動画などを見てどうしたら早く投げれるかどんなトレーニングをしているのかなどを、調べてみたり、部活、クラブのコーチに聞いてみる。','タイムと、二塁まで届かせること。','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','5','D','','バレーのルールについて','バレーをもっと楽しむためにルールを明らかにする','たくさん調べて少しずつ小さなことをやってみる','ルールを聞かれたらこたえられるくらいになりたい！','タブレットにあるよもっかとかでバレーのルールを調べたい！','タブレット','国語、体育','国語：図書閲覧室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','6','D','','アートブロックって、何？','発生を明らかにする','一日に何回か絵を描く','本当にブロックできたのかを確認する','アートブロックのある人に方法を教えて本当に変わったのかを見る','鉛筆と消しゴムとノートだけなので必要ないと思いません。','びじゅつ','美術：美術室','できればcanvaでやるのを許可を取る','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','7','D','','ソフトテニスが上手くなる方法','本探求ではラケットの打点をボールに当てるコツを調べる','ボールが落ちてから打つまでをはかる','ラケットの打点をボールに当てるコツを明確にする','大会動画などを見る','ラケット・ストップウォッチ','保体','保体②：校庭','大会の動画を見て分かったことを書いておく。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','8','D','','英語をしゃべれるようにする。','どんな単語があるか調べて覚える。','少しずつ言えるようにする。','英語を言えるようにする','英語の言ってる意味を理解して覚える。','なし','英語','英語：１D教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','9','D','','誰でも絵がうまく描けるようになるには','自分に合ったより良い練習法を見つける','絵がうまい人の書き方や練習法を見て、その中から自分に合った絵の書き方、練習法を見つける','絵がうまく描けるようにする。','絵がうまい人と自分の絵を比べて、どこがよくてどこがダメなのかを調べる。','筆記用具、スケッチブック、タブレットのみ。','美術','美術：美術室','調べる手順を確認してから作業をする。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','10','D','','なぜ生物は寝なければいけないのか','前回と同じ','まず本当に生物は寝なければいけないのか、寝ない生物について調べる。','寝ない生物について調べる','Personal Computerで調べたり、Libraryで調べたりする','Personal Computerの充電!!','保健・体育','国語：図書閲覧室','Personal Computerの充電!!!!!','やったぁ‼出られた～～!!!(^ωωωωω^)');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','11','D','','肩を強くし、球速を上げるには。','本探求ではなぜ自分は玉が速くないのか、理由を追求する。また球速を上げるには、肩を強くするには、どうしたらいいのかを明確にする','コーチに球速を上げるには何が今必要なのかを聞く。インターネットで調べる。プロの人のフォームを真似する。','球速を上げるにはどんな練習をしたらよいのか。またどんなことを投げるときに意識すればよいのかを明確にする。さらに意識する前と意識した後にどんな変化があるかを明確にする','コーチに練習法や意識することを聞いたりインターネットで調べる。聞いたことをできる範囲でやり、計測する','校庭で計測できるスペースが欲しいのでラボの人に伝える。また体育倉庫から計測できる機械を貸してほしいのでそれも相談する','体育、保険','保体②：校庭','今の球速をはかるためにＭ球と計測器を体育ラボの先生に伝えておく','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','12','D','','足をどうしたら速くするか','本探求では足を速くする走り方を明らかにする。','本を読んだりネットで走り方を調べる。そして調べて分かったことを実行する。','足が速くなるコツなどを明確にする。足が速くする方法を探る','本を読んだりネットで調べる。そしてその本やネットで調べたことをやってみる。','特になし（ストップウォッチ）','体育、保険','保体②：校庭','本やネットで調べる。そして調べて十分にコツなどが分かったら走る。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','13','D','','絵の具を使った絵を極める','本研究では絵の具を使った絵を極める、なぜ筆をうまく扱えないのかも明らかにする','考える、他人と比べて自己分析する','','','','美術','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','14','D','','スライダーとコントロールを極める','絶対に打たれないスライダーを投げられるようにする','どのようなスライダーがありどのようなスライダーがあるのか調べた上に選び投げる','スライダーはスライダーでも上手なフロントドアにできるような変化にする','とにかく投げてみて野球をやっている人に見てもらってアドバイスをもらう','グローブ、ボール（硬式→だめなら軟式に変更）','保健体育','保体②：校庭','グローブなどを持ってくるときの先生の許可と動画を撮ってみてどのぐらい自分の変化球（スライダー）が曲がるのかをまずためしてみてそこから研究してキレのバッターに打たれないようなスライダーに仕上げる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','15','D','','ソフトテニスをうまくなるには','フォアの制度・バック・サーブの制度を上げる','','プレゼンテーションで人が引き込まれる言葉やキーワードについて知る・プレゼンのイラストなどで引き込ませられるようなプレゼンの作り方について知る','Googleなどで検索してコツを調べる・小田口先生などの国語科の先生などに聞いてその部分の観点でいい感じの物を調べる','特になし','体育','国語：図書閲覧室','OneNoteの中にすべて打ち込んでるからその部分を確認する。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','16','D','','効果的な勉強方法を見つける','本探究では、様々な方法をやるだけではなく、そのほかの秘密があるのかを明らかにする','インターネットや先生、周りの人にどういうのがあるのか聞き、やってみる','勉強方法だけではなく、集中力の続け方や身の回り、使ってる物は何か明確にする','先生たちや友達、インターネットに聞いて、集める。','筆記用具、ノート、タブレット、教科書（教科による）、アドバイスをもらった上に必要なものが増えていくかもしれない','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','17','D','','自分のスイング速度を知る','本探究ではどれぐらい素振りしたらいいのかを明らかにする','いい素振りについて調べる','スイング速度を上げる方法を見つけて長打を増やす','実際校庭で打って（できればロングティー）自分がどれだけ飛ぶか確かめてスイング速度が速くなる方法を調べ実戦する','軟式ボール50個、金属バット、ティー台、スイングスピード測定器','数学、理科、保健体育','保体②：校庭','金属バットを使っていいか許可をとる。軟式ボールを使っていいか許可をとる。体育館がわを使う','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','18','D','','発見と、収穫を！！','本探求ではできるだけ多くの謎を見つけ、解明に向かう','謎のシーンを調べる','','','','技術、理科','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','19','D','','LGBTQ','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','20','D','','隕石が落ちる理由','本探求では、隕石が落ちる理由を明らかにする','インターネットで調べる、図書館で隕石についての本を探す、知っていそうな人に聞いてみる','隕石が地球に落ちる理由と、隕石の成分を明確にする。','知っていそうな先生に聞く、インターネット情報収集をする','特になし','理科、国語','国語：図書閲覧室','情報収集の最もわかりやすい仕方  考察の書き方  うまくまとめる方法','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','21','D','','ジャンプ力が高い人の特徴をインターネットで調べる。','本探求ではジャンプ力が高いは普段どんなトレーニングをしているのかを調べる','ジャンプとはどの体の部分を使うか調べる','ジャンプ力がない人の具体的な特徴を調べ底を改善する','次回に向けてインターネットで情報収集','特になし','体育、数学','保体①：体上','情報収集の最もわかりやすい仕方  考察の書き方  うまくまとめる方法','');
