INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','23','D','','SNSを通して起こっている事件、以前と比べた現在でのSNSの使われ方や歴史','本探求では、SNSの今に至るまでの成り立ちや、年々増えているSNS上での犯罪について明らかにする','SNSで何をすることが多いのかをアンケートし、その上で年々SNSでの事件が増えている経緯や理由について調査する','SNS上で犯罪が増えている理由を明確にする。そして、SNS上で起きている犯罪を減らすためにはどうすればよいのかを探求する。','クラスの人たちに調査する。  ①SNSをどのようなことに使っているか？  ②SNSは一日何時間使っているのか？（平日・休日）  （③AIに対してどのような印象を持っていますか？） （④SNSは今後どうなっていくと思いますか？）  また、ネットで情報収集する。','アンケートをFormsで集めたい。（持っていきたいもの・PC）','技術・歴史・保健体育（音楽・国語）','国語：図書閲覧室','Forms作成、Canvabaの準備、SNSについて調べる、My探求便利ツールの使い方の確認','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','24','D','','どうして三角や四角やバナナが貼ってあるだけの絵が売れるのか','どうしてそんな絵が売れるか明らかにする','どうやって絵につける色鉛筆それか絵具が作られたか，そしてどうして絵が作られたか','芸術は、爆発だっというけどどういう意味か明らかにする','インターネットを使う','タブレット、筆箱、紙、','美術','美術：美術室','プレゼンテーションを作る canvaを使いたいかも','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','25','D','','東京に高い建物がなぜ多いのか。また、高いビルなどを建てる時にどのような工夫がされているの。','本探究では、東京に高いビルや建物多いのかや、高い建物を建てる時に工夫しているところを明らかにする。','インターネットのいろんなサイトを使い情報を集め、集めた情報を整理する。','東京に高いビルや建物が多いのかを明確にする。','インターネットの情報を使う。','特にない','技術  （数学）','その他：視聴覚室','視聴覚室移動  パワポに情報を書き込む（それに少しつけか加えて完成させる）','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','26','D','','原外の国旗を作る','本探求では、過去の国々の出来事や、昔の国の国旗は今にどれくらい影響されているのか明らかにする。','歴史を知る…ネット、本  昔の国旗とどうやって作られたのかも調べる','調べた国旗たちの特徴をもとに原外に置き換えるとどんなことを国旗に入れられるか調べる。＝原外の特徴を調べる','「原外と言ったら」についてアンケートをとる  イメージカラーを考える','国旗の本','社会、美術','美術：美術室','パワポ仮作成','国旗ではなく校旗になるのでは？そしてそれはすでにあるのでは（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','27','D','','サッカーのシュートを上手くける方法、正確なパスを出す方法','目標を明確にする','シュート','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','28','D','','夜に携帯を見続けるのはどうしていけないのか','本探究では、夜に携帯を見続けるのはどうしていけないのかを明らかにする。','親がいうことやインターネットにかいてあったことを参考にしてインターネットを使って考える。','夜に携帯を見るとおこる悪いこととは何か','インターネットで情報収集。友達に、夜携帯をどれくらい使っているか調査する。また、何に使っているかも聞く。','pcの充電を満タンにしておく。事前に友達に調査しておく。','国語、道徳、理科（？）','国語：図書閲覧室','友達に調査したことをもとにパワポに調べたことをまとめながら進める。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','29','D','','どんな曲がどの層に刺さるのか知る。','本研究では、どんな曲がどんな時、どんな層に刺さるか知る。それを演奏に生かす','いろんな世代それぞれどんな音楽が好きか調べる','自分と同世代が好きな傾向にある曲を明確にする。  →その共通点なども明確にする','・友達、先輩に聞く  ・インターネットを使って調べる  →・歌詞や曲の速さ、ボーカルの種類などを調べる  →・一番多い傾向にあった特徴をまとめる','友達10人くらいに聞いておく  今回使うかはわからないけど、どんな曲か知るためにスマートフォンなどの電子機器が必要になることがあるかも','音楽、社会、国語','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('1','C','30','D','','0','本探求では、なぜ人気なのかと、なぜ嫌いな人がいるのかを知る。','いろんな人に好きなのか聞く。嫌いだったら、なぜ嫌いなのか、好きだったらなぜ嫌いなのかを聞く。','美味しいと感じるのはなんでか明確にする。温度だったらどっちのほうが人気なのか','サファリで調べる。抹茶は冷たいのと温かいのどっちが人気なのか調べる。','親などに抹茶はなんでおいしいと感じるのか、また、どちらのほうが美味しいと感じるか聞く。','社会、理科','理科：第１理科室','キャンバ作成','');
