INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','31','D','','視覚障害の方のための信号機ボタンの秘密','本探求では、目の不自由な人の暮らし方や、共に生きやすい未来を創るために私たちができることを明らかにする。','信号ボタンについて調べる・目が不自由な人の生活について調べる・意見を探す','視覚障害の方のための信号機の秘密について調べる','目が不自由な方本人の意見を取り入れる・調べる','なし','社会','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','32','D','','なぜ紙をあまり使わなくなったのか','紙の使用量の変化を調べて人が紙から離れて行ってしまっているのかを明らかにする','','インターネットのメリットとデメリットと紙のメリット、デメリットを比べる','インターネットと紙どちらがいいかアンケートをとる','なし。','社会','社会：２A教室','特にありません','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','33','D','','ソフトテニスで重くて速い球を打つには','重くて速い球の打ち方を明らかにする','インターネットや本で調べる、うまい人の打ち方をみてみる自分でもやってみる','インターネットで調べたうまい人の打ち方の特徴などを真似しながら何回か全力で打ってみてうまく打てた時とうまく打てなかった時の違いを見比べてみる','見比べてうまく打てた時にできていたことを意識しながらやってみる','なし','体育、理科・社会','社会：２A教室','まずはインターネットで調べてみる','');
