INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','A','39','D','','サブカルチャーの存在とその魅力について','本探求ではその独特な価値観を明らかにする','自分や周りの人（サブカルが好きな人）に刺さる作品を考えサブカルの作品について調べる','どんな基準でサブカルチャーになるのか','色んなサブカルの作品を調べて作品に触れてみる','スマホ、イヤフォン、持参の本を使いたい','社会 音楽 国語 美術','社会：２A教室','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','1','D','','外野が上手くなるには','どうやったら外野が上手くなるか、外野が上手い人との違いは何か','調べて実践する','どうやったら上手くなるかを調べて、実践する','どうやったら外野が上手くなるかを調べて、実践する','','体育','保体②：校庭','なし','');
