INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','5','D','','宗教、文化がたくさんある理由と','なぜ宗教に種類があるのだろう','宗教の種類、文化の種類、さまざまある理由','宗教、文化がもたらすいい面と悪い面','戦争を起こさないためにシュミレーションゲームなどで止めてみる。','スクラッチをやる','社会、外国語','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','6','D','','注射の年齢制限について','年齢制限がついている理由を調べる','調べる・病院のホームページ','注射の種類ごとに調べる','サイトを見る','','0','社会：２A教室','','新生児でも打てる注射もあります。打てる注射と打てない注射についてリサーチし、どうすれば新生児や幼児でも打てる注射ができるのか、開発してみても良いのではないでしょうか（新田）');
