INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','10','D','','集中が切れる原因と集中して勉強できる方法は','本探究では集中が切れる原因を調べて集中できる方法を明らかにする。','集中力に関係していることを調べて原因を考えてそれをもとに集中力が上がる方法を考える','集中力が切れる原因をインターネットで調べる。','分かったことをもとに集中力を保ったままできる勉強方法を考えてやってみる。','なし','体育','その他：視聴覚室','','インターネットで調査したうえで実験してみてはどうでしょうか。集中力が向上・もしくは低下する条件と、そうじゃない条件の2パターンで計測し有意差が出るか検討してみても良いのでは（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','11','D','','クッキーやマドレーヌなどの焼き菓子を、味も見た目も良く作る方法は？','本探求では、家にある道具で、味も見た目も良いお菓子の作り方を明らかにする。','作る時のコツを調べ、実際に試してみる。','インターネットや本を使って、焼き菓子を作る時のコツを調べる。','インターネットや本などで得た情報を基に、実際に家で作ってみる。','タブレット、お菓子作りに関する本','家庭科','国語：図書閲覧室','','今年は家庭科選択できなかったはずなので、別の方法からアプローチしてみてはいかがでしょうか。例えば、一流のパティスリーは造形にも非常に強いこだわりを持っています。どのようにしたら美味しさと造形の両立をできるか、検討するとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','12','D','','長距離が早くなるコツ','部活だけではない努力があるのではないのか','長距離が早い人の特徴','速い人のアドバイスを受ける','まずは普通に1500ｍを走る。でアドバイスをもらってメニューを立ててまた1500ｍ走る','自分、靴、タイマー','体育','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','13','D','','なぜ植物でも「花」には色があるのだろう','葉っぱに入っている成分とほとんどの花に入っている成分を比較する。','葉っぱの成分とほとんどの花に入っている成分を調べてノートなどにまとめて、比較する。','理科の先生に聞いてみる。','インターネットで葉っぱと花の色が違う理由を検索してみる。','花、木の葉っぱ、土、植木鉢','理科','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','14','D','','スマホ依存症について','スマホ依存症の原因','ネットで調べた改善点をやってみて、スマホから抜け出せるか','とりあえず三木先生。','ネットで原因と改善点を調べる。','田ブレ','理科？','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','15','D','','体感時間を調整するには？','本探求では、体感時間と集中・運動時の関係性を明らかにする。','運動中、集中しているとき、退屈な時、楽しい時に脳や体にどんな変化が起こっているのかを調べる。それぞれのときに体感で5分か10分計って誤差を記録する。','体感時間と楽しい時、退屈な時、集中しているとき、運動時の関係性を明らかにする。','楽しい時、退屈な時、集中しているとき、運動しているときに脳にどんな変化が起きているのかタブレットで調べる。それぞれの時に体感で5分か10分計って誤差を記録する。','タブレット','理科、数学、家庭科、体育','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','16','D','','サッカーの','','','','','','皇帝','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','17','D','','音楽の誕生、その進化の軌跡','本研究は音楽がどのようにできて、どのように進化したのか','音楽の誕生、その進化の軌跡を調べる','音楽がいつ、どのように誕生したのかを調べる','Googleを使って誕生した年、どのようにかを調べる','ない','音楽、社会','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','18','D','','五点着地の仕組みを理解してできるようになるには？','なぜ衝撃が分散されるかを明らかにする','ネットでどのように衝撃を分散するのかを調べる','どのようにすれば衝撃を分散できるのかを明確にする','実践してみる','特になし','n','保体②：校庭','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','19','D','','世界の教育について','本探求で明らかにすること（４）  1.日本と世界の地域的特色  2.1と関連付けた日本と世界の教育の違い・共通点  3.日本と世界の教育の問題点・課題点  4.私たちにできること・考察・まとめ  （教育現場で働く人の声や働き方をインタビューする】','','MY探求 進め方  １.日本の教育の仕方を明らかにする 分野を決めて特徴を具体的に  ２.日本の教育の課題点・問題点について調べる  ３.世界の国々の教育の仕方を明らかにする（地域の特色・特徴も具体的に）  ４.世界の国々の教育の課題点や問題点について調べる  ５.教育現場で働く人の声や働き方をインタビューしてみる  →そのうえで分かったことを６にまとめる  ６.世界の教育の仕方を踏まえたうえで今後自分がどうすべきか・改善点などを考える（考察）  ７.まとめ    調べたこと（おおまかに）→調べようと思ったきっかけ→仮説→調べたこと（ここがポイント！）→調べて分かったこと・考察→まとめ','まず国の理解を深めるために地域的特色・気候的特色・文化や暮らしなどいったん様々なことについて調べてみる！また国の数を根拠を示し厳選する（だいたい５か国ぐらい？）この課題には全教科が関わってくるため、具体的かつ詰め込みすぎないようにする。インターネットで調べる以外に身近にいる先生に実際にお話を聞いてみたり、本で調べてみたりさまざまなものを活用しながら調べる！','特になし','全教科','社会：２A教室','次回は国の特色について調べる！あらかじめ事前にスライドの構成や進め方の計画を練っておく。あとタブレットを忘れないこと！本を借りておくとさらに良い','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','20','D','','人見知りを直して、自分からたくさんの人とかかわれるようになるためには？','本研究では人と話すときに大切なことなどを知り、人見知りを直すために大切なことを明らかにする','コミュ力が高い友達などに聞いてみる。ネットで調べてみる','友達に聞いたり、本やインターネットで調べる。  人見知りはなぜなのかを知り、コミュよく高い人と比較して、話すときのコツを明確にする。','調べる。聞く。','特になし','道徳、国語','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','21','D','','リフティングがうまくなるためには、量より質なのか、質より量なのかを分析する','本探求では、リフティングは量なのか質なのか明らかにする','1つ目：まず素の状態でリフティングの回数を測って、その後にネットなどでコツ等を調べ、それをもとにもう一回やってみる。そしてコツを調べる前と後の回数を比較する。２つ目：まず素の状態でリフティングの回数を測る。そして３０分間リフティングをやり続けてそのあとにもう一回回数を測る。そして３０分前と後での回数を比較する。','どうやったらうまくなるのかを明確にする','コツはインターネットで調べる。あとはリフティングをしまくる。','ボール・トレシュー','体育','保体②：校庭','なし','これが実現すると社会においてどのようなインパクトをもたらすのか考えてみてください。例えば、リフティングがうまくなるとサッカー選手にとってどのような利点があるのか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','22','D','','野球ファンはなぜ減っているのか、増やすために自分にできることを調べたい','本探究では、なぜ野球ファンが減っているのかを明らかにし、野球ファンを増やすために自分にできることを明らかにする','まず他のスポーツとファンの数の推移を比べて、なぜそのスポーツが好きなのか、嫌いなのかを友達に聞いてみる','野球ファンを増やすために自分にできることを明確にする','インターネットで調べ、アンケートなどをとってみる','特になし','社会、保体','社会：２A教室','調べたことをWordなどにメモする','スポーツというものが、どのような成り立ちで出来上がり、現在の興行になっているのか調べてみるとよいと思います（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','23','D','','0','','','','','','','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','24','D','','モチベが下がる原因とどうしたらモチベが上がるのか','本探求ではモチベが下がる原因とどうしたらモチベが上がるのかを明らかにする','ネットで調べたことを実践する 友達にどうすればモチベが上がるかを聞く','','','','0','その他：視聴覚室','','J-STAGEで動機付けの先行研究を調べてみるとよいと思います（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','25','D','','好き嫌いがどうやったらなくなるのか、減るのか。','本探究では食べ物の好き嫌いがどうやったらなくなるのか、減るのかを明らかにする。','インターネット上を使って調べる。実践してみる。友達に何で嫌いになったか聞いてみる。','どうやったら嫌いな食べ物を嫌いじゃなくなるのかを明確にする。','友達に質問する。インターネットで調べる。実践してみる','なし。','保体 家庭科 CT','その他：視聴覚室','発表資料の準備。インターネットで調べる。','なぜ味覚が年齢を重ねるにつれて変化するのか探究してみてください（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','26','D','','ドラえもんの最終回はどんなものなのだろうか','ドラえもんに最終回があるのかをはっきりさせる','ググる','','','','歴史','','','ドラえもん最終回は何パターンかありますね。どれが事実で、事実じゃないとしたら、なぜその通説が広まるのか検討してみてもよいのではないでしょうか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','27','D','','日本人の食に対する考えはどのようなものなのか','和の心が食べ物を大切にする心なのかを明らかにする','検索や文献','日本の食文化について調べる','検索や文献を見る','なし','社会','社会：２A教室','発表資料を作れ','日本の食文化の成り立ちと、日本史を重ねてみてみると何か見えてくるかもしれません（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','28','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','29','D','','和服、制服の変化について','ほんとに和服や制服などを着る文化はなくなったのか、変化について調べる。','ネット検索する。アンケートをとる。','和服・制服の歴史を調べる。','ネットで調べる。アンケートする。','なし','社会','社会：２A教室','発表資料をつくっていく','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','30','D','','バスケ面から見た自分自身を知る','本研究では客観的に自分自身を解析して詳しい観点から理解して  バスケではどのようなプレーなのか','まずは僕がどのようなプレーヤーであるかを確認  ほかの人と自分を比べる','','','','体育','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','31','D','','「個性」を外見で表現するのはダメなのか','校則がある理由を調べる','めちゃくちゃ厳しい校則を調べる','外見に関する校則の必要性について調べる','たくさんの学校の外見に関する校則を調べる','','社会','社会：２A教室','発表資料を同時進行で作る','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','32','D','','和菓子屋減少の理由はなにか','本探求では、和菓子屋の減少の理由を明らかにする。また、和菓子の普及率はどうやったら戻るかを考える。','和菓子屋の減少の理由を調査し、グラフにまとめる。','和菓子屋の減少の理由を明確にする。','ネットで調べてみる。また、友達にも聞いてみる。','アンケートをFormで集めたい。ラボの先生に聞いてみる。','家庭科、社会、数学','社会：２A教室','foam作成','洋菓子はパン屋さんと併設されていたり、ケーキ屋さんという文化が根付いているのでよく見かけますが、和菓子は確かにあまり見かけませんね。なぜなのでしょうか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','33','D','','カントリーマアムが小さくなった原因とその背景','カントリーマアムがなぜ小さくなりその背景にはどのような事が起きているのかを考える。','カントリーマァムの歴史を辿って何が変わったのかを調べまとめる。','カントリーマアムが小さくなった理由を社会の変化と結び付けて調べる。','インターネットで情報を集める。','クラスや家族にアンケートを取る。','家庭科、社会','社会：２A教室','発表資料の準備','小さくなった理由はすぐわかると思います。問題は企業側が消費者にサイレントで大きさを調整したり、価格を動かすところではないでしょうか。このような行動が企業・製品イメージにどのような影響を及ぼしているのかとか、検討しても面白いのではないでしょうか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','34','D','','現代人の無駄な時間とは何か、また無駄な時間を削減するには','そもそも無駄な時間は何かを明らかにする','アンケートをとり、みんなにとって無駄な時間を聞く。そして、その無駄な時間の傾向は何か整理する。','無駄な時間とは何か','無駄な時間の定義を明確にする','Formsでアンケートを取りたいので相談。','社会','社会：２A教室','Formsを作成','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','35','D','','ディズニーはなぜあんなにもわくわくするのだろう','パーク内で工夫されている建物や置物を調べる','','パーク内の音楽、アトラクション、トイレ、世界観、それぞれに着目して調べる。','ネットで調べる。','タブレット充電する','音楽','音楽：音楽室','タブレット忘れない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','36','D','','ギターの早く上達する練習方法を調べる','ギターが早く上達する練習方法を明らかにする','練習方法を調べて実践してみる','ギターがうまくなってもっとギターを楽しめるようになりたい','まずインターネットでギターの効率いい練習方法を調べて実践してみる','ギター本体とアンプの持ち込み tab譜をみるためのスマホ','音楽','その他：視聴覚室','練習方法をたくさん調べておく、どの練習が効果的なのか調べる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','37','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','B','38','D','','投げたことない変化球を投げるためには','投げたことない変化球を投げたい','','','','','0','','','いっそ、新しい変化球の開発に取り組んでみては？これまでにない持ち方・握り方・ボールのリリースなどを試してみると、何かが生まれるかもしれません（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','1','D','','ドリブルをつよくするには','ドリブルを強くしたい','インターネットで調べる','ドリブルの強くなる練習メニューをやる','頑張る','ボール','保体','保体②：校庭','','どの競技においてのドリブルなのかで話が変わりますが、なぜドリブルを強くする必要があるのか個人単位ではなく社会単位で改めて考えましょう。ドリブルが強くなることで、どのような発見が得られますか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','2','D','','人は涙が出るのか','','インターネットや本で調べて、結果をまとめる。また、どんなときに涙が出やすいかアンケートを取ってみたい。','そもそもなぜ人は悲しい時に涙が出るのかを調べる','今日はラボ活動ではないので前提としてインターネットで軽く調べてみる','どんな時に涙が出るのかをアンケートを取りたい。ラボの先生に相談してみる。','国語、(全教科？)','その他：視聴覚室','アンケートの作成、アンケート作成の許可','ジェームズ・ランゲ説というのがあります。この説では「悲しいから泣くのではなく、泣くから悲しいのである」と言われています。逆にキャノン＝バード説は、「悲しいから泣くのである」です。どちらが正しいのか、検証してみてはどうでしょうか。涙が難しければ、例えば心拍数を上げるから楽しいのか、楽しいから心拍数が上がるのか、などどうでしょう（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','3','D','','アイスの美味しさの根源とは','なんでアイスが美味しいのか','ネットで調べてまとめる','アイスがなんで美味しいのかを調べる','人気のアイスなどを調べて、その共通点を見つけてまとめる','タブレット','家庭科','その他：視聴覚室','「','今年度は家庭科が選択できないはずです。別の角度から模索してみてはいかがでしょうか。例えば、数学で相関関係について考え、季節とアイスの美味しさについて検討するとか。');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','4','D','','どんな場面なら解釈の影響が大きいのか','本探求ではどんな場面だと解釈の影響が大きいのか明らかにしたい','インターネット、アンケート','','','','0','その他：視聴覚室','','解釈の影響とはどのようなことを指すのか、定義を明確にするとよいと思います（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','5','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','6','D','','身体能力を上げるには','本探求には来年度の体力テストに向けて、高得点をとれるようにするためにはどのようなことが大切なのかを明らかにする。','インターネットで調べたのを校庭で試してみて実践する。','渋谷区がほかの地区と比べて体力が平均が低いから、どうしたら平均が上がるか考える。','タブレット、インターネット、そして調べたものを校庭で実践','','保健体育科、理科','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','7','D','','ケガしないために','本探求ではファウルされた時の倒れ方自分の骨折の原因、ケガしないためにすること。','タブレット、本で調べる。骨折のたいけんだん','もうケガしないための準備や倒れ方を研究する。倒れない体幹をつくる','タブレットで調べる、プロの試合を見てどういう倒れ方をしているのか研究','','保体','その他：視聴覚室','','例えばですが、ファウルをよくされるけど怪我しない選手としてメッシが浮かびます。メッシの被ファウル時の倒れ方などを並べたり重ねたりして分析することで、怪我しにくい倒れ方を検討できるのでは（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','8','D','','日本各地でどのようなカツオの種類があるか','地元に限らず、どのような場所でどのような種類のカツオがあるか探りたい！','街中アンケート～究極のカツオを求めて～','カツオが取れる環境の条件を調べる。','インターネットで調べる。出来たらカツオが有名な地域に（日本各地）行ってアンケートする','なし','社会','社会：２A教室','キャンバを作る。','これを明らかにすると、究極のカツオはどのようなところで役立ちますか？（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','9','D','','協和音と不協和音のちがいとは','本研究では協和音と不協和音の共通点を明らかにする。','色んな和音をつくってアンケートでその和音の心地よさを評価してもらってその共通点を見つける','協和音と不協和音の違いを明確にする','インターネット アンケート','チューナー','音楽','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','10','D','','共通点を見つける','本を読んで共通点を探す','本読む','伏線がある本を読む','インターネット アンケート','','国語','国語：図書閲覧室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','11','D','','勉強ができるようになる効率的な脳の使い方','数学の視点で、人気の勉強法をとる→それは脳科学的にほんとにそれがいいのか調べる','アンケートをつくる','アンケートを取る','アンケートを集計する','間違った情報を持ってこない','理科','その他：視聴覚室','めもしておく','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','12','D','','ギター上達したい','ダウンピッキングに適しているピックを探す。','自分の弾いてるところを撮ってうまい人と比較する','難しい曲を原曲と同じリズムでできるようにする。ダウンピッキングを極める','メトロノームをつけて、いろいろ技法を使う','弦で指を切らないように','音楽','音楽：音楽室','ギターを持っていけるか確認する。あとその他道具','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','13','D','','ヨーロッパはなぜ発展しているのか','昔のヨーロッパの国が何をしたのかと土地の特徴を調べる','昔のヨーロッパの歴史と土地の特徴を調べる。そしてなぜ発展したのか分析する。','ヨーロッパの歴史と土地の特徴を調べる','ネットでまず土地の特徴を軽く調べて、それからヨーロッパの歴史を調べていく。','間違った情報を持ってこないために何個かのところで調べる。','社会','社会：２A教室','パワポかタブレットのメモ帳にメモしておく。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','14','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','15','D','','バレーボールのレシーブを1000回したら腕はどうなるのか','腕がどうなるか','ひたすらレシーブをする','1000回レシーブをしたら腕はどうなるのかを実践するつもりだった、。','レシーブをする。','けがをしないこと、周りに注意して行うこと。','体育','保体①：体上','なし','これを明らかにすると、どのような良いことが生まれますか？例えば、腕が壊れないレシーブの仕方・プロテクターの開発など、もう一段回深めましょう（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','16','D','','サッカーがうまい人の特徴','うまい人の動画などを見て研究する','動画を見て実際にやってみる','外国人の選手なども見て学ぶ','実際にやってみる','人にボールを当てないこと','体育','保体②：校庭','','ここでいうサッカーの”うまい”は、サッカーIQですか？テクニックですか？その前提をしっかり定義した上で検証し、もう少し課題を絞るとよいです。例えば、うまい縦パスとは・・・など（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','17','D','','スリーポイントを決めるための練習法','スリーポイントを決めるための練習法は何がよいのか','様々な練習法を調べてやってみる','スリーポイントの確立目指せ５０パーセント','フォームを固める練習、ゴールの感覚をつかむ練習を調べてやってみる','準備運動。人にボールがぶつからないようにする','体育','保体②：校庭','メモを取る','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','18','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','19','D','','足が早くなる方法','早い人の共通する走り方の工夫を調べて体に定着させ、記録の向上につなげる','仲のいい足が速い人に聞いたりトップスプリンターの走り方などを分析してそれを意識しながら走る。','100mの記録を挙げる','','','体育','保体②：校庭','','トップスプリンターのフォームを自分の身体に定着させる過程に着目してもよさそうです。つまり、プロと自分の身体のずれをどのように調整し、技術をモノにするのか。探究的ですね（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','20','D','','スリーの入るアーチの高さや工夫','本探求ではスリーが入るアーチの高さや工夫を見つける','スリーの入るアーチの高さをさがして、練習法を探して実際にやってみる','実際に練習してスリーを入るようにする','入りずらいアーチの高さ フォームのきれいさを考える','体操','体育','保体①：体上','スリーの入るアーチの高さを確認する','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','21','D','','気になる子を一瞬で虜に！？みたいな魔法の道具は作れるのか','人が魅力を感じる原因や共通点を追求し、それを応用して魔法の道具のようなものを作れるのか','恋愛してる友達とかで実験する・ネット、動物の生態の本とか・ドラえもん見る','ドラえもんになりたい','・実際に恋愛してる友達で実験する(片思い、両想い、両片思いで変化はあるのか。逆に、魅力を感じない人の特徴は？)１，ほかの動物の求愛行動やモテル条件は？２，ひとにそれは当てはまる？３，それを利用して人工的に人に魅力を感じさせることはできる？  １２３までを図鑑や本インターネットで・結局ドラえもんになれるのか','友達、アンケートをFormで作りたい。','理科・保健体育、国語','国語：図書閲覧室','アンケート作成、許可・キャンバに同時進行でまとめとく','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','22','D','','じゃんけんの必勝法','じゃんけんの心理と必勝法を見つける','まず心理を調べてどうすれば勝つ確率が上がるのか実践などしてみる','じゃんけんを勝てるようにして運ゲーを勝利する','調べて実践する','なし','','その他：視聴覚室','','じゃんけん実験は、心理学分野でよくやられているのでJ-STAGEで検索してみるとよいです。そのうえで、何か仮説を持って取り組むとよいのではないでしょうか。例えば、左手にロブスターを持って相手に見えるようにする（チョキへの誘導）と、相手はグーを出しやすくなるのではないか、とか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','23','D','','3を決める方法','3を決める方法を見つける','ネットで調べる、','ネットで調べて実際にやってみる','一番入りやすいフォームを見つける、シュートする時の感覚をなんとなく覚える','ない','体育','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','24','D','','スリーの確率と角度の関係','入りやすい角度やフォームを見つける','体育館に行き実際にシュートを打ってみる','入りやすい角度を見つける','１０本スリーを打ち確率を調べる','ボールを使いたい','体育','保体①：体上','１０本角度 ５か所ほど','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','25','D','','異常気象と地球温暖化の関係性について','異常気象と地球温暖化の関係性を明らかにしたい。','ネットで調べたり、気象庁の一年の平均気温を比べたりしたい。','異常気象と地球温暖化の関係性とは','2022年～2025年までの３年間の平均気温や、異常気象の中でも猛暑の発生回数を調べ、それそれを年ごとに比較してみたい。','タブレットの充電100%','理科','理科：第１理科室','グラフを使って比較したい。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','26','D','','マイクラで学校を作る','','','','','','0','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','27','D','','教師の言動を心理学的に分析する','良い先生、しんらいされる先生とは','共通点があるはずなので、共通している部分を見つける','先生がよく言う言動を集める','とりあけずよく言うせんせいの言動を調べる','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','28','D','','体力を増やすには','運動をしてすぐにばてないように体力を増やす方法','食事、筋トレなどのトレーニング、生活方法など様々な視点から調べて実践する','ネットで調べて今の自分ができるものを選び実際にやってみる。','今までの自分と、調べてみて実践した自分を比べてみて効果があるかどれくらい変わるか調べる。','ない','保健','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','29','D','','速いボールを投げるためにはどうすればいいのか','体を小さくても早いボールを投げる方法','現在の球の速さを理解し、いろいろな方法をネットで探し、良い結果が出るまでやる。','人の体のつくりについて調べて球速を上げる方法を調べ、実践したい。','人の体のつくりについて調べて、自分には何が足りていないのかを調べる。','','体育','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','30','D','','なぜ球場のごはんは高いが１０年前からどれぐらい上がったのか','10年前から物価も結構上がったと思うから300円ほどは大体のものの物価が上がったと思う','食べログで10年ほど前2016年ほどのものを調べて値段を確認する','今の球場の食べ物は値段が上がった分クオリティも上がったのか','10年前から球場のものも上がったと思うがそれ以外のコンビニなどのものもどれぐらい上がったのか','なし','社会','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','31','D','','','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','32','D','','学年の問題を解決するためにはどのような話し方をしたらいいか。','話を聞いていない人の特徴を明らかにする','インターネットで話を聞いていない人の特徴を調べる','話を聞かない人の特徴がどのくらいあってどんなものなのかを調べる','インターネットで話を聞いていない人の特徴を調べ表にまとめる','アンケートをFormでつくりたい。','国語、保体','国語：図書閲覧室','今回メモしたものをcanvaでまとめる','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','33','D','','太陽を見るとくしゃみが出る理由とくしゃみが出るといわれているものは本当にでるのか。くしゃみの威力はどのぐらいすごいのか','太陽を見るとくしゃみが出る理由とくしゃみが出るといわれているものを試して、うそのものと本当のものを見分ける。','自分だけだと個人差があるから、友達にもやってもらう。','','','','理科、保体','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','34','D','','味覚が鋭い人と普通の人の違い','違いと、味覚を鋭くする方法を調べる。','味覚を鋭くする方法を自分で検証し、何もやっていない人と同じ食べ物を食べたり、かき氷のシロップをあてたりして比べる','違いと、鋭くする方法があるのかを明確にし、検証する。','味覚を鋭くする方法を知らべそれを自分で試してみる。試す前と試した後で同じものを食べて具材が分かるか検証する。友達とも試す。','タブレット、食べ物 家で検証する','理科、保体','その他：視聴覚室','','食事の楽しさは、味覚・触感・匂い・視覚情報から成り立っています。あえて、味覚以外を遮断してみるとかどうでしょう（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','35','D','','どうしたらほどけなくなるか','本探究では靴紐をほどけないように調べてどうやったらほどけないか実験をする。','ネットで調べて自分で実験をたくさんする。','調べて実験を繰り返す。','調べて実験を繰り返す。','ない','','その他：視聴覚室','ない','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','36','D','','バスケのシュート率を上げる方法','','','','','','保体','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','37','D','','着物が着づらいと思われる理由は？','着物の欠点を理解し、着にくい理由を明らかにする。','','\bB','ネットで調べる、図やグラフを用いて、情報を取り入れる。','タブレット','社会','社会：２A教室','着物は冠婚葬祭などのシチュエーションに着たいと思っている人が多い。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('2','C','38','D','','MY探求の意味','なぜ小中学校でやるのか・My探求で得られる技術とは','調べる・インタビューしてみる','','','','0','その他：視聴覚室','','人類学などでよく使われる、自分自身の体験談を書きだし共通の要素や変化を捉えるものとして、ナラティブ・アプローチやエスノグラフィというのがあります。探究の方法の1つとして使えるかも（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','1','D','','曲の雰囲気を決めるものは何か','曲の雰囲気を決めるものは何か','','','','イヤホンとスマホ','音楽','音楽：音楽室','歌詞だけなく楽器の奏法や音の種類によっても人気が左右されるのかもしれない。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','2','D','','サッカーがうまい人の特徴','サッカーのうまい人の分析をしたりする','分析してやってみる','サッカーがうまい人・選手の特徴を明確にして自分もうまくなる','サッカーがうまい人・選手の特徴を明確にしてそれをやってみる','','体育','保体②：校庭','','ここでいうサッカーの”うまい”は、サッカーIQですか？テクニックですか？その前提をしっかり定義した上で検証し、もう少し課題を絞るとよいです。例えば、うまい縦パスとは・・・など（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','3','D','','非言語コミュニケーションと心理の関係','非言語コミュニケーションとは何かを明らかにし、具体例を挙げる','','','','','保健体育、数学','保体①：体上','','');
