INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','6','D','','強い人の特徴','特徴調べる','調べる','','','','体育','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','7','D','','スポーツは、左と右、どっちの利き手足が有利なのか','野球・バスケ・サッカーのどっち利きのが有利かを明確にする','調べたり、実際にやってみたりする','','','','体育','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','8','D','','魔法は使えるのか','本研究では科学で証明できる魔法と、証明できない第六感から発されるような魔法の二つを明らかにする','まず魔法の超常現象の情報収集、そこから科学でできるかどうかを考え・分ける。科学で証明できると分けられたものは実験し、それ以外の物は何かつながりや共通点がないか考えてみる。そのあとできるかどうか実際に試してみる。','','','','理科・保健体育','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','9','D','','0','','','','','','0','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','10','D','','アマモの分析と観察','アマモと土の関係','とにかく実験＋アマモのそもそもの観察','暑さや海の性質に左右されない方法を探す。','アマモは土から栄養をもらうためその肥料やそれがアマモに与える変化を観察する。','理科の先生に許可をもらう。','理科','理科：第１理科室','カレンダーや表を作る','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','11','D','','効率のいい勉強方法','本研究では具体的にどんなものが関係しているか','友達から協力をあおる','心理学と自分の差について考える','アンケートをとる','なし','数学 理科 国語','その他：視聴覚室','心理学','勉強における効率の良さとは、どのようなことでしょうか。たくさん覚えることなのか、点数を取りやすくなることなのか、地頭がよくなることなのか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','12','D','','U8はどうしたら勝てるのか','U8でも分かる綺麗な言葉で説明する','コーチに色々教えてもる','友達に聞く','友達にどういわれたらわかりやすいか、プレーを見せるのかどうするのが最適化調べる','ない','体育、英語','保体②：校庭','アリソンにどうするか聞く','ティキタカがいいのかポゼッションがいいのか、相手チームとの兼ね合いもあると思いますが、チームとしての哲学を探究するということなら良いと思います。それを実現するための要素について考えてみては？（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','13','D','','体内時計と実際の時間の関係','','','','','','体育','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','14','D','','0','ギターの音と心理について','ギターの音とはどのような分類があるのかExクリーン ロック 各雰囲気のギターの音をきわめて他人に聞いてもらいどのような感情を抱いたか聞く','ギターのサウンドの分類・サウンドごとの印象またどのような感情の時に聞きたいか深める','自分ギターを使ってエフェクターなどを駆使しサウンドの分類をする。そのあと各サウンドごとの代表的な曲のフレーズを練習しそのフレーズを他人に聞いてもらいどう思ったか聞くそれにより音楽と感情の関わりを深める','ギターとアンプの持ち込み タブ譜検索用のスマホ','音楽、道徳','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','15','D','','手から出る音の大きさ','本研究では時間経過と指の鳴らす音の関係を明らかにする','そのために指が鳴る原理と、実際に鳴らす実験をしてみる','調べたら指が太くなるらしいので、普通に手をたたくときどうしたら大きい音が鳴るか調べることにする。ベストな環境と、ベストな位置を見つけ出して手をたたくうえで最大の音を出すこと。','まず気温、湿度を計測し、音量を計測する。','','理科','保体②：校庭','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','16','D','','0','本探求では漫画、アニメの魅力や人を引き付ける何か、また最も人を引き付けるジャンルを明らかにする','そのためにみんなに好きなジャンルのアンケートを取り、その結果をもとになぜそれが人を引き付けるのかを明らかにする','','','ない','分からない','保体①：体上','','');
