INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','20','D','','なぜ音楽は世界中でたくさんの人に愛されているのか','','ジャンルを絞って有名な音楽や長く幅広い世代から愛されている音楽を調べる','幅広く愛されている音楽や、有名な音楽の特徴や同じところを明確にする','音楽を調べる➡実際に聞いてみる、友人や学校の人にアンケートをとってみる、ネットで調べる','スマホ、イヤホン(有線が使えないのでできればBluetoothで)、スマホ使用のための携帯型WI-FI、アンケートをとるためのFormを作る(アンケートをとる場合)','音楽','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','A','21','D','','0','メンタルが関係してるのか考える','自分が毎回走ってる時のタイムを測りメンタルを考える','','','','0','保体①：体上','','逆に、メンタル状況に刺激を与えて走ってみてはどうですか？例えば、5分で泣ける動画を見てから走った場合のタイムと、5分で笑えるお笑いを見てから走ったタイムの差異とか（新田）');
