INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','14','D','','「その人に似合った髪型」とは何なのか','顔の形的にNGな髪型なども一緒に調べたい。','欠点やあった髪型などを誰かに説明できるように知識を身につける！','いろんな髪型を知る。','','','美術','','','髪型と顔の形について探究することで、社会還元はどのようにできますか？例えば、自動的に顔写真を分析して似合うものを提案してくれるAIを開発するとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','15','D','','なぜ最近の週刊ジャンプは人気がないのか','','','','','','その他','その他：視聴覚室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','16','D','','ジャンプ力を上げる方法','','正しいフォームをしり実行する','ジャンプ力が伸びるフォームとは何かを研究する','まず自分のジャンプ力計測するその後プロの選手のジャンプのフォームを調べ自分のふぉむも動画を撮り二つを比較、その後その二つの違いをなくし計測する。また時間があったら陸上部の方々にフォームを見てもらいアドバイスをお願いしたい。','特になし','保体','保体①：体上','垂直跳びの計測と助走ありの計測どっちもする。おすぐっとなどのけがに気を付ける','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','17','D','','サッカー選手としてトップレベルにいる人達はどのようなことが僕たちと違うのか','','今回はキックのことについて詳しく探究する。','プロの選手のキックのフォームについて詳しくみて調べる。','キックがうまいと思うプロのサッカー選手をサッカー経験者にアンケートを取って一番アンケートの票が高かった選手の映像を細かく分析する','サッカーボール・スパイク','保体','保体②：校庭','自分のキックのフォームとプロの選手のキックのフォームを助走のところから１つ１つ画像を出して切り取っていく。軸足の位置などが比べ安いように意識してやる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','18','D','','昔から人気なアニメはなぜ今も人気なのか','','理由を知る','人気な理由を知る','','','社会','社会：２A教室','１つ','普遍的な面白さがあるアニメ、ありますよね。ドラえもんやクレヨンしんちゃん、ちびまるこなどでしょうか。これらが約10分程度のエピソードの中で、どのような展開をしているのか分析すると面白いと思います。ドラマだと、水戸黄門なんかが分析しやすいですね（新田）');
