INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','20','D','','なぜ記憶がなくなるのか','日常生活での記憶はあるからでかい出来事を作る','','何でもかんでも覚える意識を持つ','','','保体','その他：視聴覚室','','初頭効果と系列位置効果というものがあります。記憶が忘却されるまでの期間を数学的に分析するのもありではないですか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','21','D','','読めないような地名がなぜあるのか','読み方に歴史などがかかわっているかなぜこんな地名がつけられたのか明らかにする','読み方や不思議な地名を探す。','その土地の歴史を調べる。','その土地の本などやタブレットなどで調べる。','','社会、外国語','社会：２A教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','22','D','','ファンダイクのディフェンス','','プレーをみる','１対１をする。真似をしてみる','ひとつひとつの動作に注目する。','','保体','保体②：校庭','','例えばファンダイクがハーランドを抑えるときの動作などを、いくつかの要素から分析してみるとよいかもしれません。目線・歩幅・狩るタイミングなど（新田）');
