INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','27','D','','音を奏でるためには','ギターの起源を知って基礎的なことを学ぶ。ただギターの作り方などは一切見ないようにする。','調べても分からないことが判明した。家に弦の張っていないギターがあることを思い出したのでそれを使っていきたい','何か一つに偏らずバランスよく音について探求する','楽器だけではなく普段の音の仕組みなど理科的な部分も勉強する','楽器を作るための堅い糸と箱みたいなもの','音楽 理科','音楽：音楽室','次の時間ではもう素晴らしい音が音楽室から聞こえるような楽器を作っておく。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','28','D','','ダンクをするには','自分の今のジャンプ力知り、あとどれぐらいでリングにとどくか、ダンクができるかを理解する','フォーム、足の幅、ステップなどを理解する','自分のジャンプ力を理解してフォーム、足の幅、ステップなどが合わさっているかを理解','','バッシュ、','体育','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','29','D','','どうして日焼けするのか','陽に当たるとどうして焼けるのか、逆に陽に当たらないとどうして黒さが引くのか','焼けている人と焼けていない人の違い','焼けている人と焼けていない人での過ごし方の違いを見つける','実際に焼けている人と焼けていない人に過ごし方を聞いてみる','特になし','理科・保体・体育・家庭科','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','30','D','','','野球や数学と結びつけながら、ものの回転数が多いと、なぜスピードが早くなるのかを考える。また、頭の回転が早いとはどういうことか考える。','いろいろなもので回転数と速さの関係性を知る。また、自分が実践できそうなものは実践する。','','ボールの回転数を変えて投げて、スピードがどのように違うか考える。また、自転車をこぐときに、回転数を変えてみて、スピードの違いを調べる。そして、最終的には頭の回転が早いという言葉の意味に結びつける。','ボール、記録用の紙、・・・','9探究 (2)''!L304','','実験を家でやるか、学校の校庭でやるか、考える。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','B','31','D','','集中してるときなんで時間が早く感じるのか','本探求では、集中してるときの環境などを明らかにする。','','まず、音楽などの聴覚に刺激が与えられたときに、時間の流れをどう感じるか','インターネットで調べたり、自分の体験をもとに表にまとめる','','0','音楽：音楽室','','');
