INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','3','D','','サッカーの仕組み','本探求ではサッカーの仕組みを明らかにする','サッカーがうまい人たちの共通点を調べる','ドリブルの仕組みを明確にする','実際の試合を見たりする。','サッカーのスパイク','保体 数学','保体②：校庭','','ここでいうサッカーのうまさとは、サッカーIQなのかテクニックなのか、定義を明確にして下さい（新田）');
