INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','5','D','','守備選手の体（目、重心等）の使い方によるファウルをもらいにくくなり尚且つ攻撃の芽をつぶす方法','本探求では同じ目的を中心に探究するがそれに加えて守備がうまい選手の体の使い方（重心移動などのフィジカルコンタクトの重要性）についても明らかにする','守備がうまい人の体の使い方、目の動き、一瞬の判断力、攻撃選手に対する動きとかなどについて調べる','守備の選手がやっている目の使い方などを分析し取り入れてみてプレーしてみる','家で守備集をyoutubeなどでみる。 そして学校で実践してみる','スパイクまたはトレシュー','保体','保体②：校庭','特になし','例えば、冨安選手の守備を分析すると面白いと思います。身体の正対の観点や、目線、重心の低さと出足の鋭さの関係などを分析するとよいと思います（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','6','D','','0','不協和音はどうやって人間にこんなネガティブな気持ちを与えるか、逆になんで不協和音にかまわない人がいるのかを明らかにする','楽器使っていい音と不協和音比べてみる','','','','理科、社会','','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','7','D','','0','本探求なぜ長い間トップクラスで活躍出来るのか','校庭で、サッカーや他のスポーツをしている人の共通点を動画などを撮って分析し、意識していることなどを調べる','スポーツごとに共通している動き、違うスポーツの共通点などを調べる','校庭でスポーツの探求をしている人に許可を取って、動画などを取って、意識していることを聞く','グローブとボ―ル','体育','保体②：校庭','','');
