INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','9','D','','1対1じゃんけん 片方宣言心理戦におけるじゃんけんで原外生徒に勝利する方法とそこから考察する原外生徒の特徴','本探究では1対1じゃんけん 片方宣言心理戦におけるじゃんけんで原外生徒に勝ちやすい方法を明らかにすると共に、原外生徒の性格的な分類と傾向を考える。  （ここでは、1対1のじゃんけんで、他方の人のみがじゃんけんの前に出す手を宣言してじゃんけんを行うゲームを1対1じゃんけん 宣言心理戦と呼ぶことにする）','じゃんけんをして調査を行い、その結果を同じ手を出した人で分類し、その人の特徴を調査し、性格による出しやすい手の傾向を考える。同時に調査対象の原外生徒の手の大きさなどをできたら調査する。','とにかくデータを集めて分析をする。そこからじゃんけんの方法を考えてまたデータを集める。','生徒に協力してもらい、じゃんけんのルールを教えてじゃんけんをする。最初のデータ集めでは、僕が出す手を宣言して、相手には宣言してもらわずにじゃんけんをする。具体的な手をここでは書けないが、すでにあるじゃんけんデータから、宣言する手と出す手を決めてデータを集める。時間がありそうなら宣言する手は全ての手で行う。また、少しでもデータを集めるため、あいこの場合は仕切り直さずそのまま続ける。また、可能なら手の大きさと指の太さなどを測定させてもらう。  その集めたデータをもとに分析をして考察を考える。','すでにあるデータを集めておいてそこから自分の考察を考えてじゃんけんを行う。','数学','数学：３B教室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','10','D','','0','','','夢について具体的に調べる。','','','0','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','11','D','','テンポの違う曲の気持ちの変化','変化した部分をまとめる。','心拍数とか自分で感じる体温などを細かく記録する。','テンションの上がる曲のテンポと心拍数の関係','心拍数がわかるものをつけて、曲を聞く。','ラボの先生に許可をもらう。（スマホ、イヤホン）','保体、音楽','音楽：音楽室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','12','D','','スポーツをすれば頭よくなるかもしれない','実際頭がよくなるのかを明確にする','いろんな種目のスポーツをした後に、いろんな科目の問題を解いてみて前回の自分となにが変わったのか調べる','勉強とスポーツは関係するのか','勉強とスポーツ両方できる人たちに聞きまわる。','勉強道具かもしれない','保体','保体①：体上','自分はどこまで運動ができるのか','学力と競技力には相関関係があると、先行研究で示されているので探してみてください。仮説を持って本調査に臨めるとよいです。例えば、保体で筋肉・骨格の勉強をしたら足が速くなるのかとか（新田）');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','13','D','','自分と絵師さんの違いを調べたい。アタリの種類とか調べたい。','どういう構図が人を引き付けるのかを明らかにする(明らかにするために、近付ける)','自分が好きな構図を試しに書いてみる。','自分が好きな構図を見つけたり多い構図を探す。','色々な構図を探す。','筆記用具、紙。','美術','美術：美術室','自分が描いている構図の傾向について。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','14','D','','ギターのハンマリングとスライドには何のちがいがあるのだろうか','ギター表現技法について','比較する','ギターの技法を自在に操れるようになる','たくさんの種類の曲をやる','ギター、スマホ、イヤホン、アンプ','音楽','音楽：音楽室','ギターなどの持ち込みの許可をもらう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','15','D','','呼吸の仕方や体の動かし方で長距離での脇腹の痛みが軽減されるのか','正しい呼吸や体の動かし方を明らかにする','インターネットで調べる、長距離が得意な友達に聞く、本などで調べてみる','なぜ脇腹が痛くなるのかを明確にする','インターネットで調べる。長距離が得意な人にいろいろ聞いてみる','特になし','理科、保体','理科：第１理科室','そこそこ調べ終わったら図書室に行って本でも何かわかることがないか調べたい','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','16','D','','記憶力が良くなる方法','記憶に残ることの共通点を調べる','印象に残っていることを内容ごとに分類しどのように脳や精神状態に影響しているか調べる。','人が覚えやすいこと、覚えにくいことの違いを調べる。','インターネットで調べる、アンケートをとる','アンケートをつくる','理科、保体、音楽','理科：第１理科室','Form作成','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','17','D','','蚊に刺されなくなる方法','蚊について詳しく調べる','蚊を調べる','蚊に刺されないようにする','蚊について知る','スマホ','理科','理科：第１理科室','','');
