INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','22','D','','反射神経をよくするにはどうすればいいのか','反射神経を上げる方法','いろいろな方法を試す(定規落としてとるやつとか)','反射神経を上げる方法','定規おとしてとる、ボールをとる','定規、ボール','保体理科','保体②：校庭','なし','');
