INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','24','D','','','勉強を楽しくするには','勉強とほかの楽しいこととの違いについて考える','勉強を楽しくできるようにする','ゲームと勉強を交互にやる','なし','理科','理科：第１理科室','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','25','D','','両利きになるには','両手の腕や筋肉の作りにも着目して、左手を上達させる','左手のトレーニング方法をたくさん考える','両手をスムーズにより自然に使えるようにする','左手に普段の生活に加えて筋トレや日常生活の動作を非利き手の方で行う。','なし','保体、CT','','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','26','D','','マイケルジャクソンの歌声をもとに、きれいな声を出すためにはどうすればよいのか考える','美しい音色の出し方、マイケルについて調べ、自分なり考えを明らかにする','マイケルの練習法についてネットで調べ、自分なりに考察する','とりあえず実際に音楽を聴いて、後々決める','自分の考察や意見を取り入れて、楽曲とマッチさせる','スマホとイヤホン','音楽','音楽：音楽室','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','27','D','','服','似合う服とは何か明らかにする','それぞれの骨格やパーソナルカラーはどんな服が似合うのか','','','','理科 美術','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','28','D','','デッサンの上達に必要なもの','本研究では、デッサンにおいて上達のために意識するべきポイントを明らかにする','実際に意識しているポイントについて調査し、実践する','デッサンを上達するための練習方法を明確にし、自分にあった方法を見つける。','実際に藝大や美大を卒業している（または現役の）美術学院のコーチに大切にしていることや経験を聞き、情報を整理して、実践する。','画用紙、（パネル）','美術','美術：美術室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','29','D','','身長を伸ばすには','','','','','','保体','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','30','D','','起き上がることが楽になる方法','いい夢を見た朝は気分がいい。夢の内容はどうやって決められているのか。','夢の内容はどのように決められているのか調べる','目覚まし時計について調べる','どのような音楽にしたら起き上がれるのか。脳に良いのか調べる','ない','理科、音楽、体育','理科：第１理科室','なし','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','31','D','','なんで日焼けをするのか','どうやって日焼けするのか、なんで黒くなるのか、日焼けするとどんなメリットがあるのか、どうやったら白くなるのか','どんな対策が一番効果的かどの日焼け止めが一番焼けにくいか調べる','なんで黒くなるのか、どんな対策、どうして焼けるのか調べる','インターネットで調べる、自分の予想と友達の予想とか聞いてみる','なし','保健、体育、理科、家庭科','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','32','D','','いろいろな心理的行動とそのりゆう','なぜ心理的行動が起こるのか','インターネットで調べてみる','いろいろな心理的行動についてしらべる','インターネットでしらべてみる','なし','理科 社会 保体','保体①：体上','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','33','D','','なぜ、早寝早起きが大切なのか。','早寝早起きは大切なのか、そしてどのぐらいの時間寝たほうかよいのか、明らかにする。','インターネットで調べたり、実際にやってみる（健康に注意しながら）。','早寝早起きの大切さや、睡眠時間はどのくらいが適しているのかを明確にする。','自分で、家でやってみたり、インターネットで調べたりする。','特にない。','理科、保健、数学','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','34','D','','面倒くさいと思わないようにするためには','なぜ面倒くさいと感じるのか、それを明らかにして自分の生活をどう改善できるか。','他の人に聞いたりインターネットで調べたりする。','なぜ面倒くさいと感じるのかを明確にする。','インターネットなどで調べる。友達はどう思っているのかを聞く。','特にない。','理科、保健','理科：第１理科室','','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','35','D','','なぜ人間は鳥のように飛べないのか','翼の必要性や人と鳥の進化の過程での違いを調べる。','インターネットや本を使って調べる。','翼の構造や、人や鳥になるまでの過程を調べ違いを明確にする。','本やインターネットを使って調べる。人と鳥の違いが分かりやすいよう表にまとめる。','特になし。','理科、歴史、保体','理科：第１理科室','表の作成の仕方を覚える。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','36','D','','人が他人と比べる要因とその長所・短所','人と比べてしまうことによって生じるメリット・デメリットを調べる','アンケートとインターネットを用い、グラフにする','アンケート方式でクイズを作成する','問題が難しすぎると実力差が出てしまうので、なるべく実力差が出ない問題を作成する。','アンケート・クイズをformで集めたい。','国語・理科・体育','国語：図書閲覧室','Form作成、許可をもらう','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','37','D','','なぜタイムが落ちるときがあるのか','本探究では、どんな条件でタイムが落ちるのかを調べる（体の仕組みも調べる）。','インターネットで体力について調べる。','全般でタイムが落ちる原因を調べる。','インターネットで調べる。','特にない。','保体、理科、国語（資料）','国語：図書閲覧室','体の仕組み（本とインターネットを使う）に関係があるか調べる。','');
INSERT OR REPLACE INTO entries (grade,cls,no,session,name,col5,col6,col7,col8,col9,col10,col11,col12,col13,teacher_comment) VALUES ('3','C','38','D','','一番集中できる勉強法はなにか','どの勉強法が一番効率的で集中しやすいか調べる','インターネットで集中できない理由を調べる','音楽を聴いて勉強するときのメリットデメリット','インターネットで調べる','なし','理科、音楽','音楽：音楽室','','');
